# -*- coding: utf-8 -*-
"""레터 본문 — 엔진 결과와 구조 선언으로 본문 절을 쓴다 (W7b · 스키마 v13).

`레터.py` 가 만든 맥락(`레터.맥락` — 가정 · 구조 · 세 시나리오 결과 · 민감도 표 · 점검 결과 · 숫자 장부)을 받아 본문 줄 목록을 낸다.
숫자는 모두 `맥.수(키, 꼴)` · `맥.식(식, 꼴)` 로 찍는다 — 장부에 키와 함께 남는다. 저자가 쓴 글(독자층 원고)은 `맥.원고글()` 로 싣는다.
선언하지 않은 갈래는 서술하지 않는다 — 절마다 구조를 보고, 서술한 갈래를 `맥.서술()` 로 남긴다.

절 차례(독자가 읽는 차례 — L2 · 제안 2절) — 요약 · (지난 평가와의 다리) · 실적과 재무상태 · (Narrative) · 평가 방법과 사용 자료 ·
매출 추정 · 영업비용과 영업이익률 · 재투자 · 법인세와 FCFF · 할인율 · Terminal Value · 주주가치와 주당가치 · 시나리오 · 민감도 ·
이 가격이 성립하려면 필요한 가정 · (Narrative 점검) · (평가자의 자리) · 모델 점검 · 평가의 한계 · 평가 모델 파일.
Narrative 의 절 · 문단은 `레터이야기.py` 가 쓴다. 용어는 문서 첫 등장에 병기하고 그 뒤로는 영어만(`용어.병기` — `레터.레터` 가 끝에 한 번).
"""
from __future__ import annotations

import importlib
import io
import json
import os
import re

import 레터이야기

태그뜻 = [
    ("공시", "사업보고서 · 반기보고서의 본문과 주석에 적힌 값을 그대로 쓴 값"),
    ("관측", "공시된 값에서 뽑은 시계열"),
    ("계산", "둘 이상의 공시값을 나누거나 곱해 구한 값"),
    ("회사주장", "IR · 컨퍼런스콜 · 보도자료에서 회사가 밝힌 값(검증되지 않은 회사 쪽 진술)"),
    ("외부평가", "외부 조사기관의 통계 · 전망과 언론 보도"),
    ("판단", "공시 · 외부 자료로 구할 수 없어 평가자가 정한 값"),
    ("기본값", "평가자의 답이 오기 전에 규칙의 기본으로 둔 값(확인 대기)"),
    ("법령", "법 · 시행령 조문에 근거한 값"),
    ("미해결", "두 자료의 값이 다르거나 원문을 열람하지 못해 확정하지 못한 값"),
]
시나리오들 = ("비관", "기준", "낙관")


def _n(x):
    try:
        if x is None or isinstance(x, bool):
            return None
        return float(x)
    except (TypeError, ValueError):
        return None


def _괄호앞(말):
    """조사를 고를 말 — 끝의 따옴표 · 빈칸을 떼고, 끝에 붙은 괄호 덧말 「(…)」 은 떼어 그 앞의 말을 본다
    (「이연법인세부채(순액)를」 · 「가중평균자본비용 (WACC)은」). 괄호만 있으면 괄호 안의 말을 본다."""
    s = ("%s" % (말 or "")).rstrip("`”’\"' ")
    for _ in range(4):
        if not s.endswith(")"):
            break
        깊, i = 0, len(s) - 1
        while i >= 0:
            if s[i] == ")":
                깊 += 1
            elif s[i] == "(":
                깊 -= 1
                if 깊 == 0:
                    break
            i -= 1
        if i < 0:                                            # 짝 없는 「)」 — 떼고 본다
            s = s[:-1].rstrip("`”’\"' ")
            continue
        앞 = s[:i].rstrip("`”’\"' ")
        s = 앞 if 앞 else s[i + 1:-1].strip()
    return s


def _조(말, 있, 없):
    """받침으로 조사를 고른다(괄호 덧말은 레터.조사 와 같이 뗀다. 숫자는 읽는 소리 — 1 · 7 · 8 은 ㄹ 받침).
    순환 import 를 피하려고 여기 둔다."""
    글 = _괄호앞(말).rstrip("」』")                           # 1.1.11 — 낫표로 싼 이름은 안의 말로 고른다(「…법인세」와)
    if not 글:
        return 있
    끝 = 글[-1]
    if "가" <= 끝 <= "힣":
        종 = (ord(끝) - 0xAC00) % 28
        if 종 == 8 and 있.startswith("으로"):
            return 없
        return 없 if 종 == 0 else 있
    if 끝 == "%":
        return 없
    if 끝 in "0123456789":
        if 끝 in "178" and 있.startswith("으로"):
            return 없
        return 있 if 끝 in "013678" else 없
    if 끝.isalpha() and 끝.upper() in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        import 용어 as _용                                     # noqa: PLC0415 — 용어표의 영어 용어는 읽는 소리로(L2)
        표받침 = _용.받침(글)
        if 표받침 == "미정":                                  # 읽는 소리가 정해지지 않은 말(WACC) — 「값」 을 넣어 조사가 바로 붙지 않게
            return " 값" + 있
        if 표받침 is not None:
            return _용.조사고르기(표받침, 있, 없)
        단받침 = _용.영단어받침(글)                              # 1.1.10 — 소문자가 섞인 영문 낱말은 읽는 소리로(iPhone은)
        if 단받침 is not None:
            return _용.조사고르기(단받침, 있, 없)
        if 끝.upper() in "LR" and 있.startswith("으로"):
            return 없
        return 있 if 끝.upper() in "LMNR" else 없
    return 있


def 이다(말):
    return "%s%s" % (말, _조(말, "이다", "다"))


def 입니다(말):
    """서술격 합쇼체(레터 v27 — 레터 독자 글은 합쇼체) — 받침과 무관하게 「입니다」."""
    return "%s입니다" % 말


def 이고(말):
    """서술격 연결형 — 받침과 무관하게 「이고」(1.1.21 — 「643달러고」 는 구어 꼴 · 「입니다」 와 같은 원칙). 읽는 소리가 정해지지 않은 말(WACC)은 「값이고」."""
    조 = _조(말, "이고", "고")
    return "%s%s" % (말, "이고" if 조 == "고" else 조)


def 은(말):
    return "%s%s" % (말, _조(말, "은", "는"))


def 이(말):
    return "%s%s" % (말, _조(말, "이", "가"))


def 을(말):
    return "%s%s" % (말, _조(말, "을", "를"))


def 으로(말):
    return "%s%s" % (말, _조(말, "으로", "로"))


def 과(말):
    return "%s%s" % (말, _조(말, "과", "와"))


def 도(말):
    """「도」 는 받침과 무관하다 — 읽는 소리가 정해지지 않은 말(WACC)에도 붙는다."""
    return "%s도" % 말


def _표(머리, 줄들, 정렬=None):
    정렬 = 정렬 or (["l"] + ["r"] * (len(머리) - 1))
    L = ["| %s |" % " | ".join(머리), "|%s|" % "|".join("---" if a == "l" else "---:" for a in 정렬)]
    for 줄 in 줄들:
        L.append("| %s |" % " | ".join(("%s" % c).replace("|", "·").replace("\n", " ") for c in 줄))
    return L


def 사이설명(맥, x, i):
    """사이 자본거래 표의 「내용」 칸 — `관측.사이자본거래[i].설명`. 1.1.15 — 공시채움 · 판단이 평서체(~넣었다)로 적은 글을 합쇼체로 펴서 싣는다
    (평서체 끝이면 원고 검수가 칸을 비웠다 · 가정의 글은 그대로)."""
    글 = x.get("설명")
    if not (isinstance(글, str) and 글.strip()):
        return ""
    import 원고어투 as _어                                  # noqa: PLC0415 — 1.1.19 숫자 뒤 명사(「1,000주다」 → 「1,000주입니다」 — 「줍니다」 가 아니다)
    return 맥.원고글(_어.합쇼체로(글)[0], "관측.사이자본거래[%d].설명" % i)


def 블록소절(맥, 이름, 줄):
    """레터 v27 6단계 — 추정 블록을 짓는 중(`맥._절글끔`)이면 절에 붙는 보조 분석(설명 문단 · 표 · 표 주석 통째)을 부록 「추정 블록의 근거 표」 의
    제 이름 자리로 보내고 빈 목록을 돌려준다. 옛 조각 나누기는 산문을 버리고 표만 옮겨, 설명 없는 표가 남거나 표 없는 분석 문단이 통째로 사라졌다.
    줄 안의 「### 」 제목은 그 제목으로 소절을 나눈다. 블록이 아니면 그대로."""
    줄 = ["%s" % x for x in (줄 or [])]
    if not any(x.strip() for x in 줄) or not getattr(맥, "_절글끔", False):
        return 줄
    소절들, 지금 = [], [이름, []]
    for x in 줄:
        if x.startswith("### "):
            if any(y.strip() for y in 지금[1]):
                소절들.append(지금)
            지금 = [x[4:].strip(), []]
            continue
        if not 지금[1] and not x.strip():
            continue
        지금[1].append(x)
    if any(y.strip() for y in 지금[1]):
        소절들.append(지금)
    맥._블록소절 = (getattr(맥, "_블록소절", None) or []) + [(a, b + ([""] if b and b[-1].strip() else [])) for a, b in 소절들]
    return []


def _나열(말들, 끝="과"):
    말들 = [m for m in 말들 if m]
    if not 말들:
        return ""
    if len(말들) == 1:
        return 말들[0]
    앞 = " · ".join(말들[:-1])
    if 끝 == "과" and _조(앞, "과", "와").startswith(" "):        # 읽는 소리가 정해지지 않은 말(WACC)로 끝나면 가운뎃점으로만 잇는다
        return " · ".join(말들)
    return "%s%s %s" % (앞, _조(앞, "과", "와"), 말들[-1]) if 끝 == "과" else " · ".join(말들)


# ══════════════════════════════════════════════════════════════════ 손잡이 — 독자가 읽는 이름과 문장 틀

# ── 축 이름 표 — 민감도 · 역산 손잡이(엔진 `민감도` 의 손잡이 꼴: 이름 · 대상 · 방식 · 폭)를 독자가 읽는 이름 · 꼴 · 문장 틀로.
#    대상의 첫 칸으로 고른다. 이름 틀의 {가정} 은 그 가정 번호의 이름(구조의 이름을 넣은 것), {공통} 은 구분 이름을 뗀 공통 이름이다.
#    역산 틀: {이름} {적용} {내재} {변} — 「이 가격이 성립하려면 필요한 가정」 의 문장. 꼴은 장부의 꼴(레터.꼴글).
def _대상꼴(대상):
    """대상 첫 칸의 갈래 — 표의 열쇠."""
    d = "%s" % 대상
    if d == "WACC.예측기간+WACC.영구기간":
        return "WACC"
    if d.startswith("WACC."):
        return "WACC구간" if d.count(".") == 1 else "WACC입력"
    if d in ("영구이익률가감", "매출성장", "목표마진", "비영업할인"):
        return d
    try:
        n = int(d)
    except ValueError:
        return "모름"
    if n == 212:
        return "영구성장률"
    if n == 213:
        return "Normalization"
    if 610 <= n <= 659 and n % 10 == 6:
        return "정상단가"
    if 610 <= n <= 659 and n % 10 in (8, 9):
        return "연도"
    if 610 <= n <= 659 and n % 10 in (0, 1) or 670 <= n <= 699:
        return "판매량"
    if n in (30, 38, 46, 54, 62, 70):
        return "판매량증가율"
    if n in (34, 42, 50, 58, 66):
        return "판매단가변동률"
    if n in (80, 84, 88, 92, 112, 116, 120) or 711 <= n <= 777:
        return "원가줄"
    return "가정"


손잡이표 = {
    # 갈래: (이름 틀, 꼴, 역산 문장 틀)
    "영구성장률": ("영구성장률", "퍼2", "영구성장률이 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "WACC": ("WACC", "퍼2",
             "할인율로 이 가격을 설명하려면 WACC 값이 {적용}에서 {내재_으로} 낮아져야 합니다(예측기간과 영구기간에 같은 크기를 더한 값)."),
    "WACC구간": ("{구간} WACC", "퍼2", "{구간} WACC 값이 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "WACC입력": ("{키} ({구간})", "퍼2", "{이름_은} {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "영구이익률가감": ("영구기간 영업이익률", "퍼1", "영구기간 영업이익률이 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "Normalization": ("Normalization 영업이익률", "퍼1", "Normalization 영업이익률이 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "정상단가": ("{공통}", "지수2", "{이름_은} 적용값 {적용} 대신 {내재}여야 이 가격이 성립합니다(적용값의 {변})."),
    "연도": ("{공통}", "연도", "{이름_이} {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "판매량": ("{가정}", "수1", "{이름_이} 적용값 {적용} 대신 {내재}여야 이 가격이 성립합니다(적용값의 {변})."),
    "판매량증가율": ("{가정}", "퍼1", "{이름_이} {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "판매단가변동률": ("{가정}", "퍼1", "{이름_이} {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "원가줄": ("{가정}", None, "{이름_이} {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "가정": ("{가정}", None, "{이름_은} 적용값 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    "모름": ("{손잡이}", "지수2", "{이름_은} 적용값 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    # 1.1.4 — 브리지 역산 축 「비영업할인」(평가조정 대상 비영업자산의 할인율 — 0 ~ 100%)은 퍼센트 꼴(지수2 「1.00」 이 ⑬ 단위 없는 소수로 걸렸다)
    "비영업할인": ("{손잡이}", "퍼0", "{이름_은} 적용값 {적용} 대신 {내재}여야 이 가격이 성립합니다."),
    # S9-03 — 엔진의 성장 · 마진 역산(같은 엔진 · 같은 영구 계산). 값은 결과(매출 CAGR · 예측 끝 영업이익률)로 읽는다
    "매출성장": ("예측기간 매출 연평균 증가율(CAGR)", "퍼1",
             "예측기간 매출의 연평균 증가율이 {적용} 대신 {내재}여야 이 가격이 성립합니다(매출 줄마다 같은 폭을 더하고 원가 비율 · 재투자 규칙 · Terminal Value의 셈은 모델 그대로)."),
    "목표마진": ("예측 끝 영업이익률", "퍼1",
             "예측 끝 해의 영업이익률이 {적용} 대신 {내재}여야 이 가격이 성립합니다(원가 비율 줄을 걸음으로 줄이고 나머지는 모델 그대로)."),
}
_WACC키말 = {"국채수익률": "국채 수익률", "Rf": "무위험이자율", "베타u": "Unlevered Beta", "ERP": "MRP", "스프레드": "신용스프레드"}


def _손잡이갈래(h):
    대상 = ["%s" % x for x in (h.get("대상") or [])]
    if not 대상:
        return "모름", 대상
    if sorted(대상) == ["WACC.영구기간", "WACC.예측기간"]:
        return "WACC", 대상
    return _대상꼴(대상[0]), 대상


def 손잡이이름(h, 맥):
    """손잡이 → 독자가 읽는 이름(축 이름 표). 가정 번호 하나면 그 가정의 이름, 묶음이면 구분 이름을 뗀 공통 이름(없으면 손잡이 이름)."""
    import 레터 as _L                                       # noqa: PLC0415
    갈래, 대상 = _손잡이갈래(h)
    틀 = 손잡이표[갈래][0]
    가정말 = _L.가정이름(대상[0], 맥.구) if 대상 and 대상[0].isdigit() else None
    공통 = h.get("이름") if len(대상) > 1 else None
    if len(대상) > 1 and all(d.isdigit() and 610 <= int(d) <= 659 for d in 대상) and len({int(d) % 10 for d in 대상}) == 1:
        뗀 = {_L.가정이름(d, 맥.구).replace(_L.구분이름(맥.구, int(d) // 10 - 60) + " ", "", 1) for d in 대상}
        if len(뗀) == 1:                                    # R1b(L5) — 묶음 손잡이도 판매단가 명칭으로(구분마다 이름이 같을 때)
            공통 = 뗀.pop()
    if not 공통 and 가정말:
        공통 = 가정말
        if 대상[0].isdigit() and 610 <= int(대상[0]) <= 659:      # 「DRAM 정상 수준 판매단가 지수」 → 묶음이면 「정상 수준 판매단가 지수」
            s = int(대상[0]) // 10 - 60
            공통 = 가정말.replace(_L.구분이름(맥.구, s) + " ", "", 1) if len(대상) > 1 else 가정말
    부 = 대상[0].split(".") if 대상 else []
    return 틀.format(가정=가정말 or h.get("이름") or "", 공통=공통 or h.get("이름") or "", 손잡이=h.get("이름") or "",
                    구간=부[1] if len(부) > 1 else "", 키=_WACC키말.get(부[2], 부[2]) if len(부) > 2 else "")


def 손잡이꼴(h, 맥):
    import 레터 as _L                                       # noqa: PLC0415
    갈래, 대상 = _손잡이갈래(h)
    꼴 = 손잡이표[갈래][1]
    if 꼴 is None and 대상 and 대상[0].isdigit():
        꼴 = _L.가정꼴(대상[0], 맥.구)
    return 꼴 or "지수2"


def 역산문장(h, 맥, 이름, 적용, 내재, 변):
    """손잡이마다의 역산 문장 틀(축 이름 표의 셋째 칸)."""
    갈래, 대상 = _손잡이갈래(h)
    부 = 대상[0].split(".") if 대상 else []
    return 손잡이표[갈래][2].format(이름=이름, 이름_은=은(이름), 이름_이=이(이름), 적용=적용, 내재=내재, 내재_으로=으로(내재), 변=변,
                                 구간=부[1] if len(부) > 1 else "")


def _범위행(맥, 키):
    """「민:표3:i:폭」 · 「민:요약:i:폭」 의 행이 비대칭 범위 손잡이(엔진 민감도 `범위` — 값 방식이면 그 값, 가산이면 가감)인가 → (행, 키 앞머리) | (None, None).
    범위 손잡이는 폭이 0 이라 「±0.0%p」 로 찍혔다(회차 20261023 NAVER · TSLA) — 범위 행은 옮긴 값(하값 · 상값)으로 읽는다."""
    m = re.match(r"^민:(표3|요약):(\d+):폭$", 키 or "")
    if not m or not isinstance(맥.민, dict):
        return None, None
    표 = 맥.민.get(m.group(1)) or []
    i = int(m.group(2))
    r = 표[i] if i < len(표) else None
    if isinstance(r, dict) and r.get("범위") and _n(r.get("하값")) is not None and _n(r.get("상값")) is not None:
        return r, "민:%s:%d:" % (m.group(1), i)
    return None, None


def _값말(맥, 키, h):
    """손잡이가 옮긴 값 하나를 읽는 꼴로(연도는 꼴 「연도」 — 「2028년」. 1.1.19 — 「수0」 + 「년」 은 「2,028년」 으로 찍혔다)."""
    꼴 = 손잡이꼴(h, 맥)
    return 맥.수(키, "연도") if 꼴 == "연도" else 맥.수(키, 꼴)


def _가감말(맥, 키, h, r):
    """가산 · 배율 범위 손잡이의 가감 하나(부호 붙임) — 「−3.0%p」 · 「+2.0%p」 · 「+1년」 · 「−10.0%」. 값은 장부의 범위 칸(엔진 표3 `범위`)."""
    꼴 = 손잡이꼴(h, 맥)
    if (r.get("방식") or h.get("방식")) == "배율":
        return 맥.수(키, "증1")
    if 꼴.startswith("퍼"):
        return 맥.수(키, "퍼p2" if 꼴 == "퍼2" else "퍼p1")
    v = _n(맥.값(키)) or 0.0
    글 = 맥.수(키, "수0" if 꼴 == "연도" else "지수2")
    글 = ("+" + 글) if v > 0 and not 글.startswith("+") else 글
    return 글 + ("년" if 꼴 == "연도" else "")


def _값방식(r, h):
    return (r.get("방식") or h.get("방식")) == "값"


def 범위폭(맥, 키, h):
    """범위 손잡이의 폭 글 — 값 방식은 옮긴 값의 범위(「8.0%~12.0%」), 가산 · 배율은 가감의 범위(「−3.0%p~+2.0%p」 — 열마다 더한다). 범위가 아니면 None.
    가산 손잡이를 옮긴 값(하값 · 상값)으로 적으면 「2.0%에서 −1.0%로」 처럼 한 값을 바꾼 것으로 읽힌다(회차 20261023 NAVER ★)."""
    r, 앞 = _범위행(맥, 키)
    if not r:
        return None
    if _값방식(r, h):
        return "%s~%s" % (_값말(맥, 앞 + "하값", h), _값말(맥, 앞 + "상값", h))
    return "%s~%s" % (_가감말(맥, 앞 + "범위:0", h, r), _가감말(맥, 앞 + "범위:1", h, r))


def 폭말(h, 키, 맥):
    """문장 속 폭 — 「0.50%p」 꼴(± 없이). 범위 손잡이는 「8.0%~12.0% 사이에서」 · 「−3.0%p~+2.0%p 사이에서」."""
    글 = 범위폭(맥, 키, h)
    if 글:
        return "%s 사이에서" % 글
    return 폭글(h, 키, 맥).lstrip("±")


def 폭글(h, 키, 맥):
    """± 폭을 읽는 꼴로(장부에 적는다) — 비율 가정은 %p, 지수는 그대로, 배율 방식은 %. 범위 손잡이는 옮긴 값의 범위(「8.0%~12.0%」)."""
    글 = 범위폭(맥, 키, h)
    if 글:
        return 글
    꼴 = 손잡이꼴(h, 맥)
    if h.get("방식") == "배율":
        return "±" + 맥.수(키, "퍼1")
    if 꼴.startswith("퍼"):
        return "±" + 맥.수(키, "폭p2" if 꼴 == "퍼2" else "폭p1")
    if 꼴 == "연도":
        return "±" + 맥.수(키, "수0") + "년"
    return "±" + 맥.수(키, "지수2")


# ══════════════════════════════════════════════════════════════════ 독자 층의 눈금 (R1c 뒤)
# 독자 층(3분 레터 · 1~5막)에는 지수 · 배수를 쓰지 않는다. 가격 변수는 눈금 = 100(「웨이퍼당 매출, 2025년 평균 = 100」 — `눈금선언`, 없으면 기준 기간),
# 값은 돈(조 원 · 만 원), 그리고 과거 비교만. 깊이 층(전문가 본편 · 부록)은 지수를 그대로 쓴다. 정상 수준(12번 6s6)은 기준 기간 값
# (표 T:6s7:판매단가지수)이 있으면 = 100 눈금으로 바꾸고, 바꿀 수 없는 지수 · 배수는 독자 층에서 싣지 않는다(깊이 층에 있다).

def 곳(맥, 번):
    """절 번호 → 레터에서 부르는 이름 — 다섯 막 짜임의 막이면 「5막」, 그 밖은 「17절」(통독 v3 상-10 — 막 · 절을 섞어 부르지 않게).
    막 번호는 `레터막.쓰기` 가 맥.막번 에 둔다."""
    return ("%d막" % 번) if 번 in (getattr(맥, "막번", None) or ()) else ("%d절" % 번)


def 독자층(맥):
    """지금 독자 층(3분 레터 · 1~5막)을 쓰는 중인가(`레터막.쓰기` 가 맥.층 을 정한다 — 옛 짜임은 None)."""
    return getattr(맥, "층", None) == "독자"


def 지수꼴인가(꼴):
    return isinstance(꼴, str) and (꼴.startswith("지수") or 꼴 == "배")


def 눈금선언(가정):
    """독자 층 눈금의 기준(통독 v4 — 0_결정 2026-10-16 총괄 판단). `Narrative.독자.눈금` =
    {"이름": 「2025년 평균」, "지수": {구분 번호: 그 기간의 판매단가 지수(엔진 지수와 같은 눈)}, "근거": …} 이면 그 기간 = 100,
    없거나 {"기준": "기준기간"} 이면 엔진의 기준 기간(표 T:6s7:판매단가지수 — 옛 「2026년 2분기 = 100」) = 100. 저자가 키 하나로 되돌린다."""
    N_ = 가정.get("Narrative") if isinstance(가정.get("Narrative"), dict) else {}
    독 = N_.get("독자") if isinstance(N_.get("독자"), dict) else {}
    d = 독.get("눈금")
    if (not isinstance(d, dict) or ("%s" % (d.get("기준") or "")).strip() == "기준기간" or not ("%s" % (d.get("이름") or "")).strip()
            or not isinstance(d.get("지수"), dict)):
        return None
    return d


def 눈금키(맥, s):
    """구분 s 의 눈금 = 100 이 되는 지수의 장부 키 — 선언(N:독자:눈금:지수:s)이 있으면 그것, 없으면 기준 기간(T:6s7:판매단가지수)."""
    가정 = 맥 if isinstance(맥, dict) else 맥.가정
    d = 눈금선언(가정)
    if d and _n(d["지수"].get("%d" % s)):
        return "N:독자:눈금:지수:%d" % s
    return "T:6%d7:판매단가지수" % s


def 눈금이름(맥, x):
    """구분 x 의 눈금 이름 — 선언이 있으면 「2025년 평균」, 없으면 기준 기간 이름(「2026년 2분기」)."""
    d = 눈금선언(맥.가정)
    if d and _n(d["지수"].get("%s" % x.get("번호"))):
        return ("%s" % d["이름"]).strip()
    return _기준기간이름(맥, x)


def 눈금따로(맥, s):
    """눈금이 기준 기간과 다른가(선언이 있는가) — 그때만 「기준 기간이 이 눈금으로 얼마」를 적는다."""
    return 눈금키(맥, s).startswith("N:")


def 정상수준구분(맥, 번):
    """12번 정상 수준 판매단가 지수(6s6)이고 그 구분의 눈금 값(선언 또는 T:6s7:판매단가지수)이 있으면 구분 번호 s, 아니면 None."""
    m = re.fullmatch(r"6([1-5])6", ("%s" % 번).strip())
    if not m:
        return None
    s = int(m.group(1))
    return s if _n(맥.값(눈금키(맥, s))) and _n(맥.값("T:6%d7:판매단가지수" % s)) else None


def 백글(맥, 식, s):
    """구분 s 의 지수(키 또는 식) → 눈금 = 100 의 글(「91」 — 장부에 식으로)."""
    return 맥.식(["×", ["÷", 식, 눈금키(맥, s)], 100], "수0")


def 백이름(맥, 들):
    """[(구분 s, 글)] → 「범용 DRAM 33 · NAND 22」(하나면 「33」)."""
    import 레터 as _L                                       # noqa: PLC0415
    if len(들) == 1:
        return 들[0][1]
    import 레터3분                                           # noqa: PLC0415
    return 레터3분.같은값한번([_L.구분이름(맥.구, s) for s, _g in 들], [g for _s, g in 들])      # v4d — 같은 값이면 한 번만


def 백폭(맥, i, h):
    """민감도 표 Ⅲ 줄 i 의 손잡이가 정상 수준(6s6)만 움직이면 그 폭을 기준 기간 = 100 눈금으로 →
    {"기" · "하" · "상": 「범용 DRAM 33 · NAND 22」, "하길" · "상길": 「범용 DRAM 33 → 31 · NAND 22 → 21」, "기간": 「2026년 2분기」, "구분": [s]}.
    가산 · 배율 방식만(값 방식은 구분마다 갈라 적을 수 없다). 바꿀 수 없으면 None."""
    import 레터 as _L                                       # noqa: PLC0415
    대 = ["%s" % x for x in h.get("대상") or []]
    구들 = [정상수준구분(맥, d) for d in 대]
    방식 = h.get("방식") or "가산"
    if not 대 or None in 구들 or 방식 not in ("가산", "배율") or any(_n(맥.값("S:%s:기준" % d)) is None for d in 대):
        return None
    폭 = "민:표3:%d:폭" % i
    if _n(맥.값(폭)) is None:
        return None

    def 식(d, 쪽):
        b = "S:%s:기준" % d
        if 쪽 == "기":
            return b
        if 방식 == "배율":
            return ["×", b, ["−", 1, 폭] if 쪽 == "하" else ["합", 1, 폭]]
        return ["−", b, 폭] if 쪽 == "하" else ["합", b, 폭]
    글 = {쪽: [(s, 백글(맥, 식(d, 쪽), s)) for d, s in zip(대, 구들)] for 쪽 in ("기", "하", "상")}
    낸 = {쪽: 백이름(맥, 글[쪽]) for 쪽 in ("기", "하", "상")}
    for 쪽 in ("하", "상"):
        짝 = [(s, "%s → %s" % (a, b)) for (s, a), (_s, b) in zip(글["기"], 글[쪽])]
        낸[쪽 + "길"] = 백이름(맥, 짝)
    x0 = next((x for x in 맥.구.get("매출구분") or [] if x.get("번호") == 구들[0]), {})
    낸["기간"] = 눈금이름(맥, x0)
    낸["구분"] = 구들
    return 낸


def 독자손잡이이름(맥, h):
    """독자 층의 손잡이 이름 — 정상 수준만 움직이는 손잡이이고 그 구분들이 3분 레터의 바닥 구분과 같으면 「웨이퍼 한 장으로 버는 돈의 바닥」,
    아니면 손잡이 이름 그대로."""
    import 레터3분                                           # noqa: PLC0415
    대 = ["%s" % x for x in h.get("대상") or []]
    구들 = [정상수준구분(맥, d) for d in 대]
    b = 레터3분.바닥(맥)
    if 대 and None not in 구들 and b and sorted(구들) == sorted(s for s, _x in b["구분"]):
        return "%s의 정상 수준" % 레터3분.가격말(맥, b)
    return 손잡이이름(h, 맥)


def _수글(v, 자리):
    return ("%." + str(자리) + "f") % v


def 꼴글표(v, 맥):
    import 레터 as _L                                       # noqa: PLC0415
    return _L.금액글(v, 맥.메타)


# ══════════════════════════════════════════════════════════════════ 절

def _머리(맥):
    회사 = ("%s" % (맥.메타.get("회사명") or "평가 대상 회사")).strip()
    기준일 = ("%s" % (맥.메타.get("평가기준일") or "")).strip()
    통 = 맥.메타.get("표시통화") or "KRW"
    표기 = "조 원 · 억 원" if ("%s" % 통).upper() == "KRW" else "억 %s" % ({"USD": "달러", "EUR": "유로", "JPY": "엔", "TWD": "대만달러"}.get(("%s" % 통).upper(), 통))
    L = ["# %s 가치평가" % 회사, ""]
    덧 = "".join(" · %s %s" % (말, ("%s" % 맥.메타[k]).strip()) for 말, k in (("레터 작성", "작성일"),)
                 if ("%s" % (맥.메타.get(k) or "")).strip())        # 통독 v3 중6 — 작성일(가정 확정일은 깊이 층 방법 절로 — 통독 v4 중-15)
    재 = (" · 재무 자료 기준일 %s" % 재무날(맥)) if 이월판(맥) else ""     # 2026-10-25 날짜 둘 — 두 날짜를 나란히(IVS 101 · 106)
    L.append("평가기준일 %s%s · DCF · 금액 표기 %s%s" % (기준일, 재, 표기, 덧))
    L.append("")
    if 맥.견본:
        곳 = []
        가성 = 맥.가성 if isinstance(맥.가성, dict) else {}
        if 가성.get("견본") and (가성.get("증설") or 가성.get("조합")) and 맥.절.get("역산"):
            곳.append("「이 가격이 성립하려면 필요한 가정」의 기준에서 뺀 증설 · 조합 사례")
        if isinstance(맥.부록, dict) and 맥.부록.get("견본"):
            곳.append("자본비용 대안 산정 방법 · 평가기준일 뒤 자료(부록 B · G)")
        if isinstance(맥.가정.get("Narrative"), dict) and 맥.가정["Narrative"].get("견본"):
            곳.append("Narrative의 글(요약 첫 문단 · Narrative 절 · Narrative 점검 · 평가자의 자리 · 3분 레터의 신호등과 그림 1 의 가로선)")
        L.append("> 견본 — 이 레터는 짜임을 보이기 위한 견본입니다. %s" % (
            ("%s의 내용은 자리표시이며 납품본에서 바뀝니다." % _나열(곳)) if 곳 else "자리표시가 든 칸은 납품본에서 바뀝니다."))
        L.append("")
    return L


def _주당표(맥, 종가줄=True):
    D = "R:%s:2.DCF:%s"
    줄들 = [["주당가치"] + [맥.수(D % (s, "68"), "주당") for s in 시나리오들],
           ["영업가치"] + [맥.수(D % (s, "58"), "금액") for s in 시나리오들],
           ["주주가치"] + [맥.수(D % (s, "66"), "금액") for s in 시나리오들],
           ["Terminal Value 비중 (영업가치 대비)"] + [맥.수("R:%s:요약:영구가치비중" % s, "퍼1") for s in 시나리오들],
           ["최종 예측 연도(%s) 영업이익률" % 맥.열말(맥.끝예측)] + [맥.수("R:%s:요약:마지막해영업이익률" % s, "퍼1") for s in 시나리오들],
           ["영구기간 영업이익률"] + [맥.수(D % (s, "42"), "퍼1") for s in 시나리오들]]
    if 맥.종가키 and 종가줄:
        줄들.append(["주당가치 ÷ %s" % 종가말(맥)] + [맥.식(["÷", D % (s, "68"), 맥.종가키], "배") for s in 시나리오들])
    return _표(["구분", "비관", "기준", "낙관"], 줄들)


def 요약절(맥, 번):
    """1. 요약 — R1b(L12 · L16): 값의 범위와 종가가 요구하는 조건을 한 표에 나란히, 아래로 틀릴 길 한 줄, 주당가치는 반올림."""
    L = ["## %d. 요약" % 번, ""]
    이야기 = 레터이야기.요약문단(맥)
    if 이야기:
        L += 이야기
    else:
        맥.알림.append("Narrative(계기 · 질문 · 한줄)가 없다 — 요약을 계산 사실로만 열었다")
        회사 = ("%s" % (맥.메타.get("회사명") or "평가 대상 회사")).strip()
        길이 = 맥.수("R:기준:요약:예측기간길이합", "수1")
        다음해 = (맥.회계연도(맥.끝예측) or 0) + 1
        주당 = 맥.수("R:기준:2.DCF:68", "어림주당")
        할 = ("재무 자료 기준일의 현재가치로 할인한 뒤 평가기준일로 이월했습니다" if 이월판(맥) else "평가기준일의 현재가치로 할인했습니다")
        L.append("%s의 FCFF를 %s부터 %s까지 %s년 동안 추정했습니다. %d년 이후의 가치는 Terminal Value로 산정해 %s. "
                 "기준 시나리오의 주당가치는 약 %s." % (회사, 맥.열말(맥.첫예측), 맥.열말(맥.끝예측), 길이, 다음해, 할, 입니다(주당)))
        L.append("")
        음수 = [s for s in 시나리오들 if (_n(맥.값("R:%s:2.DCF:68" % s)) or 0) < 0]
        if 음수:
            L.append("%s 시나리오의 주주가치는 음수입니다. 주식의 가치는 0 아래로 내려가지 않으므로, 이 값은 그 시나리오에서 이자부부채와 차감 항목이 "
                     "영업가치 · 비영업자산 · 현금의 합보다 크다는 뜻입니다." % " · ".join(음수))
            L.append("")
        if 맥.종가키:
            L.append("%s %s. 다른 가정을 그대로 두고 가정 하나만 바꿔 이 가격이 성립하는 값을 분석했습니다(%d절)." % (
                은(종가말(맥)), 입니다(맥.수(맥.종가키, "어림주당")), 맥.절["역산"]))
            L.append("")
    L += _나란히표(맥)
    L += _아래길(맥)
    L += _요약민감(맥)
    맥.서술("요약")
    return L


def _나란히표(맥):
    """R1b(L12) — 세 시나리오의 값과 종가가 요구하는 값을 한 표에. 마지막 칸은 정상 수준만 풀어 종가를 맞춘 세계(다른 가정은 기준)."""
    import 레터3분                                           # noqa: PLC0415
    b = 레터3분.바닥(맥)
    마지막 = bool(맥.종가키 and b and b["풀이"])
    머 = ["구분", "비관", "기준", "낙관"] + (["%s 요구하는 값" % 이(종가말(맥))] if 마지막 else [])
    D = "R:%s:2.DCF:%s"
    줄들 = [["주당가치"] + [맥.수(D % (s, "68"), "어림주당") for s in 시나리오들] + ([맥.수(맥.종가키, "어림주당")] if 마지막 else [])]
    if b:
        import 레터 as _L                                   # noqa: PLC0415
        x0 = dict(b["구분"])[b["주"]]
        기간 = 눈금이름(맥, x0)
        이름 = "정상 수준 %s" % (("%s" % (x0.get("판매단가명칭") or "")).strip() or "판매단가 지수")
        구들 = [s for s, _x in b["구분"]]
        같음 = all(len({round(_n(_L._시점값(맥.가정, "6%d6" % s, 시)) or 0, 12) for s in 구들}) == 1 for 시 in 시나리오들)
        if 같음 and not 독자층(맥):                         # 독자 층은 지수 줄 없이 기준 기간 = 100 줄만
            줄들.append(["%s (%s)" % (이름, " · ".join(_L.구분이름(맥.구, s) for s in 구들))]
                      + [맥.수("S:6%d6:%s" % (구들[0], s), "지수2") for s in 시나리오들]
                      + ([맥.식(레터3분._내(b, 구들[0]), "지수2") if b["방식"] != "값" else 맥.수("민:표4:줄:%d:내재값" % b["i"], "지수2")] if 마지막 else []))
        줄들.append(["정상 수준 (%s = 100, %s)" % (기간, " · ".join(_L.구분이름(맥.구, s) for s in 구들))]
                  + [" · ".join(레터3분._백(맥, "S:6%d6:%s" % (s, 시), s) for s in 구들) for 시 in 시나리오들]
                  + ([" · ".join(레터3분._백(맥, 레터3분._내(b, s), s) for s in 구들)] if 마지막 else []))
    독 = 독자층(맥)                                         # 통독 v3 중-13 — 독자 층은 「영구기간 · 최종 예측 연도」 대신 해로
    다음해 = (맥.회계연도(맥.끝예측) or 0) + 1
    줄들.append([("%d년 뒤 영업이익률" % 다음해) if 독 else "영구기간 영업이익률"] + [맥.수(D % (s, "42"), "퍼1") for s in 시나리오들]
              + ([맥.수("가:역셀:%d:2.DCF:42" % b["i"], "퍼1")] if 마지막 else []))
    줄들.append([("%s 영업이익률" if 독 else "최종 예측 연도(%s) 영업이익률") % 맥.열말(맥.끝예측)]
              + [맥.수("R:%s:요약:마지막해영업이익률" % s, "퍼1") for s in 시나리오들]
              + ([맥.수("가:역셀:%d:요약:마지막해영업이익률" % b["i"], "퍼1")] if 마지막 else []))
    L = ["**표. 세 시나리오의 산정 결과와 %s 성립하는 조건**" % 이(종가말(맥)) if 마지막 else "**표. 세 시나리오의 산정 결과**", ""]   # 레터 v27 — 표 제목(레터.py 가 번호를 매긴다)
    L += _표(머, 줄들)
    L.append("")
    # 1.1.20 — 같은 정의(「기준 시나리오는 … 기댓값이 아닙니다」)가 시나리오 절(폭포)에 이미 섰으면 되풀이하지 않는다(한 레터에 두 번 — 서른 곳)
    글 = "" if getattr(맥, "_기준뜻", False) else "기준 시나리오는 세 시나리오의 가운데 시나리오이며, 확률로 가중한 기댓값이 아닙니다."
    if b and not 독자층(맥):                                # 기준 기간의 지수 값은 깊이 층에만(독자 층은 위 표의 = 100 줄)
        import 레터 as _L                                   # noqa: PLC0415
        x0 = dict(b["구분"])[b["주"]]
        명 = ("%s" % (x0.get("판매단가명칭") or "")).strip() or "판매단가 지수"
        N = 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}
        기준말 = 맥.원고글((N.get("독자") or {}).get("지수기준"), "Narrative.독자.지수기준") if isinstance(N.get("독자"), dict) and (N.get("독자") or {}).get("지수기준") else ""
        값들 = " · ".join("%s %s" % (_L.구분이름(맥.구, s), 맥.수("T:6%d7:판매단가지수" % s, "지수2")) for s, _x in b["구분"])
        L += ["%s %s 잰 지수이며, %s의 값은 %s." % (은(명), 으로(기준말.rstrip(".")), _기준기간이름(맥, x0), 입니다(값들))
              if 기준말 else "%s의 %s %s." % (_기준기간이름(맥, x0), 은(명), 입니다(값들)), ""]
    if 독:                                                  # 통독 v3 중-12 — 같은 문장은 3막에 한 번(독자 층)
        글 = ""
    if 마지막:
        글 = ("맨 오른쪽 값은 다른 가정을 기준 시나리오대로 두고 정상 수준만 바꿔 주당가치가 이 가격과 같아지게 한 값입니다. " + 글).strip()
    if 글:
        L += [글, ""]
    return L


def _아래길(맥):
    """R1b(L12) — 값이 아래로 틀릴 길 한 줄: 민감도 표 Ⅲ 에서 값을 낮추는 쪽(크기 차례로 셋) · 보조 시나리오(R1a) · 저자 글(Narrative.틀림.아래)."""
    import 레터3분                                           # noqa: PLC0415
    쪽 = []
    for i, r in enumerate((맥.민 or {}).get("표3") or []):
        기 = _n(r.get("기준"))
        후보 = [(k, _n(r.get(k))) for k in ("하", "상") if _n(r.get(k)) is not None and 기 and _n(r.get(k)) < 기]
        if not 후보:
            continue
        k, v = min(후보, key=lambda t: t[1])
        h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
        쪽.append((v / 기 - 1, i, k, h))
    쪽.sort(key=lambda t: t[0])
    글들 = []
    독자 = 독자층(맥)
    if 독자:                                                 # 독자 층 — 지수 폭은 기준 기간 = 100 눈금으로, 바꿀 수 없는 지수 손잡이는 뺀다
        쪽 = [t for t in 쪽 if 백폭(맥, t[1], t[3]) or not (지수꼴인가(손잡이꼴(t[3], 맥)) and t[3].get("방식") != "배율")]
    for _크기, i, k, h in 쪽[:3]:
        값글 = "%s(%s)" % (맥.수("민:표3:%d:%s" % (i, k), "어림주당"), 맥.식(["괴리", "민:표3:%d:%s" % (i, k), "R:기준:2.DCF:68"], "증1"))
        백 = 백폭(맥, i, h) if 독자 else None
        if 백:
            이름 = 독자손잡이이름(맥, h)
            글들.append("%s(%s = 100)%s %s %s %s" % (이름, 백["기간"], 이(이름)[len(이름):], 으로(백[k + "길"]),
                                               "내려가면" if k == "하" else "올라가면", 값글))
            continue
        이름 = 손잡이이름(h, 맥)
        꼴 = 손잡이꼴(h, 맥)
        r범, 앞 = _범위행(맥, "민:표3:%d:폭" % i)
        if r범 and _값방식(r범, h):                          # 값 방식 범위 — 옮긴 값으로(「±0.0%p 낮으면」 이 아니라 「8.0%에서 12.0%로 바뀌면」)
            글들.append("%s %s에서 %s 바뀌면 %s" % (이(이름), _값말(맥, 앞 + "기준값", h), 으로(_값말(맥, 앞 + k + "값", h)), 값글))
            continue
        if r범:                                             # 가산 · 배율 범위 — 열마다 더한 가감으로(「3.0%p 낮으면」)
            j = 0 if k == "하" else 1
            d = _n((r범.get("범위") or [0, 0])[j]) or 0.0
            글들.append("%s %s %s %s" % (이(이름), _가감말(맥, 앞 + "범위:%d" % j, h, r범).lstrip("+−-"), "낮으면" if d < 0 else "높으면", 값글))
            continue
        if 독자 and 꼴.startswith("퍼") and h.get("방식") != "배율":   # 통독 v3 하-9 — 「0.50%p 높으면」 대신 「10.8%에서 11.3%로 높으면」
            기키, 폭키 = "민:표3:%d:기준값" % i, "민:표3:%d:폭" % i
            새 = 맥.식(["−" if k == "하" else "합", 기키, 폭키], "퍼1")
            글들.append("%s %s에서 %s %s %s" % (이(이름), 맥.수(기키, "퍼1"), 으로(새), "낮으면" if k == "하" else "높으면", 값글))
            continue
        폭 = 폭글(h, "민:표3:%d:폭" % i, 맥).lstrip("±")
        글들.append("%s %s %s %s" % (이(이름), 폭, "낮으면" if k == "하" else "높으면", 값글))
    for 이름, 키 in 레터3분.보조시나리오들(맥):
        if (_n(맥.값(키)) or 0) < (_n(맥.값("R:기준:2.DCF:68")) or 0):
            글들.append("보조 시나리오 %s의 주당가치는 %s" % (이름, 맥.수(키, "어림주당")))
    N = 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}
    틀 = N.get("틀림") if isinstance(N.get("틀림"), dict) else {}
    아래 = 레터이야기.펴기(맥, 틀.get("아래"), "Narrative.틀림.아래") if 틀.get("아래") else ""
    if not 글들 and not 아래:
        return []
    # 1.1.20 — 머리 문장(「주당가치가 기준 시나리오보다 낮아지는 경우도 있습니다」 — 스물두 곳 같은 글)은 뒤에 값이 오면 싣지 않는다(값 문장이 그 뜻이다)
    문 = "" if 글들 else "주당가치가 기준 시나리오보다 낮아지는 경우도 있습니다."
    if 글들:
        앞수 = 1 if 독자 and 쪽 and 백폭(맥, 쪽[0][1], 쪽[0][3]) else 2       # 눈금 문장은 길어 홀로 한 문장
        문 += "다른 가정을 그대로 둘 때 %s." % 입니다(", ".join(글들[:앞수]))
        if len(글들) > 앞수:
            문 += " %s." % 입니다(", ".join(글들[앞수:]))
    if 아래:
        문 += " " + (아래 if 아래.endswith(".") else 아래 + ".")
    return [문, ""]


def _요약민감(맥):
    상위 = _민감도순(맥, 어림=True)[:4]
    if not 상위:
        return []
    L = ["**표. 기준 시나리오에서 주당가치를 크게 좌우하는 가정(전체는 %d절)**" % 맥.절["민감도"], ""]
    L += _표(["가정", "변동 폭", "낮출 때", "높일 때"], [[이름, 폭, 하, 상] for 이름, 폭, 하, 상, _크기 in 상위], ["l", "r", "r", "r"])
    L.append("")
    return L


막힘각주 = "「—」는 그 가정 조합으로는 주당가치를 계산할 수 없는 경우입니다. 영구성장률이 영구기간 WACC 이상이거나 영구기간 ROIC이 0 이하인 조합이 이에 해당합니다."


def _표3칸(맥, i, 쪽, 어림=False):
    """표 Ⅲ 한 칸 — 「주당가치 (기준 대비)」. 엔진이 막은 칸(「해당 없음」 글 · 값 없음)은 「—」. 어림 = 요약의 반올림 꼴(R1b · L16)."""
    if _n((맥.민["표3"][i] or {}).get(쪽)) is None:
        return "—"
    return "%s (%s)" % (맥.수("민:표3:%d:%s" % (i, 쪽), "어림주당" if 어림 else "주당"),
                        맥.식(["괴리", "민:표3:%d:%s" % (i, 쪽), "R:기준:2.DCF:68"], "증1"))


def _민감도순(맥, 어림=False):
    """표 Ⅲ(손잡이마다 ± 폭) — 주당가치 변화가 큰 차례. [(이름, 폭글, 낮출 때 글, 높일 때 글, 크기)]. 막힌 칸은 「—」."""
    표3 = 맥.민["표3"]
    낸 = []
    for i, r in enumerate(표3):
        기준 = _n(r.get("기준"))
        쪽값 = [_n(r.get(k)) for k in ("하", "상")]
        if not 기준 or all(v is None for v in 쪽값):
            continue
        h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
        크기 = max(abs(v / 기준 - 1) for v in 쪽값 if v is not None)
        낸.append((손잡이이름(h, 맥), 폭글(h, "민:표3:%d:폭" % i, 맥), _표3칸(맥, i, "하", 어림), _표3칸(맥, i, "상", 어림), 크기))
    return sorted(낸, key=lambda t: -t[4])


def _역산줄(맥):
    """표 Ⅳ — [(이름, 적용값 글, 내재값 글, 변화 글, 비고 글)], 풀이가 없는 손잡이 이름 목록.
    엔진이 풀이를 냈는데 뜻 범위 밖이면 「비고」에 까닭을 적는다(검증 ② 뒤 S4 — 예: 무위험이자율보다 낮음 · 100% 초과).
    레터는 그 비고를 엔진 글로 그대로 싣는다(장부에 키와 함께 — 게이트가 다시 계산해 맞댄다). 풀이가 없을 때만 「값이 없다」."""
    줄, 없음, 손 = [], [], []
    맥.역산없음손잡이 = []
    for i, r in enumerate(맥.민["표4"]["줄"]):
        h = {"이름": r["이름"], "대상": r["대상"]}
        이름 = 손잡이이름(h, 맥)
        꼴 = 손잡이꼴(h, 맥)
        if _n(r.get("내재값")) is None:
            없음.append(이름)
            맥.역산없음손잡이 = getattr(맥, "역산없음손잡이", []) + [h]
            continue
        비고 = 맥.엔진글("민:표4:줄:%d:비고" % i) if ("%s" % (r.get("비고") or "")).strip() else ""
        적용 = 맥.수("민:표4:줄:%d:적용값" % i, 꼴)
        내재 = 맥.수("민:표4:줄:%d:내재값" % i, 꼴 if 꼴 != "지수2" else "지수2")
        줄.append((이름, 적용, 내재, "", 비고))          # 변화(배 · %p)는 싣는 곳에서 셈한다 — 장부에는 레터에 찍힌 글만
        손.append(h)
    맥.역산손잡이 = 손
    맥.서술("역산")
    return 줄, 없음


def 개요문단(맥):
    """`서사`(①②③ … 의 사전 또는 글) → 실을 문단. 검수에 걸리는 문단은 싣지 않고 저자에게 알린다."""
    서사 = 맥.가정.get("서사")
    글들 = []
    if isinstance(서사, dict):
        글들 = [v for _k, v in sorted(서사.items()) if isinstance(v, str) and v.strip()]
    elif isinstance(서사, str) and 서사.strip():
        글들 = [x for x in re.split(r"\n\s*\n", 서사) if x.strip()]
    return [g for g in (맥.원고글(x.strip(), "서사") for x in 글들) if g]


def 개요절(맥, 번):
    L = ["## %d. 사업 개요" % 번, ""]
    for g in 맥.개요:
        L.append(g)
        L.append("")
    return L


def 재무범위(맥):
    """「연결」 · 「별도」 — 국내 회사가 연결 재무 원천 없이 별도만 받았으면 별도(종속기업이 없어 연결을 짓지 않는 회사 · 1.1.10).
    가정 곁 `_raw` 의 `dart_재무_연결_*` · `dart_재무_별도_*` 로 가른다. 가정 경로가 없거나 판단할 원천이 없으면 연결."""
    import glob as _g                                       # noqa: PLC0415
    경 = getattr(맥, "경로", None)
    if not 경:
        return "연결"
    raw = os.path.join(os.path.dirname(os.path.abspath(경)), "_raw")
    if _g.glob(os.path.join(raw, "dart_재무_별도_*.json")) and not _g.glob(os.path.join(raw, "dart_재무_연결_*.json")):
        return "별도"
    return "연결"


def 실적절(맥, 번):
    L = ["## %d. 실적과 재무상태" % 번, ""]
    열 = 맥.실적열
    부분 = [c for c in 열 if (맥.속성.get(c, {}).get("개월") or 12) != 12]
    import 레터 as _L                                       # noqa: PLC0415 — 개월 글(부동소수 꼬리 없이 · 1.1.9)
    L.append("**표. %s재무제표 실적**" % 재무범위(맥))       # 레터 v27 — 표 제목(번호는 레터.py) · 부분 기간의 개월은 표 주석으로
    L.append("")
    D = "R:기준:2.DCF:%s:%s"
    줄들 = [["매출액"] + [맥.수(D % ("11", c), "금액") for c in 열],
           ["영업이익"] + [맥.수(D % ("15", c), "금액") for c in 열],
           ["영업이익률"] + [맥.식(["÷", D % ("15", c), D % ("11", c)], "퍼1") for c in 열],
           ["감가상각비 및 무형자산상각비"] + [맥.수(D % ("16", c), "금액") for c in 열],
           ["EBITDA"] + [맥.수(D % ("17", c), "금액") for c in 열]]
    if any(_n((맥.기["8.CapEx"].get("31") or {}).get(c)) is not None for c in 열):
        줄들.append(["CAPEX"] + [맥.수("R:기준:8.CapEx:31:%s" % c, "금액") if _n((맥.기["8.CapEx"].get("31") or {}).get(c)) is not None else "—" for c in 열])
    if any(_n((맥.기["9.WC"].get("14") or {}).get(c)) is not None for c in 열):
        줄들.append(["순운전자본 (기말)"] + [맥.수("R:기준:9.WC:14:%s" % c, "금액") if _n((맥.기["9.WC"].get("14") or {}).get(c)) is not None else "—" for c in 열])
    L += _표(["구분"] + list(열), 줄들)
    L.append("")
    if 부분:
        L += [" ".join("%s 연간이 아닌 %s개월 동안의 실적입니다." % (은(맥.표기(c)), _L.개월글(맥.속성[c]["개월"])) for c in 부분), ""]   # 레터 v27 — 표 주석
    N = "R:기준:11.NOA"
    순 = _n(맥.값(N + ":31:순평가"))
    리스 = (맥.가정.get("스위치") or {}).get("리스부채포함", "포함") != "제외"
    if 리스 and 맥.기준일열:                                 # 장부에 리스부채가 없으면(13번 39 · 47 이 0 · 빈칸) 「(리스부채 포함)」 을 달지 않는다(부록 C 와 같은 판정)
        리스 = sum(abs(_n(((맥.가정.get("원천") or {}).get(k) or {}).get(맥.기준일열)) or 0.0) for k in ("39", "47")) > 0
    if 순 is not None:
        L.append("%s 현재 현금 및 단기금융자산은 %s, 이자부부채%s는 %s. %s"
                 % (재무날말(맥), 맥.수(N + ":21:순평가", "금액"), "(리스부채 포함)" if 리스 else "", 입니다(맥.수(N + ":30:순평가", "금액")),
                    ("순현금은 %s." % 입니다(맥.식(["음", N + ":31:순평가"], "금액"))) if 순 < 0 else ("순차입금은 %s." % 입니다(맥.수(N + ":31:순평가", "금액")))))
        L.append("")
    사실 = ((맥.가정.get("관측") or {}).get("사실")) or []
    줄들 = [[맥.원고글(x.get("항목")), 맥.원고글(x.get("값")), 맥.원고글(x.get("비교") or ""), 맥.원고글(x.get("출처") or "")]
           for x in 사실 if isinstance(x, dict) and ("%s" % (x.get("항목") or "")).strip()]
    if 줄들:
        L.append("**표. 재무제표 주석과 공시에서 확인한 사실**")
        L.append("")
        L += _표(["항목", "값", "비교", "출처"], 줄들, ["l", "l", "l", "l"])
        L.append("")
    return L


def 방법절(맥, 번):
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. 평가 방법과 사용 자료" % 번, ""]
    구 = 맥.구
    덧 = []
    미지급 = (구.get("운전자본") or {}).get("미지급항목") or []
    if 미지급 and "111" in 맥.기["2.DCF"]:
        덧.append("미지급 항목 증감을 더했습니다. 미지급 항목 증감은 %s 현재 미지급된 %s의 잔액 변화입니다." % (
            재무날말(맥), _나열([x.get("이름") for x in 미지급])))
        맥.서술("운전자본.미지급")
    한시 = [x for x in 구.get("한시적현금흐름") or [] if x.get("손익반영") == "없음"]
    if 한시 and "112" in 맥.기["2.DCF"]:
        # 1.1.11 — 이름을 낫표로 싼다(실측: 「한시적 현금흐름 결손 법인 미상계로 더 내는 법인세와 …」 — 이름이 문장에 녹아 읽히지 않았다)
        덧.append("손익을 거치지 않는 한시적 현금흐름인 %s 세후 금액으로 더했습니다." % 도(_나열(["「%s」" % x.get("이름") for x in 한시 if x.get("이름")])))
        맥.서술("한시적.손익밖", *["한시적.%d" % x["번호"] for x in 한시])
    L.append("FCFF는 NOPLAT에 감가상각비 및 무형자산상각비를 더하고 CAPEX와 순운전자본 증가를 뺀 금액입니다."
             + "".join(" " + (("여기에 " + x) if i == 0 else x) for i, x in enumerate(덧)))
    L.append("")
    # 1.1.20 — 할인 시점 · 기간 · 주주가치 · 주당가치 · 직접 입력한 가정 수를 문장 다섯(서른 곳 같은 꼴의 방법 설명 · 원칙 12)에서 「설정」 표로 옮겼다.
    # 값 · 판정은 표 칸에 그대로 남고, 회사마다 다른 값(Terminal Value 할인 시점을 바꾼 차이)만 표 설명 문장으로 둔다
    스 = 맥.가정.get("스위치") or {}
    기중 = (스.get("현금흐름발생시점") or "기중") == "기중"
    영기중 = (스.get("영구가치할인시점") or "기말") == "기중"
    설정 = [["예측기간 현금흐름의 할인 시점", "각 기간의 %s" % ("중간" if 기중 else "말")],      # 표 칸은 짧게(⑬ 표 칸 길이)
          ["Terminal Value의 할인 시점", "최종 예측 연도 %s" % ("중간" if 영기중 else "말")]]
    수렴 = list(맥.묶음.get("수렴") or [])
    설정.append(["실적", ("%s ~ %s" % (맥.열말(맥.실적열[0]), 맥.열말(맥.실적열[-1]))) if len(맥.실적열) > 1 else " · ".join(맥.열말(c) for c in 맥.실적열)])
    설정.append(["예측기간", "%s ~ %s" % (맥.열말(맥.첫예측), 맥.열말(맥.끝예측))])
    if 수렴:
        설정.append(["수렴 구간(상세 예측과 영구기간 사이)", " · ".join(맥.열말(c) for c in 수렴)])
    설정.append(["영구기간", "%d년 이후" % ((맥.회계연도(맥.끝예측) or 0) + 1)])
    빼는 = ["이자부부채"]
    D = 맥.기["2.DCF"]
    for 키, 말 in (("62", "우선주"), ("63", "비지배지분"), ("64", "순확정급여부채")):
        if _n(D.get(키)):
            빼는.append(말)
    이연 = "101" in 맥.기["11.NOA"] and _n((맥.기["11.NOA"].get("101") or {}).get("순평가"))
    if 이연:
        빼는.append("이연법인세부채(순액)")
    희석 = _n(D.get("151"))
    설정.append(["주주가치", "영업가치 + 비영업자산 + 현금 및 단기금융자산 − 이자부부채"])
    if len(빼는) > 1:
        설정.append(["주주가치에서 더 뺀 항목", " · ".join(빼는[1:])])
    설정.append(["주당가치", "주주가치 ÷ 적용 주식수(유통주식수 + 희석 주식수)" if 희석 else "주주가치 ÷ 유통주식수"])
    # 출처 구분 — 값이 든 입력 가정의 근거 첫 칸 딱지
    셈, 든수 = {}, 0
    for 번 in sorted(set(맥.가정.get("가정") or {}) | set(맥.가정.get("시점가정") or {}), key=lambda x: (len(x), x)):
        if not ("%s" % 번).isdigit():
            continue
        if 번 in (맥.가정.get("가정") or {}):
            if not _L._값든열(맥.가정, 번, 맥.예측열 + [맥.영구열]):
                continue
        elif all(_n(_L._시점값(맥.가정, 번, s)) is None for s in 시나리오들):
            continue
        든수 += 1
        t = _L.딱지(맥.가정, 번)
        if t:
            셈[t] = 셈.get(t, 0) + 1
    if 든수:                                                 # 1.1.20 — 「가정마다의 값과 출처 구분은 부록 A에 있습니다」(문서 안내 · 원칙 3)는 지웠다
        설정.append(["직접 입력한 가정", "%d개%s" % (든수, ("(출처 구분 %s)" % " · ".join("%s %d" % (k, 셈[k]) for k, _ in 태그뜻 if 셈.get(k))) if 셈 else "")])
    L += ["**표. 할인과 가치 산정의 설정**", ""] + _표(["항목", "이 평가"], 설정, ["l", "l"]) + [""]
    차 = 다른할인시점글(맥, "말" if 영기중 else "중간").strip()          # S8-03 — 다른 시점이면 ±x%(엔진 요약 「다른할인시점차」 — 값에 쓰지 않는다) · 표 설명
    if 차:
        L += [차, ""]
    # 1.1.20 — 「이 레터의 숫자와 평가 모델(엑셀)은 같은 가정으로 계산했습니다. 평가 모델을 마감할 때 … 대조했습니다(18절)」 는 지웠다 —
    # 모델 점검 절이 같은 대조와 그 결과를 쓴다(같은 내용을 두 자리에 쓰지 않는다)
    출 = ("%s" % ((getattr(맥, "주가", None) or {}).get("출처") or "")).strip()
    if 출:                                                   # 통독 v3 하-13 — 일별 종가 자료의 주소는 이 층에(1~5막은 자료 이름과 조회일만)
        출 = __import__("원고어투").합쇼체로(출)[0]           # v27 — 자료 파일 머리의 출처 메모(「… 뒤 줄은 뺐다」)도 레터의 어투로
        L += ["날마다의 주가 자료: %s" % 맥.바깥글(출), ""]
    확 = ("%s" % (맥.메타.get("가정확정") or "")).strip()
    if 확:                                                   # 통독 v4 중-15 — 가정 확정판의 날짜(첫 확정판 따위)는 머리 줄이 아니라 이 층에
        L += ["가정 확정: %s." % 맥.바깥글(확), ""]
    return L


# ── 매출

_금액줄 = {1: "13", 2: "21", 3: "27", 4: "33", 5: "39", 6: "44"}
_증가율줄 = {1: ("10", "11"), 2: ("18", "19"), 3: ("24", "25"), 4: ("30", "31"), 5: ("36", "37"), 6: ("42", None)}
_기준기간말 = {"직전회계연도": "직전 회계연도", "직전분기": "직전 분기", "직전12개월": "직전 12개월", "누계": "평가기준일까지의 누계 기간"}


def _방법말(x, 구=None):
    s, 경로 = x.get("번호"), x.get("경로")
    if 경로 == "합계" and 구:                                  # 전문가 통독 v3 하 — 하위 구분을 더한 구분(DRAM = 범용 DRAM + HBM)은 그렇게 적는다
        import 레터 as _L                                   # noqa: PLC0415
        아래 = [_L.구분이름(구, y["번호"]) for y in 구.get("매출구분") or [] if y.get("상위") == s]
        if 아래:
            return "하위 구분(%s)의 합" % " · ".join(아래)
    if 경로 == "수준":
        if s == 6:
            return "기준 기간 수준"
        명 = ("%s" % (x.get("판매단가명칭") or "")).strip() or "판매단가 지수"
        return ("생산능력 기준 판매량 × %s" if x.get("판매량산정") == "능력" else "판매량 × %s") % 명
    if s == 6:
        return "매출액 증가율"
    # 판매량명칭이 매출 자체(「매출」 · 구분 이름)면 판매단가 몫이 없는 매출 증가율 한 줄이다(회차 20261023 NVDA · TSLA · NAVER — 레터.가정이름과 같은 판정)
    명 = ("%s" % (x.get("판매량명칭") or "")).strip()
    if 매출명칭인가(x):
        return "%s 증가율" % ("매출" if 명 in ("매출", "매출액") else 명)
    단 = ("%s" % (x.get("판매단가명칭") or "")).strip() or "판매단가"
    return "%s 증가율 × %s 변동률" % (명 or "판매량", 단[:-2].strip() if 단.endswith("지수") and len(단) > 2 else 단)


def 자본구조말(맥, 구간="예측기간", 칸="예측값"):
    """Levered Beta 를 다시 환산한 자본구조의 이름 — `WACC.<구간>.DE`(목표 자본구조)를 적었으면 「목표 자본구조(D/E …)」, 비우면 엔진이 쓰는
    「평가기준일 자본구조(D/E …)」(엔진 `wacc` S7-09). 조건 없이 「목표 자본구조」를 찍으면 현재 구조를 쓴 회사에서 사실이 틀린다(2026-10-22 견본 실측)."""
    목표 = _n(((맥.가정.get("WACC") or {}).get(구간) or {}).get("DE")) is not None
    말 = "목표 자본구조" if 목표 else "평가기준일 자본구조"
    if "14" in 맥.기.get("3.WACC", {}) and _n((맥.기["3.WACC"].get("14") or {}).get(칸)) is not None:
        말 += "(D/E %s)" % 맥.수("R:기준:3.WACC:14:%s" % 칸, "퍼2")
    return 말


def 개별구분(맥):
    """→ (수준 경로 구분들, 증가율 경로 구분들) — 매출 절에서 소절(### N.k)을 따로 갖는 매출 구분. 기타(6)는 빼고,
    증가율 경로는 실적 마지막 회계연도나 최종 예측 연도의 매출 비중이 10% 이상일 때만(「분량은 중요도에 비례한다」).
    `레터원고.요건` 이 같은 목록으로 「사업마다 추정 논리」 원고를 요구한다."""
    구분들 = [x for x in 맥.구.get("매출구분") or []]
    FY, 끝 = 맥.FY끝, 맥.끝예측

    def 큰가(x):
        금 = _금액줄[x["번호"]]
        fy = _n((맥.기["4.Sales"].get(금) or {}).get(FY)) or 0.0
        합 = _n((맥.기["4.Sales"].get("54") or {}).get(FY)) or 0.0
        끝몫 = (_n((맥.기["4.Sales"].get(금) or {}).get(끝)) or 0.0) / (_n((맥.기["4.Sales"].get("54") or {}).get(끝)) or 1.0)
        return max(fy / 합 if 합 else 0.0, 끝몫) >= 0.10
    return ([x for x in 구분들 if x["경로"] == "수준" and x["번호"] < 6],
            [x for x in 구분들 if x["경로"] == "증가율" and x["번호"] < 6 and 큰가(x)])


def 매출절(맥, 번, 덧=None):
    """덧(맥, 매출 구분) — 매출 구분 소절 끝에 붙일 줄(본편 — 공시와 방법 · 가정 표 · 그림, `레터본문.스트림덧`)."""
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. 매출 추정" % 번, ""]
    구 = 맥.구
    구분들 = [x for x in 구.get("매출구분") or []]
    S = "R:기준:4.Sales:%s:%s"
    FY, 끝, TV = 맥.FY끝, 맥.끝예측, 맥.영구열
    L.append("매출은 %d개 매출 구분으로 나누어 추정했습니다." % len(구분들))
    L.append("")
    줄들 = []
    for x in 구분들:
        s = x["번호"]
        이름 = _L.구분이름(구, s)
        금 = _금액줄[s]
        fy = _n((맥.기["4.Sales"].get(금) or {}).get(FY))
        줄들.append([이름, _방법말(x, 구),
                   맥.수(S % (금, FY), "금액") if fy is not None else "—",
                   맥.식(["÷", S % (금, FY), S % ("54", FY)], "퍼1") if fy is not None else "—",
                   맥.수(S % (금, 끝), "금액"), 맥.수(S % (금, TV), "금액") if TV else "—"])
        맥.서술("매출.%s.%d" % (x["경로"], s))
    줄들.append(["합계", "", 맥.수(S % ("54", FY), "금액"), "", 맥.수(S % ("54", 끝), "금액"), 맥.수(S % ("54", TV), "금액") if TV else "—"])
    L += _표(["매출 구분", "추정 방법", "%s 매출" % FY, "비중", "%s 매출" % 끝, "영구기간 매출"], 줄들,
            ["l", "l", "r", "r", "r", "r"])
    L.append("")
    열 = 맥.예측열 + ([TV] if TV else [])
    L += _표(["구분"] + 열, [["매출액"] + [맥.수(S % ("54", c), "금액") for c in 열],
                           ["매출액 (연환산)"] + [맥.수(S % ("55", c), "금액") for c in 열],
                           ["매출액 증가율"] + [맥.수(S % ("56", c), "퍼1") if _n((맥.기["4.Sales"].get("56") or {}).get(c)) is not None else "—" for c in 열]])
    L.append("")
    반기 = [c for c in 맥.예측열 if (맥.속성.get(c, {}).get("개월") or 12) != 12]
    if 반기:
        글 = "%s %s개월 동안의 금액입니다. 연간 금액과 비교할 때는 연환산 금액을 씁니다." % (     # 레터 v27 — 표 주석(표 바로 아래)
            은(" · ".join(맥.표기(c) for c in 반기)), " · ".join(__import__("레터").개월글(맥.속성[c]["개월"]) for c in 반기))
        잔, 누 = 맥.자리.get("잔여"), 맥.자리.get("누계")
        if 잔 in 반기 and 누 and 맥.회계연도(잔) and 맥.회계연도(누) == 맥.회계연도(잔):
            글 += " 매출액 증가율은 회계연도 매출액의 전년 대비 증감률입니다. %d년 매출액은 %s 실적과 %s 추정을 합한 금액입니다." % (
                맥.회계연도(잔), 맥.열말(누), 맥.열말(잔))
        L.append(글)
        L.append("")
    환 = (구.get("환율") or {}).get("경로") or "없음"
    if 환 != "없음" and "181" in 맥.기["4.Sales"]:
        맥.서술("환율.%s" % 환)
        표기 = (구.get("환율") or {}).get("표기") or "환율"
        날 = "재무 자료 기준일" if importlib.import_module("기준일").자료경계(맥.가정)["이월"] else "평가기준일"   # 2026-10-26 — 이월 판에서 경로는 재무기준일부터 센다
        if 환 == "금리차":
            L.append(("환율(%s)은 " + 날 + " 환율 %s에 두 통화의 금리 차이를 반영한 선도환율로 가정했습니다. 표시통화 금리는 %s, 상대통화 금리는 %s. "
                     "최종 예측 연도 환율은 %s, 영구기간 환율은 %s. 기준 기간 매출에 적용된 환율은 %s.")
                     % (표기, 맥.수("S:601:기준", "수1"), 맥.수("S:602:기준", "퍼2"), 입니다(맥.수("S:603:기준", "퍼2")),
                        맥.수("R:기준:4.Sales:181:%s" % 끝, "수1"), 입니다(맥.수("R:기준:4.Sales:181:%s" % TV, "수1")), 입니다(맥.수("S:604:기준", "수1"))))
        elif 환 == "고정":
            L.append(("환율(%s)은 " + 날 + "의 %s 그대로 적용했습니다. 기준 기간 매출에 적용된 환율은 %s.") % (표기, 을(맥.수("S:601:기준", "수1")), 입니다(맥.수("S:604:기준", "수1"))))
        else:
            L.append("환율(%s)은 기간마다 가정했습니다(첫 예측 기간 %s · 최종 예측 연도 %s · 영구기간 %s). 기준 기간 매출에 적용된 환율은 %s."
                     % (표기, 맥.수("R:기준:4.Sales:181:%s" % 맥.예측열[0], "수1"), 맥.수("R:기준:4.Sales:181:%s" % 끝, "수1"),
                        맥.수("R:기준:4.Sales:181:%s" % TV, "수1"), 입니다(맥.수("S:604:기준", "수1"))))
        L.append("")

    수준, 증가 = 개별구분(맥)
    if 수준:
        L += _수준설명(맥, 수준)
    if 증가:
        이름들 = _나열([_L.구분이름(구, x["번호"]) for x in 증가])
        L.append("%s 매출액은 전기 매출액에 판매량 증가율과 판매단가 변동률을 반영해 추정했습니다."
                 % (이름들 if len(이름들) <= 50 else "증가율 경로로 추정한 매출 구분의"))
        L.append("")
    k = 0
    for x in 수준 + 증가:
        k += 1
        L += (_수준절 if x["경로"] == "수준" else _증가율절)(맥, x, "%d.%d" % (번, k))
        if 덧:
            L += 덧(맥, x)
    return L


def _수준설명(맥, 수준):
    """수준 경로 구분의 설명 — 한 번만 쓰고 구분마다의 값은 표로."""
    import 레터 as _L                                       # noqa: PLC0415
    구 = 맥.구
    이름들 = [_L.구분이름(구, x["번호"]) for x in 수준]
    환 = ((구.get("환율") or {}).get("경로") or "없음") != "없음"
    L = []
    명 = 수렴명칭(맥, 수준)
    L.append("%s 매출액은 기준 기간 매출액(연환산)에 판매량과 %s 기준 기간보다 얼마나 변하는지를 곱해 추정했습니다%s. "
             "영구기간 매출액에는 최종 예측 연도 말의 판매량을 적용했습니다."
             % (_나열(이름들), 이(명), ". 외화 매출 몫에는 환율 변화를 반영했습니다" if 환 else ""))
    L.append("")
    줄들 = []
    for x in 수준:
        s = x["번호"]
        T = "T:6%d7" % s
        맥.서술("매출.수준.%d" % s, "매출.%s.%d" % (x.get("판매량산정"), s), "매출.단가%s.%d" % (x.get("단가경로"), s))
        기말 = _기준기간말.get(x.get("기준기간") or "", x.get("기준기간") or "")
        if x.get("기준기간") == "누계" and 이월판(맥):                 # 날짜 둘 — 누계 기간은 재무 자료 기준일까지
            기말 = "재무 자료 기준일까지의 누계 기간"
        줄들.append([_L.구분이름(구, s), 기말,
                   ("%s" % (x.get("판매량명칭") or "판매량")).strip(), 맥.수(T + ":판매량", "수2"), ("%s" % (x.get("판매량단위") or "")).strip(),
                   맥.수(T + ":판매단가지수", "지수3"), 맥.수(T + ":판매량지수", "지수3")])
    L += _표(["매출 구분", "기준 기간", "판매량", "기준 기간 판매량", "단위", "기준 기간 %s" % 명, "기준 기간 판매량 지수"], 줄들,
            ["l", "l", "l", "r", "l", "r", "r"])
    L.append("")
    능력 = [x for x in 수준 if x.get("판매량산정") == "능력"]
    직접 = [x for x in 수준 if x.get("판매량산정") not in ("능력", "저량")]
    저량 = [x for x in 수준 if x.get("판매량산정") == "저량"]               # S2-04 — 저량 굴림(잔고 소진 · 가입자 · 설치기반)
    if 능력:
        글 = "%s 판매량은 라인별 생산능력의 합에 가동률과 수율을 곱해 구했습니다." % _나열([_L.구분이름(구, x["번호"]) for x in 능력])
        모두하나 = True
        for x in 능력:
            s = x["번호"]
            for 번호 in (273 + 25 * (s - 1), 277 + 25 * (s - 1)):
                for c in 맥.예측열:
                    v = _n(_L._가정값(맥.가정, "%d" % 번호, _시(맥, "%d" % 번호), c))
                    if v is not None and v != 1.0:
                        모두하나 = False
        if 모두하나:
            s0 = 능력[0]["번호"]
            가0 = "%d" % (273 + 25 * (s0 - 1))
            글 += " 가동률은 모든 예측 기간에 %s 두어 생산능력을 그대로 판매량으로 썼습니다." % 으로(맥.수("A:%s:%s:%s" % (가0, _시(맥, 가0), 맥.첫예측), "퍼0"))
            글 += " 수율은 따로 곱하지 않았습니다(수율이 100%라는 뜻이 아닙니다)."    # 통독 v3 전문가 중7 · 2026-10-22 — 수율이 어디에 들었는지(가격 지수 · 능력 줄)는
            #                                                     회사마다 다르다(견본 실측: 능력 줄에 든 회사에 「가격에 이미 들어 있다」). 자리는 저자 글이 적는다
        L.append(글)                                          # 1.1.20 — 「가동률과 수율은 부록 A에 있습니다」(문서 안내 · 원칙 3)는 지웠다
    if 직접:
        L.append("%s 판매량은 예측 기간마다 입력했습니다." % _나열([_L.구분이름(구, x["번호"]) for x in 직접]))
    if 저량:
        잔 = [x for x in 저량 if (x.get("판매량꼴") or "유량") != "저량"]
        기 = [x for x in 저량 if (x.get("판매량꼴") or "유량") == "저량"]
        글 = ("%s 판매량은 저량을 굴려 구했습니다. 기말 저량은 앞 기말에 기간 동안의 유입을 더하고 유출(앞 기말 × 유출률)을 뺀 값입니다."
              % _나열([_L.구분이름(구, x["번호"]) for x in 저량]))
        if 잔:
            글 += " 잔고 소진인 %s 판매량은 유출(앞 기말 잔고 × 소진율) 그대로입니다." % _나열([_L.구분이름(구, x["번호"]) for x in 잔])
        if 기:
            글 += " %s 판매량은 기간 평균 저량에 전환율을 곱한 값입니다(전환율을 비운 기간은 1)." % _나열([_L.구분이름(구, x["번호"]) for x in 기])
        L.append(글)                                          # 1.1.20 — 「유입과 유출률은 부록 A에 있습니다」(원칙 3)는 지웠다
    산출 = [(x, _n(_L._시점값(맥.가정, "6%d2" % x["번호"], "기준"))) for x in 수준]
    산출 = [(x, v) for x, v in 산출 if v]
    if 산출:
        물량원가 = any("물량단위원가" in (y.get("산식"), y.get("보조산식")) for y in 구.get("원가줄") or [])
        L.append("판매량 지수는 판매량에 단위 산출량을 곱한 지수%s. 단위 산출량 증가율은 %s."
                 % ("로, 매출액이 아니라 원가 추정(전사 판매량 지수)에 씁니다" if 물량원가 else "입니다", 입니다(" · ".join("%s %s" % (_L.구분이름(구, x["번호"]), 맥.수("S:6%d2:기준" % x["번호"], "퍼1")) for x, _v in 산출))))
    L.append("")
    수렴 = [x for x in 수준 if x.get("단가경로") == "수렴"]
    if 수렴:
        든열 = [c for c in 맥.예측열 if any(_n(_L._가정값(맥.가정, "6%d3" % x["번호"], "기준", c)) is not None for x in 수렴)]
        명 = 수렴명칭(맥, 수렴)
        L.append("%s 변동률을 적은 기간에는 기준 기간 지수에 (1 + 변동률)%s 곱한 값입니다. "
                 "유지 종료 연도까지는 그 수준을 유지하고, 그 뒤 정상 수준 도달 연도까지 해마다 같은 비율로 바뀌어 정상 수준 %s에 이른다고 가정했습니다. "
                 "영구기간의 %s 정상 수준과 같습니다."
                 % (은(명), "과 기준 기간 뒤의 단위 산출량 증가를" if any(x in [y for y, _v in 산출] for x in 수렴) else "을", 명, 은(명)))
        if 명 != "판매단가 지수" and any(x in [y for y, _v in 산출] for x in 수렴):
            L.append("%s 비트 단가 말고도 웨이퍼 한 장에서 나오는 비트(단위 산출량)와 제품 구성(믹스)의 변화를 함께 반영합니다. "
                     "매출 구분별 표에 단위 산출량 증가를 제외한 비트 단가의 추이를 함께 적었습니다. 제품 구성의 효과는 따로 구분하지 않았습니다." % 은(명)
                     if 명.startswith("웨이퍼") else
                     "%s 단가 말고도 단위 산출량과 제품 구성(믹스)의 변화를 함께 반영합니다. 매출 구분별 표에 단위 산출량 증가를 제외한 단가의 추이를 함께 적었습니다." % 은(명))
        L.append("")
        줄들 = []
        for x in 수렴:
            s = x["번호"]
            u = "6%d3" % s
            줄들.append([_L.구분이름(구, s)] + ([("%s" % (x.get("판매단가명칭") or "")).strip() or "—"] if 명 == "판매단가 지수" else [])
                      + [맥.수("A:%s:기준:%s" % (u, c), "증1") if _n(_L._가정값(맥.가정, u, "기준", c)) is not None else "—" for c in 든열]
                      + [맥.수("S:6%d8:기준" % s, "연도"), 맥.수("S:6%d9:기준" % s, "연도"), 맥.수("S:6%d6:기준" % s, "지수2")])
        한명 = 명 != "판매단가 지수"                         # 명칭이 하나면 「판매단가」 칸은 머리가 대신한다(R1b · L5)
        L += _표(["매출 구분"] + ([] if 한명 else ["판매단가"]) + ["%s 변동률" % c for c in 든열] + ["유지 종료 연도", "정상 수준 도달 연도", "정상 수준 %s" % 명],
                줄들, ["l"] + ([] if 한명 else ["l"]) + ["r"] * (len(든열) + 3))
        L.append("")
        L += 정상근거표(맥, 명)
    직단 = [x for x in 수준 if x.get("단가경로") != "수렴"]
    if 직단:
        전 = [x for x in 직단 if x.get("단가입력") == "전년대비"]
        기 = [x for x in 직단 if x.get("단가입력") != "전년대비"]
        if 기:
            명기 = {("%s" % (x.get("판매단가명칭") or "")).strip() for x in 기}
            L.append("%s %s 기준 기간 지수에 (1 + 기간마다 입력한 변동률)%s 곱해 정했습니다. 변동률을 비운 기간에는 앞 기간의 지수를 그대로 적용했습니다."
                     % (_나열([_L.구분이름(구, x["번호"]) for x in 기]), 은(명기.pop() if len(명기) == 1 and "" not in 명기 else "판매단가 지수"),
                        "과 기준 기간 뒤의 단위 산출량 증가를" if any(x in [y for y, _v in 산출] for x in 기) else "을"))
        if 전:
            L.append("%s 판매단가 지수는 앞 기간 지수에 (1 + 기간마다 입력한 변동률)을 곱해 정했습니다." % _나열([_L.구분이름(구, x["번호"]) for x in 전]))
        L.append("")
    return L


def _수준절(맥, x, 번):
    import 레터 as _L                                       # noqa: PLC0415
    구 = 맥.구
    s = x["번호"]
    이름 = _L.구분이름(구, s)
    L = ["### %s %s" % (번, 이름), ""]
    S = "R:기준:4.Sales:%s:%s"
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    량말 = ("%s" % (x.get("판매량명칭") or "")).strip() or "판매량"
    단위 = ("%s" % (x.get("판매량단위") or "")).strip()
    if x.get("판매량산정") == "능력":
        줄들 = []
        for j in x.get("라인") or []:
            n = 210 + j["번호"]
            if "%d" % n in 맥.기["4.Sales"]:
                줄들.append(["%s (기간 평균)" % (j.get("이름") or "라인 %d" % j["번호"])] +
                          [맥.수(S % (n, c), "수1") if _n((맥.기["4.Sales"].get("%d" % n) or {}).get(c)) is not None else "—" for c in 맥.예측열])
        for 줄, 말 in (("1%d8" % s, "생산능력 합계 (기간 평균)"), ("1%d9" % s, "생산능력 합계 (기말)")):
            if 줄 in 맥.기["4.Sales"]:
                줄들.append([말] + [맥.수(S % (줄, c), "수1") for c in 맥.예측열])
        L += _표(["라인%s" % ((" (%s)" % 단위) if 단위 else "")] + 맥.예측열, 줄들)
        L.append("")
    줄들 = []
    if "1%d1" % s in 맥.기["4.Sales"]:
        줄들.append(["%s (기간 평균)" % 량말] + [맥.수(S % ("1%d1" % s, c), "수1") if _n((맥.기["4.Sales"].get("1%d1" % s) or {}).get(c)) is not None else "—" for c in 열])
    명 = ("%s" % (x.get("판매단가명칭") or "")).strip() or "판매단가 지수"
    for 줄, 말, 꼴 in (("1%d3" % s, "판매량 지수", "지수3"), ("1%d5" % s, 명, "지수3"),
                    ("1%d6" % s, "환율 조정 계수", "지수3"), ("1%d7" % s, "매출 조정 계수", "지수3")):
        v = 맥.기["4.Sales"].get(줄)
        if not v:
            continue
        if 줄.endswith("7") and all(_n(v.get(c)) in (None, 1.0) for c in 열):
            continue
        줄들.append([말] + [맥.수(S % (줄, c), 꼴) if _n(v.get(c)) is not None else "—" for c in 열])
    줄들 += 백줄들(맥, x, 열)
    줄들.append(["매출액"] + [맥.수(S % (_금액줄[s], c), "금액") for c in 열])
    L += _표(["구분"] + 열, 줄들)
    L.append("")
    독 = (맥.가정.get("독자근거") or {})
    for 키 in ("6%d6" % s, "6%d7" % s, "6%d3" % s):
        if isinstance(독.get(키), str) and 독[키].strip():
            글 = 레터이야기.펴기(맥, 독[키], "독자근거.%s" % 키)       # 장부 자리표시를 편다(2026-10-22 — 원고글만 부르면 「{S:…}」 가 그대로 찍혔다)
            if 글:
                L.append(글)
                L.append("")
    return L


def 매출명칭인가(x):
    """매출 구분의 판매량명칭이 매출 그 자체인가(「매출」 · 「영업수익」 · 구분 이름에 든 말 · 「<구분 이름> 매출」) — 그 구분의 30 · 38 줄은 매출 증가율이다."""
    import 레터 as _L                                       # noqa: PLC0415
    명 = ("%s" % (x.get("판매량명칭") or "")).strip()
    이 = ("%s" % (x.get("이름") or "")).strip()
    return bool(명) and (명 in ("매출", "매출액", "영업수익") or _L.구분뗀말(명, 이) in ("매출", "매출액", "영업수익") or bool(이 and 명 in 이))


def _증가율절(맥, x, 번):
    import 레터 as _L                                       # noqa: PLC0415
    s = x["번호"]
    L = ["### %s %s" % (번, _L.구분이름(맥.구, s)), ""]
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    S = "R:기준:4.Sales:%s:%s"
    물, 가 = _증가율줄[s]
    줄들 = []
    명 = ("%s" % (x.get("판매량명칭") or "")).strip()
    매명 = 매출명칭인가(x)
    물말 = ("매출 증가율" if 매명 else ("%s 증가율" % 명 if 명 else "판매량 증가율"))
    단명 = ("%s" % (x.get("판매단가명칭") or "")).strip()
    단말 = "%s 변동률" % ((단명[:-2].strip() if 단명.endswith("지수") and len(단명) > 2 else 단명) or "판매단가")    # 판매단가명칭을 읽는다(레터.가정이름과 같은 말)
    for 줄, 말 in ((물, 물말), (가, 단말)):
        if 줄 and 줄 in 맥.기["4.Sales"]:
            v = 맥.기["4.Sales"][줄]
            if 줄 == 가 and 매명 and all(not (_n(v.get(c)) or 0.0) for c in 열):
                continue                                    # 판매량명칭이 매출이면 0 인 판매단가 줄은 싣지 않는다(이 구분에 가격 몫이 없다)
            줄들.append([말] + [맥.수(S % (줄, c), "퍼1") if _n(v.get(c)) is not None else "—" for c in 열])
    줄들.append(["매출액"] + [맥.수(S % (_금액줄[s], c), "금액") for c in 열])
    L += _표(["구분"] + 열, 줄들)
    L.append("")
    for 키 in ("%d" % (30 + 8 * (s - 1)), "%d" % (34 + 8 * (s - 1))):
        t = (맥.가정.get("독자근거") or {}).get(키)
        if isinstance(t, str) and t.strip():
            글 = 레터이야기.펴기(맥, t, "독자근거.%s" % 키)
            if 글:
                L.append(글)
                L.append("")
    return L


def 수렴명칭(맥, 수렴):
    """수렴 경로 구분들의 판매단가 명칭 — 모두 같으면 그 명칭(「웨이퍼당 매출 지수」), 아니면 「판매단가 지수」(R1b · L5)."""
    명들 = {("%s" % (x.get("판매단가명칭") or "")).strip() for x in 수렴}
    명 = 명들.pop() if len(명들) == 1 else ""
    return 명 or "판매단가 지수"


def 백줄들(맥, x, 열):
    """매출 구분 표에 더하는 두 줄(R1b · L5) — 판매단가 지수를 기준 기간 = 100 으로 읽은 줄, 그리고 단위 산출량 증가를 걷어 낸 단가(비트 단가)의
    줄(기준 기간 = 100). 비트 단가 = (지수 ÷ 기준 기간 지수) ÷ (단위 산출량 지수 ÷ 기준 기간 단위 산출량 지수), 단위 산출량 지수 = 판매량 지수 ÷ 판매량.
    단위 산출량 증가율이 없으면 둘째 줄은 없다(첫 줄과 같다)."""
    import 레터 as _L                                       # noqa: PLC0415
    s = x["번호"]
    T = "T:6%d7" % s
    if not _n(맥.값(T + ":판매단가지수")):
        return []
    S = 맥.기["4.Sales"]
    가 = S.get("1%d5" % s) or {}
    기간 = 눈금이름(맥, x)
    명 = _단가말(x)
    낸 = [["%s (%s = 100)" % (명, 기간)] + [맥.식(["×", ["÷", "R:기준:4.Sales:1%d5:%s" % (s, c), 눈금키(맥, s)], 100], "수0")
                                          if _n(가.get(c)) is not None else "—" for c in 열]]
    산출 = _n(_L._시점값(맥.가정, "6%d2" % s, "기준"))
    량, 지 = S.get("1%d1" % s) or {}, S.get("1%d3" % s) or {}
    if 산출 and _n(맥.값(T + ":판매량")) and _n(맥.값(T + ":판매량지수")):
        말 = "비트 단가" if 명.startswith("웨이퍼") else "단위 산출량을 걷어 낸 단가"

        def 칸(c):
            if None in (_n(가.get(c)), _n(량.get(c)), _n(지.get(c))) or not _n(량.get(c)):
                return "—"
            k = "R:기준:4.Sales:%s:" + c
            return 맥.식(["×", ["÷", ["÷", k % ("1%d5" % s), T + ":판매단가지수"],
                                ["÷", ["÷", k % ("1%d3" % s), k % ("1%d1" % s)], ["÷", T + ":판매량지수", T + ":판매량"]]], 100], "수0")
        낸.append(["%s (%s = 100)" % (말, _기준기간이름(맥, x))] + [칸(c) for c in 열])     # 비트 단가는 기준 기간 눈(뉴스의 분기 계약가 변동과 견주는 눈)
    return 낸


def _근거끝(맥, v, 꼴):
    """정상수준.검증 의 끝 — 수 또는 {"키": 장부 키}. → (키 또는 식, 값)."""
    if isinstance(v, dict) and v.get("키"):
        return v["키"], _n(맥.값(v["키"]))
    return None, _n(v)


def 정상근거표(맥, 명):
    """정상 수준의 근거 표(R1b · L7) — 저자가 `Narrative.정상수준.방법` 에 적은 방법마다 범위 · 가운데와 채택 이유. 없으면 빈 목록(알림)."""
    N = 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}
    정 = N.get("정상수준") if isinstance(N.get("정상수준"), dict) else None
    if not 정 or not 정.get("방법"):
        맥.알림.append("Narrative.정상수준(정상 수준을 잰 방법마다의 범위 · 가운데 · 채택 이유)이 없다 — 5절의 근거 표를 세우지 않았다")
        return []
    줄들 = []
    for k, x in enumerate(정["방법"]):
        이 = 맥.원고글(x.get("이름"), "Narrative.정상수준.방법[%d].이름" % k)
        아, 위 = "N:정상수준:방법:%d:아래" % k, "N:정상수준:방법:%d:위" % k
        가 = 맥.수("N:정상수준:방법:%d:가운데" % k, "지수2") if _n(x.get("가운데")) is not None else 맥.식(["÷", ["합", 아, 위], 2], "지수2")
        줄들.append([이 or "방법 %d" % (k + 1), "%s~%s" % (맥.수(아, "지수2"), 맥.수(위, "지수2")), 가,
                   맥.원고글(x.get("까닭"), "Narrative.정상수준.방법[%d].까닭" % k) if x.get("까닭") else "—"])
    눈 = 눈금선언(맥.가정)
    덧 = ""
    if 눈 and all(abs((_n(v) or 0) - 1.0) < 1e-12 for v in (눈.get("지수") or {}).values()):      # 지수 1 = 눈금의 기간(「무엇의 몇 %」)
        덧 = " 범위와 가운데의 지수 1.00은 %s의 값입니다(0.90이면 %s의 90%%)." % (("%s" % 눈["이름"]).strip(), ("%s" % 눈["이름"]).strip())
    L = ["정상 수준 %s 방법별로 산정한 범위 안에서 정했습니다.%s" % (은(명), 덧), ""]
    L += _표(["방법", "범위", "가운데", "까닭"], 줄들, ["l", "r", "r", "l"])
    L.append("")
    채 = 레터이야기.펴기(맥, 정.get("채택"), "Narrative.정상수준.채택")
    if 채:
        L += ["채택한 까닭 — %s" % (채 if 채.endswith(".") else 채 + "."), ""]
    return L


def 검증범위줄(맥, v):
    """영구기간 영업이익률의 검증 범위(R1b · L7) — 저자가 `Narrative.정상수준.검증` 에 적은 범위(「완결 사이클」 · 「현 사이클 포함」 따위)마다
    아래 끝 · 위 끝과 기준 시나리오의 자리. 없으면 A-950 · A-951 의 범위 하나(그때는 알림)."""
    import 레터 as _L                                       # noqa: PLC0415
    N = 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}
    정 = N.get("정상수준") if isinstance(N.get("정상수준"), dict) else {}
    범위 = []
    for k, x in enumerate(정.get("검증") or []):
        이 = 맥.원고글(x.get("이름"), "Narrative.정상수준.검증[%d].이름" % k)
        a키 = x["아래"]["키"] if isinstance(x.get("아래"), dict) else "N:정상수준:검증:%d:아래" % k
        b키 = x["위"]["키"] if isinstance(x.get("위"), dict) else "N:정상수준:검증:%d:위" % k
        범위.append((이 or "범위 %d" % (k + 1), a키, b키))
    if not 범위:
        lo, hi = _n(_L._시점값(맥.가정, "950", "기준")), _n(_L._시점값(맥.가정, "951", "기준"))
        if lo is None or hi is None:
            return []
        맥.알림.append("Narrative.정상수준.검증(「완결 사이클」 · 「현 사이클 포함」 같은 검증 범위)이 없다 — 10절에 A-950 · A-951 의 범위 하나만 실었다")
        범위 = [("과거 경기 순환에서 잰 Normalization 영업이익률 범위", "S:950:기준", "S:951:기준")]
    줄들 = []
    for 이, a, b in 범위:
        av, bv = _n(맥.값(a)), _n(맥.값(b))
        if av is None or bv is None:
            continue
        if av - 1e-9 <= v <= bv + 1e-9:
            자 = "안"
        elif v > bv:
            자 = "위 끝보다 %s 높음" % 맥.식(["−", "R:기준:2.DCF:42", b], "폭p1")
        else:
            자 = "아래 끝보다 %s 낮음" % 맥.식(["−", a, "R:기준:2.DCF:42"], "폭p1")
        줄들.append([이, "%s~%s" % (맥.수(a, "퍼1"), 맥.수(b, "퍼1")), 자])
    if not 줄들:
        return []
    L = ["**표. 기준 시나리오의 영구기간 영업이익률 %s 검증 범위의 비교**" % 과(맥.수("R:기준:2.DCF:42", "퍼1")), ""]
    L += _표(["검증 범위", "범위", "기준 시나리오의 위치"], 줄들, ["l", "r", "l"])
    L.append("")
    return L


# ── 비용

_원가본줄 = {1: ("5.COGS", "10"), 2: ("5.COGS", "13"), 3: ("5.COGS", "14"), 4: ("5.COGS", "15"),
          5: ("6.SG&A", "12"), 6: ("6.SG&A", "14"), 7: ("6.SG&A", "15")}
_원가비율 = {1: 80, 2: 84, 3: 88, 4: 92, 5: 112, 6: 116, 7: 120}
_산식말 = {"매출액비율": "매출액 대비 비율", "물가연동": "물가 연동 금액", "물량단위원가": "판매량 × 단위원가", "설비계수": "설비 취득원가 × 설비 계수"}


def _원가줄문장들(맥, 원가줄):
    """원가 줄을 산식별로 묶어 서술한다 — 같은 산식의 줄은 한 문장으로(되풀이하지 않는다). 설비계수 · 물량단위원가는 줄마다."""
    import 레터 as _L                                       # noqa: PLC0415
    끝 = 맥.끝예측
    묶음 = {}
    차례 = []
    for x in 원가줄:
        k, 산식 = x["번호"], x.get("산식")
        맥.서술("원가줄.%d.%s" % (k, 산식))
        if x.get("옛식") == "예":
            열쇠 = ("옛", 산식)
        elif 산식 == "매출액비율" and (x.get("보조산식") or "없음") == "없음":     # 보조 산식이 있으면 개별 문장(주 · 보조 몫 — 「일정 비율」 한 값으로 부르지 않는다)
            열쇠 = ("비율", x.get("연동기준") or "매출액", x.get("가격지수") or "없음")
        elif 산식 == "물가연동" and (x.get("보조산식") or "없음") == "없음":
            열쇠 = ("물가", x.get("수준지수") or "소비자물가")      # 수준지수가 다르면 다른 문장(임금 · 인력 · 자체 — 엔진 원가 S4-08)
        else:
            열쇠 = ("개별", k)
        if 열쇠 not in 묶음:
            묶음[열쇠] = []
            차례.append(열쇠)
        묶음[열쇠].append(x)
    글들 = []
    for 열쇠 in 차례:
        xs = 묶음[열쇠]
        이름들 = [_L.원가줄이름(맥.구, x["번호"]) for x in xs]
        주어 = 은(_나열(이름들))
        if 열쇠[0] == "옛":
            if 열쇠[1] == "물가연동":
                글들.append("%s 첫 예측 기간의 매출액 대비 비율로 정한 연간 금액을 물가 변동률로 늘려 추정했습니다." % 주어)
            else:
                글들.append("%s 첫 예측 기간의 매출액 대비 비율을 모든 예측 기간에 적용했습니다." % 주어)
        elif 열쇠[0] == "비율":
            값 = []
            for x in xs:
                비 = _원가비율[x["번호"]]
                if _n(_L._가정값(맥.가정, "%d" % 비, "기준", 끝)) is not None:
                    값.append(("%s " % _L.원가줄이름(맥.구, x["번호"]) if len(xs) > 1 else "") + 맥.수("A:%d:기준:%s" % (비, 끝), "퍼1"))
            연동 = "판매량으로 환산한 불변가격 매출액" if 열쇠[1] == "판매량" else "매출액"
            글 = "%s %s의 일정 비율로 추정했습니다%s." % (주어, 연동, (". 최종 예측 연도의 비율은 %s" % 입니다(" · ".join(값))) if 값 else "")
            if 열쇠[2] != "없음":
                글 += " 비율에는 %s 변동을 곱했습니다." % {"원재료": "원재료 가격", "공공요금": "공공요금", "소비자물가": "소비자물가"}[열쇠[2]]
            글들.append(글)
        elif 열쇠[0] == "물가":
            글들.append("%s 기준 금액을 %s로 늘려 추정했습니다." % (주어, _수준말(맥, xs[0])))
        else:
            글들.append(_원가줄문장(맥, xs[0]))
    return 글들


def _수준말(맥, x):
    """물가연동 줄의 연간 수준을 미는 변동률의 이름(구조 `원가줄[].수준지수` — 엔진 원가: 소비자물가 106 · 임금 504 · 인력 (1 + 504)(1 + 501) − 1 · 자체 7k2)."""
    종 = x.get("수준지수") or "소비자물가"
    if 종 == "임금":
        return "임금상승률"
    if 종 == "인력":
        return "임금상승률과 인원 증가율을 함께 곱한 변동률"
    if 종 == "자체":
        return "그 비용의 단위원가 변동률(최종 예측 연도 %s)" % 맥.수("A:7%d2:기준:%s" % (x["번호"], 맥.끝예측), "증1")
    return "소비자물가 변동률"


def _원가줄문장(맥, x):
    """설비계수 · 물량단위원가(· 보조 산식이 있는 물가연동) 원가 줄 하나의 서술."""
    import 레터 as _L                                       # noqa: PLC0415
    k = x["번호"]
    이름 = _L.원가줄이름(맥.구, k)
    산식 = x.get("산식")
    끝 = 맥.끝예측
    글 = ""
    if 산식 == "설비계수":
        자 = _L._목록이름((맥.구.get("투자") or {}).get("자산군"), x.get("자산군") or 1, "설비")
        글 = "%s %s 취득원가(%s)에 설비 계수(최종 예측 연도 %s)를 곱해 추정했습니다." % (
            은(이름), 자, "기초 · 기말 평균" if x.get("설비기준") == "평균" else "기초", 맥.수("A:7%d1:기준:%s" % (k, 끝), "퍼1"))
    elif 산식 == "물가연동":
        글 = "%s 기준 금액을 %s로 늘려 추정했습니다." % (은(이름), _수준말(맥, x))
    elif 산식 == "물량단위원가":
        글 = "%s 전사 판매량 지수에 단위원가를 곱해 추정했습니다. 단위원가 변동률은 최종 예측 연도 %s로 가정했습니다." % (은(이름), 맥.수("A:7%d2:기준:%s" % (k, 끝), "증1"))
    elif 산식 == "매출액비율":
        비 = _원가비율.get(k)
        값 = 맥.수("A:%d:기준:%s" % (비, 끝), "퍼1") if 비 and _n(_L._가정값(맥.가정, "%d" % 비, "기준", 끝)) is not None else None
        글 = "%s 매출액의 일정 비율로 추정했습니다%s." % (은(이름), (". 최종 예측 연도의 비율은 %s" % 입니다(값)) if 값 else "")
    보 = x.get("보조산식") or "없음"
    if 보 != "없음":
        맥.서술("원가줄.%d.보조.%s" % (k, 보))
        보말 = {"물량단위원가": "전사 판매량 지수에 단위원가를 곱한", "설비계수": "설비 취득원가에 설비 계수를 곱한",
               "매출액비율": "매출액에 비율을 곱한", "물가연동": "기준 금액을 %s로 늘린" % _수준말(맥, x)}[보]
        글 += " %s 보조 산식을 %s 비중으로 섞었습니다." % (보말, 맥.수("S:7%d4:기준" % k, "퍼0"))
        단 = [_n(_L._가정값(맥.가정, "7%d2" % k, "기준", c)) for c in 맥.예측열]
        if 보 == "물량단위원가" and _n(_L._가정값(맥.가정, "7%d2" % k, "기준", 끝)) is not None:
            글 += " 보조 산식의 단위원가 변동률은 %s %s." % ("해마다" if len(set(단)) == 1 else "최종 예측 연도", 입니다(맥.수("A:7%d2:기준:%s" % (k, 끝), "증1")))
    if ((맥.구.get("환율") or {}).get("경로") or "없음") != "없음" and _n(_L._시점값(맥.가정, "7%d6" % k, "기준")):
        글 += " 외화로 나가는 몫(%s)에는 환율 변화를 반영했습니다." % 맥.수("S:7%d6:기준" % k, "퍼0")
    return 글


def 비용절(맥, 번, 인건비=True):
    """인건비 = False 면 인건비 문단 · 표를 싣지 않는다(본편은 인건비를 따로 절로 세운다 — `레터본문.인건비절`)."""
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. 영업비용과 영업이익률" % 번, ""]
    구 = 맥.구
    원가줄 = [x for x in 구.get("원가줄") or [] if _원가줄쓰나(맥, x)]
    L.append("영업비용은 원가 항목별로 나누어 추정했습니다.")      # 기능별 표시 회사(매출원가 · 판관비)도 있다 — 「성격별로」 를 고정하지 않는다
    L.append("")
    for 글 in _원가줄문장들(맥, 원가줄):
        L.append("- %s" % 글)
    원 = 구.get("원가") or {}
    if 원.get("재고변동반영") == "예" and "153" in 맥.기["5.COGS"]:
        맥.서술("원가.재고변동반영")
        L.append("- 재고자산 증감액의 %s 매출원가에 반영했습니다. 늘어난 기간에는 덜고 줄어든 기간에는 더합니다. 생산원가 가운데 재고로 남는 몫을 "
                 "손익에서 빼는 조정이며, 재고자산 증감액 전체는 순운전자본 증감으로 현금흐름에 들어갑니다." % 을(맥.수("S:701:기준", "퍼0")))
    if 원.get("판관비배분") == "예" and "152" in 맥.기["5.COGS"]:
        맥.서술("원가.판관비배분")
        L.append("- %s의 %s 판매비와관리비로 배분했습니다. 매출원가와 판매비와관리비 사이의 배분이라 영업이익에는 영향이 없습니다."
                 % (_L.원가줄이름(구, 1), 을(맥.수("A:702:%s:%s" % (_시(맥, "702"), 맥.끝예측), "퍼0"))))
    if any(_n(_L._가정값(맥.가정, "168", _시(맥, "168"), c)) is not None for c in 맥.예측열):
        L.append("- 감가상각비는 매출원가 %s · 판매비와관리비 %s 배분했습니다."
                 % (맥.수("A:168:%s:%s" % (_시(맥, "168"), 맥.끝예측), "퍼0"), 으로(맥.수("A:172:%s:%s" % (_시(맥, "172"), 맥.끝예측), "퍼0"))))
    L.append("")
    if 인건비:
        L += _인건비글(맥)
    영구열씀 = ((구.get("영구가치") or {}).get("영구이익기준") == "영구열") and 맥.영구열
    열 = [맥.FY끝] + 맥.예측열 + ([맥.영구열] if 영구열씀 else [])
    C, G = 맥.기["5.COGS"], 맥.기["6.SG&A"]
    줄들 = [["매출액"] + [_칸(맥, "2.DCF", "11", c, "금액") for c in 열]]
    for x in 원가줄:
        시트, 줄 = _원가본줄[x["번호"]]
        if 시트 == "5.COGS":
            줄들.append([_L.원가줄이름(구, x["번호"])] + [_칸(맥, 시트, 줄, c, "금액") for c in 열])
    for 키, 말 in (("152", "(−) 판매비와관리비 배분액"), ("12", "감가상각비 및 무형자산상각비"), ("153", "(−) 재고자산 변동"), ("11", "노무비")):
        if 키 in C and any(_n(C[키].get(c)) for c in 열):
            줄들.append([말] + [_칸(맥, "5.COGS", 키, c, "금액") for c in 열])
    줄들.append(["**매출원가**"] + ["**%s**" % _칸(맥, "5.COGS", "17", c, "금액") for c in 열])
    for x in 원가줄:
        시트, 줄 = _원가본줄[x["번호"]]
        if 시트 == "6.SG&A":
            줄들.append([_L.원가줄이름(구, x["번호"])] + [_칸(맥, 시트, 줄, c, "금액") for c in 열])
    for 키, 말 in (("181", "(+) 매출원가에서 배분한 금액"), ("13", "감가상각비 및 무형자산상각비"), ("10", "인건비"), ("11", "연구원 인건비")):
        if 키 in G and any(_n(G[키].get(c)) for c in 열):
            줄들.append([말] + [_칸(맥, "6.SG&A", 키, c, "금액") for c in 열])
    줄들.append(["**판매비와관리비**"] + ["**%s**" % _칸(맥, "6.SG&A", "16", c, "금액") for c in 열])
    줄들.append(["**영업이익**"] + ["**%s**" % _칸(맥, "6.SG&A", "22", c, "금액") for c in 열])
    줄들.append(["영업이익률"] + [_칸(맥, "6.SG&A", "23", c, "퍼1") for c in 열])
    L += _표(["구분"] + 열, 줄들)
    L.append("")
    실 = _칸(맥, "6.SG&A", "23", 맥.FY끝, "퍼1")
    if 영구열씀:
        L.append("영업이익률은 %s 실적 %s%s, 최종 예측 연도 %s, 영구기간 %s 추정됩니다."      # v27 구조 ⑬ — 열 이름(FY2025A)이 아니라 읽는 말
                 % (맥.열말(맥.FY끝), 실, _조(실, "이었고", "였고"), _칸(맥, "6.SG&A", "23", 맥.끝예측, "퍼1"),
                    으로(_칸(맥, "6.SG&A", "23", 맥.영구열, "퍼1"))))
    else:
        L.append("영업이익률은 %s 실적 %s%s, 최종 예측 연도 %s 추정됩니다. 영구기간 영업이익률은 따로 가정했습니다(%d절)."
                 % (맥.열말(맥.FY끝), 실, _조(실, "이었고", "였고"), 으로(_칸(맥, "6.SG&A", "23", 맥.끝예측, "퍼1")), 맥.절["영구"]))
    L.append("")
    return L


def _시(맥, 번):
    벌 = (맥.가정.get("가정") or {}).get(번) or {}
    return "공통" if "공통" in 벌 else "기준"


def _원가줄쓰나(맥, x):
    시트, 줄 = _원가본줄[x["번호"]]
    v = 맥.기[시트].get(줄) or {}
    return any(_n(v.get(c)) for c in 맥.예측열)


def _칸(맥, 시트, 줄, 열, 꼴):
    v = ((맥.기.get(시트) or {}).get(줄) or {}).get(열) if 열 else None
    if _n(v) is None:
        return "—"
    return 맥.수("R:기준:%s:%s:%s" % (시트, 줄, 열), 꼴)


def _인건비글(맥):
    import 레터 as _L                                       # noqa: PLC0415
    인 = 맥.구.get("인건비") or {}
    방식 = 인.get("산정방식")
    맥.서술("인건비.%s" % 방식)
    L = []
    P = 맥.기.get("7.Payroll") or {}
    끝 = 맥.끝예측
    if 방식 == "미분리":
        L.append("인건비는 원가 항목 안에 포함되어 있어 따로 추정하지 않았습니다.")
        L.append("")
        return L
    if 방식 == "매출액비율":
        L.append("인건비는 매출액 대비 비율(최종 예측 연도 %s)로 추정했습니다." % _칸(맥, "7.Payroll", "44", 끝, "퍼1"))
        L.append("")
        return L
    경로 = 인.get("인원경로")
    맥.서술("인건비.인원경로.%s" % 경로)
    인원말 = {"물량연동": "판매량 지수(인원 가중)에 탄력성 %s 적용해 늘렸습니다" % 을(맥.수("S:521:기준", "지수2")) if _n(_L._시점값(맥.가정, "521", "기준")) is not None else "생산능력에 연동했습니다",
            "증가율": "연 증가율로 늘렸습니다", "수준": "기간마다 가정했습니다"}.get(경로, "")
    글 = "인건비는 인원에 1인당 평균급여를 곱해 추정했습니다." + ((" 인원은 %s." % 인원말) if 인원말 else "")
    if 경로 != "수준" and _n(_L._시점값(맥.가정, "503", "기준")) is not None:
        글 += " 1인당 평균급여는 기준 수준 %s(연환산)에서 임금상승률(최종 예측 연도 %s)로 늘렸습니다." % (
            맥.수("S:503:기준", "금액"), 맥.수("A:504:%s:%s" % (_시(맥, "504"), 끝), "퍼1"))
    성 = 인.get("성과급")
    if 성 != "없음" and 경로 != "수준" and "43" in P:
        맥.서술("인건비.성과급.%s" % 성)
        글 += " 성과급은 %s 영업이익의 %s 가정했습니다." % ("성과급 차감 후" if 성 == "차감후" else "성과급 차감 전",
                                            으로(맥.수("A:510:%s:%s" % (_시(맥, "510"), 끝), "퍼0")))
    L.append(글)
    L.append("")
    열 = [맥.FY끝] + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    줄들 = []
    for 키, 말, 꼴 in (("10", "기말 인원", "명"), ("12", "1인당 평균급여", "금액"), ("34", "성과급 차감 전 인건비", "금액"),
                    ("43", "성과급", "금액"), ("14", "인건비 합계", "금액"), ("44", "매출액 대비 인건비율", "퍼1")):
        if 키 in P and any(_n(P[키].get(c)) is not None for c in 열):
            if 키 in ("43", "34") and 성 == "없음":            # R1b — 성과급을 선언하지 않았으면 「성과급 차감 전」 줄도 없다(인건비 합계와 같다 · ⑧)
                continue
            줄들.append([말] + [_칸(맥, "7.Payroll", 키, c, 꼴) for c in 열])
    if 줄들:
        L += _표(["구분"] + 열, 줄들)
        L.append("")
        if any(r[0] == "1인당 평균급여" for r in 줄들) and 맥.FY끝 in 열:
            L.append("실적 기간의 1인당 평균급여는 급여를 인원으로 나눈 값입니다. 공시된 1인 평균 급여와 범위가 다를 수 있습니다.")
            L.append("")
    return L


# ── 재투자

def 재투자절(맥, 번):
    """재투자 — 설비(CAPEX · 감가상각) + 운전자본(회전일수 · 미지급 항목). 본편은 둘을 따로 절로 세운다(`설비글` · `운전글`)."""
    return ["## %d. 재투자" % 번, ""] + 설비글(맥) + 운전글(맥)


def 설비글(맥):
    """CAPEX(유지 규칙 · 프로젝트 · 건설중인자산 · 상각 · 무형)의 문단과 표."""
    import 레터 as _L                                       # noqa: PLC0415
    L = []
    구 = 맥.구
    투 = 구.get("투자") or {}
    끝 = 맥.끝예측
    유지 = 투.get("유지규칙")
    맥.서술("투자.유지.%s" % 유지, "투자.상각.%s" % 투.get("상각방식"), "투자.무형.%s" % 투.get("무형상각"))
    자산군 = 투.get("자산군") or []
    if 유지 == "취득원가비율":
        g = 투.get("유지기준자산군") or 1
        L.append("유지 CAPEX는 %s 취득원가에 유지율(최종 예측 연도 %s)을 곱해 추정했습니다."
                 % (_L._목록이름(자산군, g, "설비"), 맥.수("A:850:%s:%s" % (_시(맥, "850"), 끝), "퍼1")))
    elif 유지 == "직접":
        L.append("유지 CAPEX는 예측 기간마다 금액으로 입력했습니다.")
    elif 유지 == "상각연동":
        L.append("유지 CAPEX는 그 기간의 감가상각비와 같은 금액으로 가정했습니다.")
    elif 유지 == "판매량연동":
        L.append("유지 CAPEX는 기준 금액을 판매량 지수에 연동해 늘렸습니다.")
    프 = 투.get("프로젝트") or []
    if 프:
        맥.서술("투자.프로젝트")
        L.append("유지 CAPEX와 별도로 프로젝트 %d건의 지출을 연도별 금액으로 반영했습니다. 프로젝트는 %s." % (len(프), 입니다(" · ".join(x.get("이름") or "" for x in 프))))
    if 투.get("건설중인자산대체") == "예" and _n(_L._가정값(맥.가정, "853", _시(맥, "853"), 맥.첫예측)):
        맥.서술("투자.건설중대체")
        L.append("%s의 건설중인자산 %s %s에 본계정으로 대체해 그 뒤부터 상각했습니다."
                 % (재무날말(맥), 은(맥.수("A:853:%s:%s" % (_시(맥, "853"), 맥.첫예측), "금액")), 맥.열말(맥.첫예측)))
    if 투.get("상각방식") == "빈티지":
        수명 = " · ".join("%s %s년" % (g.get("이름") or "자산군 %d" % g["번호"], 맥.수("S:80%d:기준" % g["번호"], "수0"))
                        for g in 자산군 if _n(_L._시점값(맥.가정, "80%d" % g["번호"], "기준")) is not None)
        L.append("감가상각비는 취득 시기별로 나누어 정액 상각했습니다%s." % ((". 내용연수는 %s" % 입니다(수명)) if 수명 else ""))
    else:
        L.append("감가상각비는 기초 유형자산에 감가상각률을 곱해 추정했습니다.")
    if 투.get("무형상각") == "금액" and _n(_L._시점값(맥.가정, "856", "기준")) is not None:
        L.append("무형자산상각비는 연 %s 가정했습니다." % 으로(맥.수("S:856:기준", "금액")))
    elif 투.get("무형상각") == "금액" and _n(_L._가정값(맥.가정, "856", _시(맥, "856"), 끝)) is not None:
        L.append("무형자산상각비는 연 %s 가정했습니다." % 으로(맥.수("A:856:%s:%s" % (_시(맥, "856"), 끝), "금액")))
    L.append("")
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    X = 맥.기["8.CapEx"]
    줄들 = []
    if "101" in X:
        줄들.append(["유지 CAPEX%s" % (" (환율 조정 전)" if ((맥.구.get("환율") or {}).get("경로") or "없음") != "없음" else "")]
                   + [_칸(맥, "8.CapEx", "101", c, "금액") for c in 열])
    for x in 프:
        키 = "%d" % (140 + x["번호"])
        if 키 in X:
            줄들.append(["%s CAPEX" % x.get("이름")] + [_칸(맥, "8.CapEx", 키, c, "금액") for c in 열])
    # 1.1.2 — CAPEX 합계의 구성을 다 싣는다(성장 CAPEX · 그 밖 — 숨은 구성 줄이 없게 · 정합 「표 구성 합」)
    if "102" in X and any(abs(_n((X.get("102") or {}).get(c)) or 0.0) > 0 for c in 열):
        줄들.append(["성장 CAPEX(매출 연동)"] + [_칸(맥, "8.CapEx", "102", c, "금액") for c in 열])
    if "31" in X:
        든 = ["101"] * ("101" in X) + ["%d" % (140 + x["번호"]) for x in 프 if "%d" % (140 + x["번호"]) in X] + ["102"] * ("102" in X)
        남 = {c: ["−", "R:기준:8.CapEx:31:%s" % c, ["합"] + ["R:기준:8.CapEx:%s:%s" % (k, c) for k in 든]] for c in 열}
        if any(abs(_n(맥.식값(남[c])) or 0.0) > max(0.5, 0.005 * abs(_n((X.get("31") or {}).get(c)) or 0.0)) for c in 열):
            줄들.append(["그 밖(환율 조정 · 무형 취득)"] + [맥.식(남[c], "금액") for c in 열])
    for 키, 말, 꼴 in (("31", "**CAPEX 합계**", "금액"), ("34", "감가상각비 및 무형자산상각비", "금액"), ("36", "CAPEX ÷ 감가상각비", "배"),
                    ("35", "CAPEX ÷ 매출액", "퍼1")):
        if 키 in X:
            줄들.append([말] + [_칸(맥, "8.CapEx", 키, c, 꼴) for c in 열])
    L += _표(["구분"] + 열, 줄들)
    L.append("")
    return L


def 운전글(맥):
    """운전자본(회전일수 · 순운전자본 표 · 미지급 항목 · 지급 시점 보정)의 문단과 표."""
    import 레터 as _L                                       # noqa: PLC0415
    L = []
    구 = 맥.구
    끝 = 맥.끝예측
    운 = 구.get("운전자본") or {}
    맥.서술("운전자본.재고.%s" % 운.get("재고회전기준"), "운전자본.매입채무.%s" % 운.get("매입채무회전기준"))
    회 = []
    for 번호, 말 in (("178", "매출채권"), ("182", "재고자산"), ("186", "매입채무")):
        if _n(_L._가정값(맥.가정, 번호, _시(맥, 번호), 끝)) is not None:
            회.append("%s %s" % (말, 맥.수("A:%s:%s:%s" % (번호, _시(맥, 번호), 끝), "일")))
    기준말 = []
    if 운.get("재고회전기준") == "발생원가":
        기준말.append("재고자산 회전일수는 성과급 차감 전 발생원가를")
    if 운.get("매입채무회전기준") == "재료비및경비":          # 엔진 — 5번 재료비 및 경비 소계 + 6번(판매비와관리비)에 선 원가 줄(운전자본.py)
        판 = [x.get("이름") for x in 맥.구.get("원가줄") or [] if x.get("시트") == 6 and x.get("이름")]
        기준말.append("매입채무 회전일수는 재료비 및 경비%s를" % (("(판매비와관리비의 %s 포함)" % _나열(판)) if 판 else ""))
    L.append("순운전자본은 매출채권 · 재고자산 · 매입채무를 회전일수로 추정했습니다%s.%s"
             % ((". 최종 예측 연도의 회전일수는 %s" % 입니다(" · ".join(회))) if 회 else "", (" %s 기준으로 산정했습니다." % ", ".join(기준말)) if 기준말 else ""))
    L.append("")
    W = 맥.기["9.WC"]
    줄들 = [["순운전자본 (기말)"] + [_칸(맥, "9.WC", "14", c, "금액") for c in [맥.FY끝, 맥.기준일열] + 맥.예측열 if c],
           ["순운전자본 증감"] + [_칸(맥, "9.WC", "18", c, "금액") for c in [맥.FY끝, 맥.기준일열] + 맥.예측열 if c]]
    머 = [c for c in [맥.FY끝, 맥.기준일열] + 맥.예측열 if c]
    if 맥.FY끝 == 맥.기준일열:
        머 = [맥.FY끝] + 맥.예측열
        줄들 = [[r[0]] + r[2:] if len(r) > len(머) + 1 else r for r in 줄들]
    L += _표(["구분"] + 머, 줄들)
    L.append("")
    미 = 운.get("미지급항목") or []
    if 미 and "111" in 맥.기["2.DCF"]:
        맥.서술("운전자본.미지급")
        L.append("%s 현재 미지급된 %s 지급 시점에 맞춰 현금으로 나간다고 가정했습니다. 예측 기간마다 새로 발생하는 금액과 지급하는 금액의 차이를 "
                 "미지급 항목 증감으로 FCFF에 더했습니다." % (재무날말(맥), 은(_나열([x.get("이름") for x in 미]))))
        줄들 = []
        for x in 미:
            키 = "2%d7" % x["번호"]
            if 키 in W:
                줄들.append(["%s 기말 잔액" % x.get("이름")] + [_칸(맥, "9.WC", 키, c, "금액") for c in [맥.기준일열] + 맥.예측열])
        줄들.append(["미지급 항목 증감 (FCFF 가산)"] + ["—"] + [_칸(맥, "2.DCF", "111", c, "금액") for c in 맥.예측열])
        L.append("")
        L += _표(["구분"] + [맥.기준일열] + 맥.예측열, 줄들)
        L.append("")
        if 운.get("지급시점보정") == "예" and "121" in 맥.기["2.DCF"]:
            맥.서술("운전자본.지급시점보정")
            L.append("현금흐름은 기간 중간 시점에 발생한다고 가정해 할인하지만 미지급 항목은 정해진 달에 지급됩니다. 그 차이를 지급 시점 보정으로 계산해 영업가치에 %s 반영했습니다."
                     % 맥.수("R:기준:2.DCF:121", "금액"))
            L.append("")
    return L


# ── 법인세 · FCFF

def 세금절(맥, 번):
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. 법인세와 FCFF" % 번, ""]
    법 = 맥.구.get("법인세") or {}
    끝 = 맥.끝예측
    공제 = (any(_n(_L._가정값(맥.가정, b, 시, 끝)) for b in ("200", "940") for 시 in 시나리오들) or bool(_n(_L._시점값(맥.가정, "941", "기준")))
           or 법.get("세액공제이월") == "예" or 법.get("무형공제") == "예" or 법.get("그밖의공제") == "예")     # 인쇄 조건 — 세액공제가 없는 회사에 「뺀」 을 찍지 않는다
    글 = "법인세는 영업이익에 적용세율(최종 예측 연도 %s)을 곱%s 금액입니다." % (맥.수("A:196:%s:%s" % (_시(맥, "196"), 끝), "퍼1"), "하고 세액공제를 뺀" if 공제 else "한")
    if 법.get("세액공제이월") == "예":
        맥.서술("법인세.세액공제이월")
        글 += " 세액공제는 과세표준의 %s 한도로 적용하고 한도를 넘는 금액은 다음 기간으로 이월했습니다." % 을(맥.수("S:208:기준", "퍼1"))
        if _n(_L._시점값(맥.가정, "941", "기준")):
            글 += " %s의 이월 세액공제는 %s." % (재무날말(맥), 입니다(맥.수("S:941:기준", "금액")))
        if all("132" in 맥.R[s]["2.DCF"] and not isinstance(맥.R[s]["2.DCF"]["132"], dict) for s in 시나리오들):
            if any(abs(_n(맥.R[s]["2.DCF"]["132"]) or 0.0) > 0.5 for s in 시나리오들):
                글 += (" 최종 예측 연도 말까지 쓰지 못한 세액공제는 이월 기한 안에서 한도만큼 영구기간에 쓴다고 가정했습니다. "
                      "그 절세액의 현재가치를 이월 세액공제 조정으로 영업가치에 더했습니다. 조정액은 %s." % 입니다(" · ".join(
                          "%s %s" % (s, 맥.수("R:%s:2.DCF:132" % s, "금액")) for s in 시나리오들)))
            else:
                글 += " 최종 예측 연도 말에 남는 세액공제가 없어 이월 세액공제 조정은 없습니다."
    if 법.get("그밖의공제") == "예" and "116" in 맥.기["10.Tax"] and any(_n(맥.기["10.Tax"]["116"].get(c)) for c in 맥.예측열):
        맥.서술("법인세.그밖의공제")
        글 += " 투자세액공제가 아닌 세액공제도 같은 한도 안에서 반영했습니다."
    L.append(글)
    L.append("")
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    T = 맥.기["10.Tax"]
    줄들 = []
    for 키, 말, 꼴 in (("10", "영업이익", "금액"), ("12", "산출세액", "금액"), ("13", "(−) 세액공제", "금액"),
                    ("14", "(−) 이월결손금 법인세효과", "금액"), ("15", "영업이익에 대한 법인세", "금액"), ("16", "유효세율", "퍼1")):
        if 키 in T and any(_n(T[키].get(c)) for c in 열):
            줄들.append([말] + [_칸(맥, "10.Tax", 키, c, 꼴) for c in 열])
    L += _표(["구분"] + 열, 줄들)
    L.append("")
    L.append("**표. 연도별 FCFF**")
    L.append("")
    D = 맥.기["2.DCF"]
    줄들 = []
    for 키, 말, 꼴 in (("15", "영업이익", "금액"), ("18", "(−) 영업이익에 대한 법인세", "금액"), ("19", "NOPLAT", "금액"),
                    ("20", "(+) 감가상각비 및 무형자산상각비", "금액"), ("21", "(−) CAPEX", "금액"),
                    ("22", "(−) 순운전자본 증감", "금액"), ("111", "(±) 미지급 항목 증감", "금액"),
                    ("112", "(+) 한시적 현금흐름 (세후)", "금액"), ("23", "**FCFF**", "금액"),
                    ("35", "현가계수", "지수4"), ("36", "FCFF의 현재가치", "금액")):
        if 키 in D and isinstance(D[키], dict):
            줄들.append([말] + [_칸(맥, "2.DCF", 키, c, 꼴) for c in 맥.예측열])
    L += _표(["구분"] + 맥.예측열, 줄들)
    L.append("")
    L.append("예측기간 FCFF 현재가치의 합은 %s." % 입니다(맥.수("R:기준:2.DCF:40", "금액")))
    L.append("")
    return L


# ── 할인율

def 할인율절(맥, 번):
    L = ["## %d. 할인율" % 번, ""]
    할 = 맥.구.get("할인") or {}
    W = "R:기준:3.WACC:%s:%s"
    따로 = 할.get("영구WACC") == "따로"
    같음 = abs((_n(맥.값("R:기준:WACC:예측기간:WACC")) or 0) - (_n(맥.값("R:기준:WACC:영구기간:WACC")) or 0)) < 1e-12
    맥.서술("할인.영구WACC.%s" % 할.get("영구WACC"), "할인.무위험이자율.%s" % 할.get("무위험이자율"),
           "할인.타인자본비용.%s" % 할.get("타인자본비용"), "할인.베타출처.%s" % 할.get("베타출처"))
    글 = "자기자본비용은 CAPM으로 산정했습니다."
    if 할.get("무위험이자율") == "부도스프레드차감":
        글 += " 무위험이자율은 국채 수익률(%s)에서 국가 부도스프레드(%s)를 뺀 %s." % (
            맥.수(W % ("101", "예측값"), "퍼2") if "101" in 맥.기["3.WACC"] else 맥.수("W:예측기간:국채수익률", "퍼2"),
            맥.수(W % ("102", "예측값"), "퍼2") if "102" in 맥.기["3.WACC"] else 맥.수("W:예측기간:부도스프레드", "퍼2"),
            입니다(맥.수(W % ("7", "예측값"), "퍼2")))
    else:
        글 += " 무위험이자율은 %s." % 입니다(맥.수(W % ("7", "예측값"), "퍼2"))
    글 += " MRP는 %s." % 입니다(맥.수(W % ("8", "예측값"), "퍼2"))
    피어 = [x.get("이름") for x in 할.get("유사기업") or [] if x.get("이름")]
    구조말 = 자본구조말(맥, "예측기간", "예측값")              # 목표 D/E 를 적은 판만 「목표 자본구조」(엔진 S7-09 — 비우면 평가기준일 D/E)
    if 할.get("베타출처") == "유사기업표" and 피어:
        대표 = "중앙값" if 할.get("베타대표값", "중앙값") == "중앙값" else "평균"
        글 += " Peer group은 %s %d곳입니다. Levered Beta는 Peer group Unlevered Beta의 %s %s %s 환산한 %s." % (
            " · ".join(피어), len(피어), 대표, 을(맥.수(W % ("10", "예측값"), "지수3")), 으로(구조말), 입니다(맥.수(W % ("15", "예측값"), "지수3")))
    else:
        글 += " Levered Beta는 Unlevered Beta %s %s 다시 환산한 %s." % (을(맥.수(W % ("10", "예측값"), "지수3")), 으로(구조말), 입니다(맥.수(W % ("15", "예측값"), "지수3")))
    if 할.get("타인자본비용") == "관측수익률":
        글 += " 세전 타인자본비용은 회사채 수익률 관측치 %s." % 입니다(맥.수(W % ("19", "예측값"), "퍼2"))
    else:
        글 += " 세전 타인자본비용은 무위험이자율에 신용스프레드(%s)를 더한 %s." % (맥.수(W % ("21", "예측값"), "퍼2"), 입니다(맥.수(W % ("19", "예측값"), "퍼2")))
    L.append(글)
    L.append("")
    구간 = [("예측기간", "예측값")] + ([("영구기간", "영구값")] if 따로 else [])
    줄들 = []
    for 키, 말, 꼴 in (("7", "무위험이자율 (Rf)", "퍼2"), ("8", "MRP", "퍼2"), ("10", "Unlevered Beta", "지수3"),
                    ("12", "현금 조정 Unlevered Beta", "지수3"), ("15", "Levered Beta", "지수3"), ("16", "자기자본비용 (Ke)", "퍼2"),
                    ("19", "세전 타인자본비용 (Kd)", "퍼2"), ("20", "세후 타인자본비용", "퍼2"), ("23", "자기자본 비중", "퍼1"),
                    ("24", "타인자본 비중", "퍼1"), ("27", "**WACC**", "퍼2")):
        v = 맥.기["3.WACC"].get(키)
        if not isinstance(v, dict):
            continue
        if 키 == "12" and all(abs((_n(v.get(b)) or 0) - (_n((맥.기["3.WACC"].get("10") or {}).get(b)) or 0)) < 1e-12 for _a, b in 구간):
            continue
        줄들.append([말] + [맥.수(W % (키, b), 꼴) if _n(v.get(b)) is not None else "—" for _a, b in 구간])
    L += _표(["구분"] + [a for a, _b in 구간], 줄들)
    L.append("")
    if 따로 and 같음:
        L.append("영구기간에도 예측기간과 같은 WACC 값을 적용했습니다.")
        L.append("")
    elif 따로:
        L.append("영구기간의 WACC 값은 %s. 예측기간의 %s 다릅니다." % (입니다(맥.수("R:기준:WACC:영구기간:WACC", "퍼2")), 과(맥.수("R:기준:WACC:예측기간:WACC", "퍼2"))))
        L.append("")
    if 할.get("연도별WACC") == "사용" and "33" in 맥.기["2.DCF"]:
        맥.서술("할인.연도별WACC.사용")
        열들 = [c for c in 맥.예측열 if _n((맥.기["2.DCF"].get("33") or {}).get(c)) is not None]
        L.append("예측 연도마다 다른 WACC 값을 적용했습니다.")
        L.append("")
        L += _표(["기간"] + [맥.표기(c) for c in 열들], [["WACC"] + [맥.수("R:기준:2.DCF:33:%s" % c, "퍼2") for c in 열들]])
        L.append("")
    피어줄 = []
    for x in 할.get("유사기업") or []:
        키 = "%d" % (110 + x["번호"])
        v = 맥.기["3.WACC"].get(키)
        if isinstance(v, dict) and v:
            칸 = list(v.keys())[0]
            피어줄.append([x.get("이름"), 맥.수(W % (키, 칸), "지수3")])
    for 키, 말 in (("121", "평균"), ("122", "중앙값")):
        v = 맥.기["3.WACC"].get(키)
        if isinstance(v, dict) and v and 피어줄:
            칸 = list(v.keys())[0]
            피어줄.append(["**%s**" % 말, 맥.수(W % (키, 칸), "지수3")])
    if 피어줄:
        L += _표(["Peer group", "Unlevered Beta"], 피어줄)
        L.append("")
    L += 피어회사표(맥)                                        # 1.1.2 — 회사별 βL · 부채비율 · 현금 몫 · βU · 채택 · 제외 까닭(재료 `유사기업βU`)
    import 레터갭 as _갭                                     # noqa: PLC0415
    # 레터 v27 6단계 — 아래 보조 분석은 추정 블록이면 소절 통째로 부록 「추정 블록의 근거 표」 에(`블록소절`)
    L += 블록소절(맥, "Unlevered Beta의 정밀도 가중", _갭.축소줄(맥))          # 1.1.3(B1) — 정밀도 가중 축소(회귀 βU · 업종 βU · 가중치 · 사후 · 채택)
    L += 블록소절(맥, "내재 ERP와 영구성장률", _갭.ERP짝줄(맥))                # 1.1.3(B3) — 성숙시장 ERP 의 끝 성장과 g
    import 레터안정 as _안                                    # noqa: PLC0415
    L += 블록소절(맥, "영구기간 자본비용 비교", _안.영구베타줄(맥))           # 1.1.5 — 영구기간 자본비용의 세 판(업종 성숙 평균 · Levered Beta 1.0 · 수렴 없음)
    독 = (맥.가정.get("독자근거") or {}).get("WACC")
    if isinstance(독, str) and 독.strip():
        글 = 레터이야기.펴기(맥, 독, "독자근거.WACC")
        if 글:
            L.append(글)
            L.append("")
    # 1.1.20 — 「대안 산정 방법으로 계산한 할인율과 그때의 주당가치는 부록 B에 있습니다」(문서 안내 · 원칙 3)는 지웠다 — 부록 차례가 자리를 말한다
    return L


# ── 영구가치

def 영구절(맥, 번):
    """Terminal Value — R1b(L6): 영구기간 ROIC 은 새 투자의 수익률(RONIC)이라 새 투자만 초과수익이 0 이고 기존 설비의 초과수익은 남는다고
    적는다. 기존 투하자본의 수익률 · 총 재투자(유지 투자 + 순투자) ÷ 매출액을 표에 싣고, 영업이익률이 최종 예측 연도보다 높은 까닭이
    감가상각비(정상 유지 투자 수준)라면 그 크기를 적는다. 검증 범위는 저자가 적은 범위마다(L7)."""
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. Terminal Value" % 번, ""]
    영 = 맥.구.get("영구가치") or {}
    D = "R:기준:2.DCF:%s"
    기준 = 영.get("영구이익기준")
    맥.서술("영구.%s" % 기준, "영구.상각.%s" % 영.get("영구상각"))
    수렴 = [x for x in 맥.구.get("매출구분") or [] if x.get("경로") == "수준" and x.get("번호", 6) < 6]
    끝, TV = 맥.끝예측, 맥.영구열
    검증 = []
    if 기준 == "영구열":
        글 = "Terminal Value는 영구기간의 손익을 직접 추정해 산정했습니다."
        if 수렴:
            글 += " 영구기간 매출액은 최종 예측 연도 말의 판매량과 정상 수준 %s에 영구성장률을 반영한 금액입니다." % 수렴명칭(맥, [x for x in 수렴 if x.get("단가경로") == "수렴"] or 수렴)
        else:
            글 += " 영구기간 매출액은 최종 예측 연도 매출액에 영구성장률을 반영한 금액입니다."
        글 += " 영구기간 영업이익률 %s 그 매출과 비용 가정에서 나온 결과입니다." % 은(맥.수(D % "42", "퍼1"))
        검증 = 검증범위줄(맥, _n(맥.값(D % "42")))
    else:
        글 = "영구기간 영업이익률은 Normalization 영업이익률로 가정한 %s." % 입니다(맥.수(D % "42", "퍼1"))
    L.append(글)
    L.append("")
    상 = "R:기준:2.DCF:16:%s"
    매 = "R:기준:2.DCF:11:%s"
    if TV and 끝 and all(_n(맥.값(k % c)) for k in (상, 매) for c in (끝, TV)):
        m끝, mTV = _n(맥.값("R:기준:요약:마지막해영업이익률")), _n(맥.값(D % "42"))
        d끝, dTV = _n(맥.값(상 % 끝)) / _n(맥.값(매 % 끝)), _n(맥.값(상 % TV)) / _n(맥.값(매 % TV))
        if mTV is not None and m끝 is not None and mTV - m끝 > 0.005 and d끝 - dTV > 0.005:
            L.append("영구기간 영업이익률이 최종 예측 연도(%s)의 %s보다 높은 것은 주로 감가상각비 때문입니다. 감가상각비는 매출액의 %s에서 %s 줄어드는 것으로 추정됩니다%s." % (
                맥.열말(끝), 맥.수("R:기준:요약:마지막해영업이익률", "퍼1"), 맥.식(["÷", 상 % 끝, 매 % 끝], "퍼1"), 으로(맥.식(["÷", 상 % TV, 매 % TV], "퍼1")),
                "(영구기간의 감가상각비는 정상 유지 투자 수준으로 가정)" if 영.get("영구상각") == "정상유지투자" else ""))
            L.append("")
    L += 검증
    ROIC입력 = _n(_L._시점값(맥.가정, "219", "기준")) is not None
    L.append("영구기간 FCFF는 NOPLAT에서 재투자를 뺀 금액입니다. 재투자율은 영구성장률 %s 영구기간 ROIC %s 나눈 %s."
             % (을(맥.수(D % "47", "퍼2")), 으로(맥.수(D % "48", "퍼2")), 입니다(맥.수(D % "49", "퍼1"))))
    뜻 = "이 ROIC은 영구기간에 새로 하는 투자의 수익률, 곧 RONIC입니다."      # 용어 병기가 처음 한 번 「신규 투자 수익률(RONIC)」 로 편다
    if ROIC입력:
        뜻 += " 영구기간 ROIC은 직접 설정한 가정입니다."
    else:
        뜻 += " 신규 투자의 수익률은 WACC 값과 같아 초과수익이 없다고 가정했습니다. 기존 설비가 내는 초과수익은 영구기간에도 유지된다고 가정했습니다."
    if _n(맥.값(D % "86")) and _n(맥.값(D % "45")) is not None:
        뜻 += " 영구기간 NOPLAT을 최종 예측 연도 말 투하자본으로 나눈 기존 자본의 수익률은 %s." % 입니다(맥.식(["÷", D % "45", D % "86"], "퍼1"))
    # S8-05 — RONIC 의 두 값(엔진 요약 「증분ROIC」 · 「RONIC증분주당가치」 — 값에 쓰지 않는다)
    if 맥.값("R:기준:요약:RONIC증분주당가치") is not None and 맥.값("R:기준:요약:증분ROIC") is not None:
        뜻 += (" 영구기간 ROIC을 예측 끝의 증분 ROIC %s로 두면 주당가치는 %s." % (맥.수("R:기준:요약:증분ROIC", "퍼1"),
                                                                   입니다(맥.수("R:기준:요약:RONIC증분주당가치", "주당"))))
    L.append(뜻)
    L.append("")
    if 영.get("영구상각") == "정상유지투자" and "601" in 맥.기["8.CapEx"] and 맥.영구열:
        L.append("영구기간의 감가상각비와 유지 투자는 정상 수준(정상 유지 CAPEX %s)으로 가정했습니다." % _칸(맥, "8.CapEx", "601", 맥.영구열, "금액"))
        L.append("")
    if 영.get("초과상각조정") == "예" and "131" in 맥.기["2.DCF"]:
        맥.서술("영구.초과상각조정")
        L.append("예측기간에 취득한 설비의 장부 상각은 영구기간 첫해 뒤에도 %s년 동안 정상 수준을 넘습니다. 그동안의 법인세 절감 효과를 초과 상각 조정 %s 영업가치에 더했습니다."
                 % (맥.수("S:857:기준", "수0"), 으로(맥.수(D % "131", "금액"))))
        L.append("")
    줄들 = [["영구기간 매출액", 맥.수(D % "41", "금액")], ["영구기간 영업이익률", 맥.수(D % "42", "퍼1")],
           ["영구기간 ROIC (새 투자의 수익률)", 맥.수(D % "48", "퍼2")]]
    if _n(맥.값(D % "86")) and _n(맥.값(D % "45")) is not None:
        줄들.append(["기존 자본의 수익률 (영구기간 NOPLAT ÷ %s 말 투하자본)" % 맥.열말(끝), 맥.식(["÷", D % "45", D % "86"], "퍼1")])
    순 = (맥.기["2.DCF"].get("113") or {}) if TV else {}
    유지 = (맥.기["8.CapEx"].get("601") or {}) if TV else {}
    if isinstance(순, dict) and isinstance(유지, dict) and _n(순.get(TV)) is not None and _n(유지.get(TV)) is not None:
        총 = ["합", "R:기준:8.CapEx:601:%s" % TV, "R:기준:2.DCF:113:%s" % TV]
        줄들.append(["영구기간 총 재투자 (유지 투자 + 순투자)", 맥.식(총, "금액")])
        줄들.append(["총 재투자 ÷ 영구기간 매출액", 맥.식(["÷", 총, D % "41"], "퍼1")])
    줄들 += [["영구기간 FCFF", 맥.수(D % "50", "금액")], ["Terminal Value", 맥.수(D % "51", "금액")],
           ["Terminal Value의 현재가치", 맥.수(D % "54", "금액")],
           ["Terminal Value 비중 (영업가치 대비)", 맥.수("R:기준:요약:영구가치비중", "퍼1")]]
    L += _표(["구분", "기준"], 줄들)
    L.append("")
    import 레터안정 as _안                                    # noqa: PLC0415
    L += 블록소절(맥, "영구기간의 재투자와 ROIC 점검", _안.재투자줄(맥))      # 1.1.5 — 마지막 예측 해와 영구기간의 재투자 정합 · 연장 감사 · 연구개발 자본화 측정(블록이면 부록으로)
    독 = (맥.가정.get("독자근거") or {})
    for 키 in ("212", "213", "219", "종착"):
        if isinstance(독.get(키), str) and 독[키].strip():
            글 = 레터이야기.펴기(맥, 독[키], "독자근거.%s" % 키)
            if 글:
                L.append(글)
                L.append("")
    return L


# ── 주주가치

def 주주가치절(맥, 번):
    L = ["## %d. 주주가치와 주당가치" % 번, ""]
    D = 맥.기["2.DCF"]
    K = "R:기준:2.DCF:%s"
    import 레터 as _L                                       # noqa: PLC0415
    줄들 = [["예측기간 FCFF 현재가치 합계", 맥.수(K % "40", "금액")], ["(+) Terminal Value의 현재가치", 맥.수(K % "54", "금액")]]
    쓴 = ["40", "54"]
    for 키, 말 in _L.영업가치조정줄:
        if 키 in D and not isinstance(D[키], dict) and _n(D.get(키)):
            줄들.append([말, 맥.수(K % 키, "금액")])
            쓴.append(키)
    남은 = (_n(D.get("58")) or 0.0) - sum(_n(D.get(k)) or 0.0 for k in 쓴)
    if abs(남은) > 0.5:                                      # 레터가 이름을 모르는 영업가치 조정 줄 — 표가 맞게 남은 몫을 한 줄로
        줄들.append(["(±) 그 밖의 영업가치 조정", 맥.식(["−", K % "58", ["합"] + [K % k for k in 쓴]], "금액")])
        맥.알림.append("영업가치에 레터가 이름을 모르는 조정 줄이 있다(%s) — 레터.영업가치조정줄 에 번호와 이름을 더한다" % 꼴글표(남은, 맥))
    줄들.append(["**영업가치**", "**%s**" % 맥.수(K % "58", "금액")])
    for 키, 말 in (("59", "(+) 비영업자산"), ("60", "(+) 현금 및 단기금융자산"), ("61", "(−) 이자부부채"), ("62", "(−) 우선주"),
                 ("63", "(−) 비지배지분"), ("64", "(−) 순확정급여부채"), ("65", "(±) 기타 조정항목")):
        if _n(D.get(키)):
            줄들.append([말, 맥.수(K % 키, "금액")])
    이월 = 이월판(맥)
    if 이월:                                                 # 2026-10-25 날짜 둘 — 재무 자료 기준일 값에서 평가기준일 값으로(2번 161~167)
        줄들.append(["**재무 자료 기준일 주주가치**", "**%s**" % 맥.수(K % "161", "금액")])
        if (맥.기.get("요약") or {}).get("이월적용", True) is not False:
            줄들.append(["(×) 이월 계수 (1 + 자기자본비용 %s)^%s" % (맥.수(K % "163", "퍼2"), 맥.수(K % "162", "수4")), 맥.수(K % "164", "지수4")])
        줄들.append(["(±) 두 날 사이의 자본거래 현금", 맥.수(K % "165", "금액")])
        줄들.append(["**평가기준일 주주가치**", "**%s**" % 맥.수(K % "66", "금액")])
    else:
        줄들.append(["**주주가치**", "**%s**" % 맥.수(K % "66", "금액")])
    if 이월:
        if _n(D.get("151")):
            줄들.append(["재무 자료 기준일 적용 주식수 (유통 %s + 희석 %s)" % (맥.수(K % "67", "주"), 맥.수(K % "151", "주")), 맥.수(K % "166", "주")])
        else:
            줄들.append(["재무 자료 기준일 유통주식수", 맥.수(K % "166", "주")])
        줄들.append(["(±) 두 날 사이의 주식 수 변동", 맥.수(K % "167", "주")])
        줄들.append(["평가기준일 적용 주식수", 맥.수(K % "152", "주")])
    elif _n(D.get("151")):
        줄들.append(["적용 주식수 (유통 %s + 희석 %s)" % (맥.수(K % "67", "주"), 맥.수(K % "151", "주")), 맥.수(K % "152", "주")])
    else:
        줄들.append(["유통주식수", 맥.수(K % "67", "주")])
    줄들.append(["**주당가치**", "**%s**" % 맥.수(K % "68", "주당")])
    L += _표(["구분", "기준"], 줄들)
    L.append("")
    if 이월:
        L += 이월글(맥)
        L += 사이표(맥)
    L += 후사건(맥)
    다른 = [s for s in ("비관", "낙관") if abs((_n(맥.R[s]["2.DCF"].get("59")) or 0) - (_n(D.get("59")) or 0)) > 0.5]
    if 다른:
        L.append("비영업자산은 평가조정을 반영해 %s 시나리오에서 %s 기준 시나리오와 다릅니다." % (
            " · ".join(다른), 으로(" · ".join(맥.수("R:%s:2.DCF:59" % s, "금액") for s in 다른))))
        L.append("")
    return L                                                # 1.1.20 — 「계정별 내역은 부록 C에 있습니다」(원칙 3)는 지웠다


# ── 시나리오

def 시나리오폭글(맥):
    """S9-12 — 비관 ↔ 낙관 주주가치 폭이 4배를 넘거나 비관 주주가치가 0 이하면 레터가 먼저 말한다(EV 폭 · 순부채 ÷ EV 와 함께 — 레버리지)."""
    비주, 낙주 = _n(맥.값("R:비관:요약:주주가치")), _n(맥.값("R:낙관:요약:주주가치"))
    비EV = _n(맥.값("R:비관:요약:영업가치"))
    if 비주 is None or 낙주 is None or not (비주 <= 0 or 낙주 / 비주 > 4.0):
        return []
    주 = 맥.식(["÷", "R:낙관:요약:주주가치", "R:비관:요약:주주가치"], "배") if 비주 > 0 else None
    ev = 맥.식(["÷", "R:낙관:요약:영업가치", "R:비관:요약:영업가치"], "배") if (비EV or 0) > 0 else "—"
    # 1.1.20 — 순부채의 부호를 본다(ADDER80 백테스트: 순현금 회사에도 「순부채가 차이를 키운 결과」 가 섰다). 순부채 등 = 영업가치 − 주주가치(기준 시나리오).
    # 양수면 순부채가 주주가치의 폭을 영업가치의 폭보다 키우고, 0 이하(순현금)면 키우지 않는다 — 그때는 순현금 등의 크기와 가정 쪽 까닭만 쓴다
    기EV, 기주 = _n(맥.값("R:기준:요약:영업가치")), _n(맥.값("R:기준:요약:주주가치"))
    순부채 = (기EV is not None and 기주 is not None and 기EV - 기주 > 0)
    if 순부채:
        순 = 맥.식(["÷", ["−", "R:기준:요약:영업가치", "R:기준:요약:주주가치"], "R:기준:요약:영업가치"], "퍼1")
        순말 = "기준 시나리오의 순부채 등은 영업가치의 %s" % 입니다(순)
    else:
        순 = 맥.식(["÷", ["−", "R:기준:요약:주주가치", "R:기준:요약:영업가치"], "R:기준:요약:영업가치"], "퍼1")
        순말 = "기준 시나리오의 순현금 등은 영업가치의 %s" % 입니다(순)
    if 주 is None:
        if 순부채:
            return ["비관 시나리오의 주주가치는 0 이하입니다. 영업가치가 순부채 등보다 작다는 뜻입니다(%s)." % 순말.rstrip("."), ""]
        return ["비관 시나리오의 주주가치는 0 이하입니다. 비관 시나리오의 영업가치가 0 이하라는 뜻입니다(%s)." % 순말.rstrip("."), ""]
    return ["비관 시나리오와 낙관 시나리오의 주주가치는 %s 차이로 네 배를 넘습니다. 영업가치의 차이는 %s이고, %s. "
            "성숙 기업은 두세 배가 일반적이므로, %s." % (
                주, ev, 순말.rstrip("."),
                "시나리오마다 바꾼 가정이 많았거나 순부채가 차이를 키운 결과입니다" if 순부채 else "시나리오마다 바꾼 가정이 많았던 결과입니다"), ""]


def _쪽(v, b):
    if v is None or b is None or abs(v - b) <= 1e-12 * max(1.0, abs(b)):
        return 0
    return 1 if v > b else -1


def 꺾인열(가정, 번호, 열들, 첫, 영구=None):
    """레터 v27 P8 — 열별 가정 한 줄에서 첫 갈림 열(첫) 뒤에 (시나리오 − 기준) 부호가 꺾이는 열 → 열 ID 또는 None.
    꺾임 = 비관 · 낙관 가운데 하나가 첫 열과 반대 부호로 가거나, 첫 열에서 기준의 양쪽에 섰던 비관 · 낙관이 그 열에서 기준의 같은 쪽에 선다.
    영구기간 열이 꺾였으면 그 열을, 아니면 처음 꺾인 예측 열을 낸다(가정 표가 첫 열 하나만 보여 영구 열의 역전이 숨던 자리)."""
    import 레터 as _L                                       # noqa: PLC0415
    if 첫 not in 열들:
        return None

    def 부호(c):
        b = _n(_L._가정값(가정, 번호, "기준", c))
        return tuple(_쪽(_n(_L._가정값(가정, 번호, s, c)), b) for s in ("비관", "낙관"))
    p0 = 부호(첫)
    꺾 = []
    for c in 열들[열들.index(첫) + 1:]:
        p = 부호(c)
        반대 = any(a and b and a == -b for a, b in zip(p, p0))
        같은쪽 = p[0] and p[0] == p[1] and not (p0[0] and p0[0] == p0[1])
        if 반대 or 같은쪽:
            꺾.append(c)
    if not 꺾:
        return None
    return 영구 if 영구 in 꺾 else 꺾[0]


def 시나리오절(맥, 번, 폭포=True):
    import 레터 as _L                                       # noqa: PLC0415
    L = ["## %d. 시나리오" % 번, ""]
    L += ["**표. 세 시나리오의 산정 결과(반올림하지 않은 값)**", ""]
    L += _주당표(맥, 종가줄=False)                            # R1b — 세 시나리오의 원 단위 값(본편 요약은 반올림)
    L.append("")
    L += 시나리오폭글(맥)
    서 = 맥.가정.get("서술") or {}
    이름 = 서.get("이름") or {}
    세계 = 서.get("세계서술") or {}
    이야 = 맥.가정.get("시나리오이야기") or {}
    글 = []
    for s in 시나리오들:
        자리 = "시나리오이야기.%s.한줄" % s if (이야.get(s) or {}).get("한줄") else "서술.세계서술.%s" % s
        한 = 레터이야기.펴기(맥, (이야.get(s) or {}).get("한줄") or 세계.get(s) or "", 자리)
        나 = ("%s" % (이름.get(s) or "")).strip()
        삼 = 레터이야기.시나리오3P(맥, s)
        if 한 or 나 or 삼:
            글.append("- %s 시나리오%s%s%s" % (s, ("(%s)" % 맥.원고글(나)) if 나 else "", (" — " + 한.rstrip(".") + ".") if 한 else "",
                                         (" " + 삼) if 삼 else ""))
    if 글:
        L += 글 + [""]
    줄들 = []
    안닿 = _L.값안닿는번호(맥.가정, 맥.구)                     # 레터 v27 P3 — 갈려도 값에 닿지 않는 번호(대조값)는 시나리오 가정으로 세지 않는다
    for 번호 in sorted(set(맥.가정.get("가정") or {}) | set(맥.가정.get("시점가정") or {}), key=lambda x: (len(x), x)):
        if not ("%s" % 번호).isdigit() or not _L._변동(맥.가정, 번호) or ("%s" % 번호) in 안닿:
            continue
        꼴 = _L.가정꼴(번호, 맥.구)
        이 = _L.가정이름(번호, 맥.구) or 번호
        if 번호 in (맥.가정.get("가정") or {}):
            열 = None
            열들 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
            for c in 열들:                                     # 시나리오끼리 값이 다른 첫 열
                세 = [_n(_L._가정값(맥.가정, 번호, s, c)) for s in 시나리오들]
                if any(v is not None for v in 세) and len({round(v, 12) if v is not None else None for v in 세}) > 1:
                    열 = c
                    break
            if 열 is None:
                continue
            줄들.append([이, 맥.표기(열)] +
                      [맥.수("A:%s:%s:%s" % (번호, s, 열), 꼴) if _n(_L._가정값(맥.가정, 번호, s, 열)) is not None else "—" for s in 시나리오들])
            꺾 = 꺾인열(맥.가정, 번호, 열들, 열, 영구=맥.영구열)      # 레터 v27 P8 — 뒤 열에서 (시나리오 − 기준) 부호가 바뀌면(대개 영구 열) 그 열을 한 줄 더
            if 꺾:
                줄들.append(["", 맥.표기(꺾)] +
                          [맥.수("A:%s:%s:%s" % (번호, s, 꺾), 꼴) if _n(_L._가정값(맥.가정, 번호, s, 꺾)) is not None else "—" for s in 시나리오들])
        else:
            줄들.append([이, "모든 기간"] +
                      [맥.수("S:%s:%s" % (번호, s), 꼴) if _n(_L._시점값(맥.가정, 번호, s)) is not None else "—" for s in 시나리오들])
    if 줄들:                                                # 레터 v27 — 표 제목 · 표 주석(「아래 가정만 …다르다」 · 「열」 → 「기간」)
        L += ["**표. 시나리오마다 다르게 적용한 가정**", ""]
        L += _표(["가정", "기간", "비관", "기준", "낙관"], 줄들, ["l", "l", "r", "r", "r"])
        L += ["", "기간별 가정은 시나리오 사이에 값이 처음 달라지는 기간의 값을 적었습니다.", ""]     # 1.1.20 — 「모든 기간의 값은 부록 A에 있습니다」(원칙 3)는 지웠다
    if 폭포:
        L += 폭포절(맥)                                      # R1b(L11) — R1c 다섯 막에서는 3막이 싣는다(같은 그림을 두 번 싣지 않는다)
    else:
        L += 폭포표(맥)                                      # 통독 v3 중-11 — 3막은 큰 묶음 셋만 그림으로, 묶음 전체 표와 보조 시나리오 표는 이 절에
    return L


def _묶음다른가(맥, 번들, 시):
    """가정 묶음이 시나리오 시 에서 기준과 다른가(열별 벌 · 한 값)."""
    import 레터 as _L                                       # noqa: PLC0415
    for 번 in 번들:
        벌 = (맥.가정.get("가정") or {}).get(번)
        if isinstance(벌, dict) and 시 in 벌 and json.dumps(벌.get(시), sort_keys=True) != json.dumps(벌.get("기준"), sort_keys=True):
            return True
        if 번 in (맥.가정.get("시점가정") or {}) and _L._시점값(맥.가정, 번, 시) != _L._시점값(맥.가정, 번, "기준"):
            return True
    return False


def 묶음값글(맥, 번들):
    """폭포 묶음의 한 값 가정(시점가정)들의 세 시나리오 값 → (글, 기간). 번호가 여럿이면(구분마다 같은 뜻의 가정) 번호마다 —
    「범용 DRAM 기준 0.91 · 비관 0.70 · 낙관 1.33, NAND 기준 0.90 · 비관 0.70 · 낙관 1.20」.
    독자 층은 정상 수준(6s6)을 기준 기간 = 100 눈금으로 적고 기간(「2026년 2분기」)을 함께 낸다 — 바꿀 수 없는 지수 · 배수가 섞이면 ("", None)
    (값은 깊이 층의 표에 있다). 한 값 가정이 없으면 ("", None)."""
    import 레터 as _L                                       # noqa: PLC0415
    import 레터3분                                           # noqa: PLC0415
    시점 = [번 for 번 in 번들 if 번 in (맥.가정.get("시점가정") or {})]
    if not 시점:
        return "", None
    독자 = 독자층(맥)
    구들 = {번: 정상수준구분(맥, 번) for 번 in 시점}
    if 독자 and any(구들[번] is None and 지수꼴인가(_L.가정꼴(번, 맥.구)) for 번 in 시점):
        return "", None
    b = 레터3분.바닥(맥)
    if b and all(구들[번] is not None for 번 in 시점):
        순 = [s for s, _x in b["구분"]]
        시점.sort(key=lambda 번: 순.index(구들[번]) if 구들[번] in 순 else len(순))
    기간 = None
    글 = []
    for 번 in 시점:
        s = 구들[번]
        if 독자 and s is not None:
            값 = [백글(맥, "S:%s:%s" % (번, 시), s) for 시 in ("기준", "비관", "낙관")]
            x0 = next((x for x in 맥.구.get("매출구분") or [] if x.get("번호") == s), {})
            기간 = 기간 or 눈금이름(맥, x0)
        else:
            꼴 = _L.가정꼴(번, 맥.구)
            값 = [맥.수("S:%s:%s" % (번, 시), 꼴) for 시 in ("기준", "비관", "낙관")]
        몸 = "기준 %s · 비관 %s · 낙관 %s" % tuple(값) if len(시점) > 1 else "기준 %s, 비관 %s, 낙관 %s" % tuple(값)
        if len(시점) > 1:
            n = int(번)
            머 = _L.구분이름(맥.구, n // 10 - 60) if 610 <= n <= 659 else (_L.가정이름(번, 맥.구) or 번)
            몸 = "%s %s" % (머, 몸)
        글.append(몸)
    return ", ".join(글), (기간 if 독자 else None)


def _묶음이름(맥, 이름):
    """폭포 묶음을 독자 층에서 부르는 이름 — 저자 선언 `Narrative.독자.묶음이름` {묶음 이름: 독자 이름}(레터에만 — 워크북 라벨은 그대로).
    선언이 없으면 가정 이름(기호 괄호를 걷은 것)."""
    독 = (맥.가정.get("Narrative") or {}).get("독자") if isinstance(맥.가정.get("Narrative"), dict) else None
    표 = 독.get("묶음이름") if isinstance(독, dict) and isinstance(독.get("묶음이름"), dict) else {}
    새 = 표.get(이름)
    return 새.strip() if isinstance(새, str) and 새.strip() else 레터이야기.이름다듬기(이름)


def _폭포줄들(맥):
    """→ (묶음, 줄들, 걸음, 식들, 앞) — 묶음마다 [이름, 비관으로, 낙관으로] 글 · 값 · 식(장부 식). 묶음이 없으면 None."""
    import 레터 as _L                                       # noqa: PLC0415
    묶음 = _L.폭포묶음(맥.가정, 맥.구)
    if not 묶음:
        return None
    기 = "R:기준:2.DCF:68"
    줄들, 걸음, 식들 = [], {"비관": [], "낙관": []}, {"비관": [], "낙관": []}
    앞 = {"비관": 기, "낙관": 기}
    for k, (이름, 번들) in enumerate(묶음):
        줄 = [_묶음이름(맥, 이름)]
        for 시 in ("비관", "낙관"):
            키 = "가:폭포:%s:%d" % (시, k)
            if _묶음다른가(맥, 번들, 시):
                줄.append(맥.식(["−", 키, 앞[시]], "부호주당"))
                걸음[시].append(_n(맥.값(키)) - _n(맥.값(앞[시])))
                식들[시].append(["−", 키, 앞[시]])
            else:
                줄.append("—")
                걸음[시].append(0.0)
                식들[시].append(None)
            앞[시] = 키
        줄들.append(줄)
    return 묶음, 줄들, 걸음, 식들, 앞


def _폭포끝줄(맥, 앞, 독=False):
    """폭포 표의 끝 줄 — 그 밖의 차이 · 합계. 독(독자 층) = 만 원 단위로, 합계 대신 시나리오의 주당가치(그림의 끝 막대)."""
    기 = "R:기준:2.DCF:68"
    꼴 = "부호어림주당" if 독 else "부호주당"
    L = []
    남 = [(시, _n(맥.값("R:%s:2.DCF:68" % 시)) - _n(맥.값(앞[시]))) for 시 in ("비관", "낙관")]
    if any(abs(r) >= 0.5 for _s, r in 남):
        L.append(["그 밖의 차이"] + [맥.식(["−", "R:%s:2.DCF:68" % 시, 앞[시]], 꼴) if abs(r) >= 0.5 else "—" for 시, r in 남])
    if 독:
        L.append(["**시나리오 주당가치**"] + ["**%s**" % 맥.수("R:%s:2.DCF:68" % 시, "어림주당") for 시 in ("비관", "낙관")])
        return L
    L.append(["**합계 (시나리오 주당가치 − 기준)**"] + ["**%s**" % 맥.식(["−", "R:%s:2.DCF:68" % 시, 기], 꼴) for 시 in ("비관", "낙관")])
    return L


폭포주석 = ("기준 시나리오에서 가정을 구분별로 하나씩 비관 · 낙관 시나리오의 값으로 바꿨을 때의 주당가치 변동액입니다. "
        "매출 · 비용 · 재투자 · 세금 · 영구기간 · 주주가치의 순서로, 앞 구분을 바꾼 상태에서 다음 구분을 바꿨습니다.")


def 폭포표(맥):
    """깊이 층(시나리오 절) — 가정 묶음 전체의 주당가치 변동 표(그림 없이)와 보조 시나리오 표(통독 v3 중-11 — 3막은 큰 묶음만)."""
    import 레터3분                                           # noqa: PLC0415
    r = _폭포줄들(맥)
    L = []
    if r:
        _묶, 줄들, _걸, _식, 앞 = r
        L += ["### 가정 구분별 주당가치 변동 (전체)", ""]          # 레터 v27 — 「가정 묶음」 → 「가정 구분」 · 설명은 표 주석으로
        L += _표(["가정 구분", "비관으로", "낙관으로"], 줄들 + _폭포끝줄(맥, 앞), ["l", "r", "r"])
        L += ["", 폭포주석, ""]
    보 = 레터3분.보조시나리오들(맥)
    if 보:
        기 = "R:기준:2.DCF:68"
        L += ["보조 시나리오는 기준 시나리오에 경로 하나를 덧씌워 계산한 값입니다.", ""]
        L += _표(["보조 시나리오", "주당가치", "기준 대비"], [[이, 맥.수(키, "주당"), 맥.식(["괴리", 키, 기], "증1")] for 이, 키 in 보])
        L.append("")
    return L


def 폭포절(맥, 위만=None):
    """시나리오 사이의 다리(R1b · L11) — 기준 시나리오에서 비관 · 낙관 시나리오로 가정 묶음을 차례로 바꿔 가며 주당가치가 움직인 몫(폭포).
    비대칭의 까닭(위 · 아래 폭이 가장 다른 묶음) · 「기준은 가운데 시나리오이며 기댓값이 아니다」 · 보조 시나리오(R1a — 있을 때).
    위만(통독 v3 중-11 · 독자 층) — 움직임이 큰 묶음 n개만 막대로, 나머지는 「그 밖의 묶음」 한 줄로(전체 표와 보조 표는 깊이 층 시나리오 절)."""
    import 레터 as _L                                       # noqa: PLC0415
    import 레터3분                                           # noqa: PLC0415
    r = _폭포줄들(맥)
    if not r:
        return []
    묶음, 줄들, 걸음, 식들, 앞 = r
    기 = "R:기준:2.DCF:68"
    독 = bool(위만) and 독자층(맥)                              # 통독 v4 중-6 — 독자 층 폭포는 만 원 단위 · 양 끝에 기준과 시나리오의 주당가치(합계 막대)
    꼴 = "부호어림주당" if 독 else "부호주당"
    if 독:
        줄들 = [[줄들[q][0]] + [맥.식(식들[시][q], 꼴) if 식들[시][q] is not None else "—" for 시 in ("비관", "낙관")] for q in range(len(줄들))]
    전체 = 줄들 + _폭포끝줄(맥, 앞, 독)
    줄임 = bool(위만 and len(줄들) > 위만 + 1)
    if 줄임:
        큰 = sorted(range(len(줄들)), key=lambda q: -max(abs(걸음["비관"][q]), abs(걸음["낙관"][q])))[:위만]
        큰 = sorted(큰)
        나머지 = [q for q in range(len(줄들)) if q not in 큰]
        덧 = ["그 밖의 구분 %d개" % len(나머지)]
        for 시 in ("비관", "낙관"):
            식 = [식들[시][q] for q in 나머지 if 식들[시][q] is not None]
            덧.append(맥.식(["합"] + 식, 꼴) if 식 else "—")
        전체 = [줄들[q] for q in 큰] + [덧] + _폭포끝줄(맥, 앞, 독)
    수꼴 = "어림주당" if 독 else "주당"
    전체 = [["기준 시나리오의 주당가치", 맥.수(기, 수꼴), 맥.수(기, 수꼴)]] + 전체     # 1.1.10 — 깊이 층도 양 끝 합계 막대(출발 · 도착)
    if not 독:                                               # 합계(차이) 줄 뒤에 도착 줄 — 그림은 「합계」 줄을 건너뛰고 도착 막대를 0 부터 그린다
        전체.append(["**시나리오 주당가치**"] + ["**%s**" % 맥.수("R:%s:2.DCF:68" % 시, "주당") for 시 in ("비관", "낙관")])
    L = ["### 가정 구분별 주당가치 변동", ""]                  # 이름은 대상 + 보여 주는 것(「…으로 가는 길」 대신) · 레터 v27 「가정 묶음」 → 「가정 구분」
    L += ["<!-- 그림:폭포 -->", "**그림. 가정 구분별 주당가치 변동(기준 → 비관 · 낙관)** — 가정 구분마다 주당가치가 달라진 금액입니다. "
          "양 끝 막대는 기준 시나리오와 그 시나리오의 주당가치입니다.", ""]
    L += _표(["가정 구분", "비관으로", "낙관으로"], 전체, ["l", "r", "r"])
    L += ["", 폭포주석 + ((" 주당가치 변동이 큰 구분 %d개만 따로 표시하고 나머지는 한 줄로 합쳤습니다." % 위만) if 줄임 else ""), ""]   # 표 주석(레터 v27) · 구분 전체 표는 깊이 층 시나리오 절
    for d in (맥.가정.get("지분경로") or []):                  # 지분 방식 「경로 DCF」 — 지분이 매출 구분의 경로를 따라 움직여 따로 묶지 않는다
        지 = next((x for x in (((맥.가정.get("구조") or {}).get("가치조정") or {}).get("지분") or []) if x.get("번호") == d.get("지분")), None)
        if 지 and 지.get("이름"):
            구이 = _L.구분이름(맥.구, d["구분"])
            L += ["%s 지분의 가치는 %s 매출과 같은 경로로 함께 계산해 따로 구분하지 않았습니다. 그 금액은 %s 관련 가정 구분에 포함돼 있습니다." % (지["이름"], 구이, 구이), ""]
    위, 아래 = _n(맥.값("R:낙관:2.DCF:68")) - _n(맥.값(기)), _n(맥.값(기)) - _n(맥.값("R:비관:2.DCF:68"))
    if 위 > 0 and 아래 > 0 and abs(위 - 아래) > 0.1 * max(위, 아래):
        # 레터 v27 P7 — 위아래 폭의 차를 만든 묶음은 걸음의 부호 합(낙관 걸음 + 비관 걸음)이 그 쪽으로 가장 큰 묶음이다(절댓값 차는 역방향 걸음을 같은 쪽으로 센다).
        #   그 묶음의 걸음이 시나리오 쪽과 거꾸로 갔으면(비관에서 올림 · 낙관에서 내림 — 차를 만든 까닭) 그렇다고 적는다
        부 = 1 if 위 > 아래 else -1
        문 = 레터이야기.귀속문턱() * abs(_n(맥.값(기)) or 0.0)
        거꾸 = [q for q in range(len(묶음)) if (걸음["비관"][q] > 문 if 부 > 0 else 걸음["낙관"][q] < -문)]
        k = max(range(len(묶음)), key=lambda q: (걸음["낙관"][q] + 걸음["비관"][q]) * 부)
        이름, 번들 = 묶음[k]
        값들, 기간 = 묶음값글(맥, 번들)
        쪽말 = "낙관" if 위 > 아래 else "비관"
        if 값들 and 기간:                                    # 독자 층 — 기준 기간 = 100 눈금, 따로 한 문장
            L.append("주당가치의 변동 폭은 %s 시나리오 쪽이 더 큽니다. 두 방향의 변동 폭 차이를 가장 크게 만든 가정 구분은 %s. %s 100으로 두면 %s." % (
                쪽말, 입니다(_묶음이름(맥, 이름)), 을(기간), 입니다(값들)))
        else:
            L.append("주당가치의 변동 폭은 %s 시나리오 쪽이 더 큽니다. 두 방향의 변동 폭 차이를 가장 크게 만든 가정 구분은 %s." % (
                쪽말, 입니다("%s(%s)" % (_묶음이름(맥, 이름), 값들)) if 값들 else 입니다(_묶음이름(맥, 이름))))
        if k in 거꾸:
            시 = "비관" if 부 > 0 else "낙관"
            L[-1] += " 이 가정 구분은 %s 시나리오에서 주당가치를 오히려 %s(%s)." % (시, "높였습니다" if 부 > 0 else "낮췄습니다", 맥.식(식들[시][k], 꼴))
        L.append("")
    L.append("기준 시나리오는 세 시나리오 가운데 실현 가능성이 가장 높은 경로이며, 세 시나리오의 평균이 아닙니다." if 독자층(맥)
             else "기준 시나리오는 세 시나리오의 가운데 시나리오이며, 확률로 가중한 기댓값이 아닙니다.")
    맥._기준뜻 = True                                        # 1.1.20 — 뒤의 「세 시나리오의 산정 결과」 표가 같은 정의를 되풀이하지 않게
    L.append("")
    보 = 레터3분.보조시나리오들(맥)
    if 보:                                                  # R1a(K4) — 보조 시나리오(골 · 회복)를 나란히
        if 독자층(맥) and len(보) == 1:
            L += ["%s %s 값입니다." % (은("보조 시나리오(%s)" % 보[0][0]), 레터3분.보조말(맥, 보[0][0])), ""]
        else:
            L += ["보조 시나리오는 기준 시나리오에 경로 하나를 덧씌워 계산한 값입니다.", ""]
        if not 위만:                                         # 통독 v3 중-11 — 독자 층(3막)은 문장만, 표는 깊이 층 시나리오 절
            L += _표(["보조 시나리오", "주당가치", "기준 대비"], [[이, 맥.수(키, "주당"), 맥.식(["괴리", 키, 기], "증1")] for 이, 키 in 보])
            L.append("")
    맥.서술("시나리오.폭포")
    return L


# ── 민감도

def 민감도절(맥, 번):
    L = ["## %d. 민감도" % 번, ""]
    머 = 레터이야기.Value드라이버문장(맥)
    if 머:
        L += [" ".join(머), ""]
    L.append("**표. 기준 시나리오에서 가정 하나를 일정한 크기만큼 바꿨을 때의 주당가치**")      # 레터 v27 — 표 제목 · 설명은 표 주석으로
    L.append("")
    줄들, 막힘 = [], False
    for i, r in enumerate(맥.민["표3"]):
        h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
        꼴 = 손잡이꼴(h, 맥)
        if _n(r.get("기준")) is None or (_n(r.get("하")) is None and _n(r.get("상")) is None):
            continue
        막힘 = 막힘 or _n(r.get("하")) is None or _n(r.get("상")) is None
        줄들.append([손잡이이름(h, 맥), 맥.수("민:표3:%d:기준값" % i, 꼴), 폭글(h, "민:표3:%d:폭" % i, 맥),
                   _표3칸(맥, i, "하"), _표3칸(맥, i, "상")])
    줄들 += _요약줄들(맥)
    L += _표(["가정", "적용값", "변동 폭", "낮출 때", "높일 때"], 줄들, ["l", "r", "r", "r", "r"])
    L.append("")
    # 1.1.20 — 「다른 가정은 바꾸지 않았습니다」 는 표 제목(「가정 하나를 … 바꿨을 때」)이 이미 말해 지웠다. 바꾸는 법 두 문장은 표 설명 한 문장으로
    # 1.1.21 — 두 틀을 쉼표로 이어 서술어가 하나뿐이던 비문(「WACC 값은 … 같은 크기를, 영구기간 영업이익률은 …」)을 두 문장으로
    L.append("WACC 값은 예측기간과 영구기간에 같은 크기를 더하거나 빼서 바꿨습니다. "
             "영구기간 영업이익률은 그 크기에 영구기간 매출액을 곱한 금액을 영구기간 영업이익에 더하거나 빼서 바꿨습니다.")
    L.append("")
    if 막힘:
        L.append(막힘각주)
        L.append("")
    import 레터갭 as _갭                                     # noqa: PLC0415
    L += _갭.g짝판줄(맥)                                      # 1.1.3(B3) — 영구 ROIC > 영구 WACC 면 「g = 무위험 근처」 판(표준 줄)
    import 레터안정 as _안                                    # noqa: PLC0415
    L += _안.주식보상줄(맥)                                   # 1.1.5 — 주식보상 비율이 매출 규모에 따라 줄어드는 판
    t = 맥.민["표1"]
    줄들 = []
    for i in range(len(t["세로값"])):
        줄들.append([맥.수("민:표1:세로값:%d" % i, "퍼2")] +
                  [맥.수("민:표1:값:%d:%d" % (i, j), "주당") if t["값"][i][j] is not None else "—" for j in range(len(t["가로값"]))])
    L.append("**표. WACC(가로)와 영구성장률(세로)을 함께 바꿨을 때의 주당가치**")
    L.append("")
    L += _표(["영구성장률 \\ WACC"] + [맥.수("민:표1:가로값:%d" % j, "퍼2") for j in range(len(t["가로값"]))], 줄들)
    L.append("")
    if any(_n(c) is None for 줄 in t["값"] for c in 줄):
        L.append(막힘각주)
        L.append("")
    t5 = 맥.민.get("표5")
    if t5:
        맥.서술("민감도.표2")
        h세 = {"이름": t5["세로이름"], "대상": ((맥.가정.get("민감도") or {}).get("표2") or {}).get("세로", {}).get("대상") or []}
        h가 = {"이름": t5["가로이름"], "대상": ((맥.가정.get("민감도") or {}).get("표2") or {}).get("가로", {}).get("대상") or []}
        세꼴, 가꼴 = 손잡이꼴(h세, 맥), 손잡이꼴(h가, 맥)
        L.append("**표. %s %s 함께 바꿨을 때의 주당가치**" % (과("%s(세로)" % 손잡이이름(h세, 맥)), 을("%s(가로)" % 손잡이이름(h가, 맥))))
        L.append("")
        줄들 = []
        for i in range(len(t5["세로값"])):
            줄들.append([맥.수("민:표5:세로값:%d" % i, 세꼴)] +
                      [맥.수("민:표5:값:%d:%d" % (i, j), "주당") if t5["값"][i][j] is not None else "—" for j in range(len(t5["가로값"]))])
        L += _표(["%s \\ %s" % (손잡이이름(h세, 맥), 손잡이이름(h가, 맥))] + [맥.수("민:표5:가로값:%d" % j, 가꼴) for j in range(len(t5["가로값"]))], 줄들)
        L.append("")
        표2세 = ((맥.가정.get("민감도") or {}).get("표2") or {}).get("세로") or {}
        L += _묶음축주(맥, 표2세.get("대상") or [], "값" not in 표2세)
        if any(_n(c) is None for 줄 in t5["값"] for c in 줄):
            L.append(막힘각주)
            L.append("")
    격자 = [("격자", k, g) for k, g in enumerate((맥.민 or {}).get("격자") or [])]       # R1a(K6) — 선언 격자 셋 · RONIC × g(표6)
    if isinstance((맥.민 or {}).get("표6"), dict):
        격자.append(("표6", None, 맥.민["표6"]))
    for 이름, k, g in 격자:
        if not (isinstance(g, dict) and g.get("값") and g.get("세로값") and g.get("가로값")):
            continue
        머키 = "민:%s:%d" % (이름, k) if k is not None else "민:%s" % 이름
        h세 = {"이름": g.get("세로이름"), "대상": g.get("세로대상") or []}
        h가 = {"이름": g.get("가로이름"), "대상": g.get("가로대상") or []}
        세꼴 = _격자꼴(g.get("세로이름"), 손잡이꼴(h세, 맥))
        가꼴 = _격자꼴(g.get("가로이름"), 손잡이꼴(h가, 맥))
        세이, 가이 = _격자이름(맥, g.get("세로이름")), _격자이름(맥, g.get("가로이름"))
        L.append("**표. %s %s 함께 바꿨을 때의 주당가치**" % (과("%s(세로)" % 세이), 을("%s(가로)" % 가이)))
        L.append("")
        줄들 = [[맥.수("%s:세로값:%d" % (머키, i), 세꼴)] +
               [맥.수("%s:값:%d:%d" % (머키, i, j), "주당") if _n(g["값"][i][j]) is not None else "—" for j in range(len(g["가로값"]))]
               for i in range(len(g["세로값"]))]
        L += _표(["%s \\ %s" % (세이, 가이)] + [맥.수("%s:가로값:%d" % (머키, j), 가꼴) for j in range(len(g["가로값"]))], 줄들)
        L.append("")
        if 이름 == "격자" and k is not None:
            선 = (((맥.가정.get("민감도") or {}).get("격자") or [])[k:k + 1] or [{}])[0].get("세로") or {}
            try:
                import importlib                                 # noqa: PLC0415
                h선, _x = importlib.import_module("엔진.민감도")._축풀기(선, 맥.가정)
                L += _묶음축주(맥, h선.get("대상") or [], h선.get("방식") != "값")
            except Exception:                                # noqa: BLE001
                pass
        if any(_n(c) is None for 줄 in g["값"] for c in 줄):
            L.append(막힘각주)
            L.append("")
    맥.서술("민감도")                                        # 1.1.20 — 「… 전체 값은 부록 F에 있습니다」(원칙 3)는 지웠다
    return L


def _묶음축주(맥, 대상, 가감):
    """격자 · 표 Ⅴ 의 세로 축이 구분 여럿의 정상 수준(6s6)을 함께 움직이면 — 줄 이름이 어느 구분의 값인지와 기준(통독 v3 하 「16절 격자」)."""
    import 레터 as _L                                       # noqa: PLC0415
    대 = ["%s" % x for x in 대상]
    if len(대) < 2 or not all(len(d) == 3 and d[0] == "6" and d[2] == "6" for d in 대):
        return []
    구들 = [int(d[1]) for d in 대]
    기 = " · ".join("%s %s" % (_L.구분이름(맥.구, s), 맥.수("S:6%d6:기준" % s, "지수2")) for s in 구들)
    if 가감:
        return ["세로 축은 %s의 정상 수준을 같은 크기로 함께 바꾼 값입니다. 세로 축의 값은 %s 기준이고, 가운데 값이 기준 시나리오(%s)입니다." % (
            _나열([_L.구분이름(맥.구, s) for s in 구들]), _L.구분이름(맥.구, 구들[0]), 기), ""]
    return ["세로 축의 값은 %s에 같은 값으로 적용한 정상 수준입니다. 기준 시나리오의 값(%s)은 이 표에 없습니다." % (_나열([_L.구분이름(맥.구, s) for s in 구들]), 기), ""]


def _요약줄들(맥):
    """R1a(K8) 요약 민감도 가운데 표 Ⅲ 에 없는 손잡이(고점 구간 길이 · 감산 · RONIC …)를 표 Ⅲ 의 꼴로 — 통독 v3 상3(워크북 요약이 레터에 없음)."""
    표3대상 = {tuple(sorted("%s" % x for x in r.get("대상") or [])) for r in (맥.민 or {}).get("표3") or []}
    낸 = []
    for i, r in enumerate((맥.민 or {}).get("요약") or []):
        h = dict(r.get("손잡이") or {})
        대 = ["%s" % x for x in h.get("대상") or []]
        if not 대 or tuple(sorted(대)) in 표3대상 or _n(r.get("기준")) is None:
            continue
        기 = _n(r["기준"])

        def 칸(쪽, i=i, r=r, 기=기):
            v = _n(r.get(쪽))
            if v is None or abs(v - 기) < 0.5:
                return "—"
            return "%s (%s)" % (맥.수("민:요약:%d:%s" % (i, 쪽), "주당"), 맥.식(["괴리", "민:요약:%d:%s" % (i, 쪽), "R:기준:2.DCF:68"], "증1"))
        if 대 == ["영구ROIC"]:
            꼴, 폭 = "퍼1", "±" + 맥.수("민:요약:%d:폭" % i, "폭p1")
        else:
            꼴 = 손잡이꼴(h, 맥)
            범 = r.get("범위")
            if isinstance(범, list) and len(범) == 2:
                폭 = " ~ ".join(맥.수("민:요약:%d:범위:%d" % (i, k), "폭p1" if 꼴.startswith("퍼") else "지수2") + (" 낮춤" if _n(범[k]) < 0 else " 높임")
                               for k in (0, 1) if _n(범[k]))
            else:
                폭 = 폭글(h, "민:요약:%d:폭" % i, 맥)
        if 대 != ["영구ROIC"] and not 꼴.startswith(("퍼", "연도")):
            꼴 = "퍼1" if all(d.isdigit() and int(d) in (273, 298, 323, 348) for d in 대) else 꼴
        이름 = ("%s" % r.get("이름") or "").replace(" (", "(")
        if 이름.startswith(("고점 구간 길이", "고원 길이")):  # 고원 — 옛 이름(지난 결과 파일)                      # 고점 구간 손잡이는 유지 종료 · 정상 수준 도달 연도를 함께 옮긴다(하강 기간 그대로)
            이름 = "고점 구간 길이(유지 종료 · 도달 연도를 함께)"
        낸.append([이름, 맥.수("민:요약:%d:기준값" % i, 꼴), 폭, 칸("하"), 칸("상")])
    return 낸


def 날짜말(iso):
    """「2026-06-30」 → 「2026년 6월 30일」."""
    m = re.match(r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})", "%s" % (iso or ""))
    return "%d년 %d월 %d일" % (int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else ("%s" % (iso or "")).strip()


# ── 날짜 둘(2026-10-25 결정) — 평가기준일 T(분석일 · 정보 경계 · 시장 자료 · 레터의 날짜) · 재무 자료 기준일 F(실적 열 · 재무상태표)
# 낱말 — 레터 본문에는 「재무기준일」(용어 확인 전)을 쓰지 않고 「재무 자료 기준일」 로 풀어 쓴다. 이월 판(F ≠ T)이 아니면 아래는 모두 옛 글을 낸다.

이월종류 = {"증자": (1, 1), "전환": (1, 1), "행사": (1, 1), "자기주식처분": (1, 1), "자기주식취득": (-1, -1), "배당": (-1, 0)}   # (현금 부호, 주식 수 부호)


def 이월판(맥):
    """재무 자료 기준일 ≠ 평가기준일인 판 — 엔진 요약에 이월연수 > 0(계약 `02_줄번호.md` 0절 · 키가 없으면 옛 판)."""
    try:
        v = _n(((getattr(맥, "기", None) or {}).get("요약") or {}).get("이월연수"))
    except Exception:                                        # noqa: BLE001
        v = None
    return bool(v and v > 0)


def 재무날(맥):
    """재무 자료 기준일 「YYYY-MM-DD」 — 엔진 요약 → 엔진 기간(축.사전) → 메타.재무기준일 → 메타.평가기준일."""
    기 = getattr(맥, "기", None) or {}
    for v in (((기.get("요약") or {}).get("재무기준일")), ((기.get("기간") or {}).get("재무기준일")),
              ((getattr(맥, "메타", None) or {}).get("재무기준일")), ((getattr(맥, "메타", None) or {}).get("평가기준일"))):
        if re.match(r"^\s*\d{4}-\d{1,2}-\d{1,2}", "%s" % (v or "")):
            return ("%s" % v).strip()[:10]
    return ""


def 재무날말(맥):
    """재무 자료의 날을 가리키는 말 — 이월 판이면 「재무 자료 기준일」, 아니면 「평가기준일」(옛 글 그대로)."""
    return "재무 자료 기준일" if 이월판(맥) else "평가기준일"


def 주식키(맥, s="기준"):
    """평가기준일 주식 수의 키 — 희석 주식이 있거나 이월 판이면 2번 152(평가기준일 적용 주식수), 아니면 67(유통주식수 — 옛 키 그대로).
    이월 판의 67 은 재무 자료 기준일 유통주식수라 평가기준일 종가와 곱하지 않는다."""
    D = (맥.R.get(s) or {}).get("2.DCF") or {}
    return "R:%s:2.DCF:%s" % (s, "152" if (_n(D.get("151")) or 이월판(맥)) else "67")


def _사이목록(맥):
    """가정 `관측.사이자본거래[]` → [(번호, 항목, 쪽)] — 쪽 = 「사이」((F, T]) · 「뒤」(T 뒤) · 「앞」(F 이전) · 「모름」(날짜 없음)."""
    목 = ((맥.가정.get("관측") or {}).get("사이자본거래")) if isinstance(맥.가정.get("관측"), dict) else None
    F, T = 재무날(맥), ("%s" % ((맥.메타 or {}).get("평가기준일") or "")).strip()[:10]
    낸 = []
    for i, x in enumerate(목 if isinstance(목, list) else []):
        if not isinstance(x, dict):
            continue
        d = ("%s" % (x.get("날짜") or "")).strip()[:10]
        쪽 = "모름" if not re.match(r"^\d{4}-\d{2}-\d{2}$", d) else ("뒤" if d > T else ("사이" if d > F else "앞"))
        낸.append((i, x, 쪽))
    return 낸


def 세액공제조정글(맥):
    """추정 블록(법인세와 FCFF)의 고지 — 최종 예측 연도 말까지 쓰지 못한 세액공제를 영구기간에 쓴다고 보아 영업가치에 더한 조정(2번 132)이
    어느 시나리오에서든 서면 그 가정과 시나리오별 조정액 두 문장(기준 시나리오 표에는 0 으로만 보이는 값이라 고지로 둔다). 없으면 []."""
    if (맥.구.get("법인세") or {}).get("세액공제이월") != "예":
        return []
    if not all("132" in 맥.R[s]["2.DCF"] and not isinstance(맥.R[s]["2.DCF"]["132"], dict) for s in 시나리오들):
        return []
    if not any(abs(_n(맥.R[s]["2.DCF"]["132"]) or 0.0) > 0.5 for s in 시나리오들):
        return []
    return ["최종 예측 연도 말까지 쓰지 못한 세액공제는 이월 기한 안에서 한도만큼 영구기간에 쓴다고 가정했습니다. "
            "그 절세액의 현재가치를 이월 세액공제 조정으로 영업가치에 더했습니다. 조정액은 %s." % 입니다(" · ".join(
                "%s %s" % (s, 맥.수("R:%s:2.DCF:132" % s, "금액")) for s in 시나리오들)), ""]


def 이월글(맥, s="기준"):
    """이월 한 줄 — 재무 자료 기준일 주주가치 → 자기자본비용으로 이월 → 사이 자본거래 → 평가기준일 주주가치 · 주식 수 · 주당가치(장부 키).
    옛 판이면 [](레터가 날짜 둘 전과 글자까지 같다)."""
    if not 이월판(맥):
        return []
    K = "R:" + s + ":2.DCF:%s"
    요 = (맥.R.get(s) or {}).get("요약") or {}
    F말, T말 = 맥.엔진글("메:재무기준일:날짜"), 맥.엔진글("메:평가기준일:날짜")
    문 = []
    if 요.get("이월적용", True) is not False:              # 1.1.19 — 이월 기간(162)은 부록 C 이월 계수 줄과 같은 자릿수(수4)로(종전 꼴 「년」 0.32년 대 0.3233)
        문.append("재무 자료 기준일(%s)의 주주가치 %s 자기자본비용 %s %s 이월해(계수 %s) 평가기준일(%s)의 값으로 옮겼습니다." % (
            F말, 을(맥.수(K % "161", "금액")), 으로(맥.수(K % "163", "퍼2")), 맥.수(K % "162", "수4") + "년", 맥.수(K % "164", "지수4"), T말))
    else:
        문.append("재무 자료 기준일(%s)의 주주가치 %s 음수라 이월 계수를 적용하지 않았습니다(평가기준일 %s)." % (F말, 이(맥.수(K % "161", "금액")), T말))
    if _n((맥.R.get(s) or {}).get("2.DCF", {}).get("165")) or _n((맥.R.get(s) or {}).get("2.DCF", {}).get("167")):
        문.append("두 날 사이의 자본거래 %s 더해 평가기준일 주주가치는 %s." % (을(맥.수(K % "165", "금액")), 입니다(맥.수(K % "66", "금액"))))
        문.append("평가기준일 주식 수는 재무 자료 기준일 %s에 %s 더한 %s." % (
            맥.수(K % "166", "주"), 을(맥.수(K % "167", "주")), 입니다(맥.수(K % "152", "주"))))
    else:
        문.append("두 날 사이에 반영할 자본거래가 없어 평가기준일 주주가치는 %s." % 입니다(맥.수(K % "66", "금액")))
    문.append("그래서 평가기준일 주당가치는 %s. 자본거래 금액은 거래일에서 평가기준일까지 이월하지 않고 근사했습니다." % 입니다(맥.수(K % "68", "주당")))
    return [" ".join(문), ""]


def 사이표(맥):
    """재무 자료 기준일 뒤 · 평가기준일까지의 자본거래 표(가정 `관측.사이자본거래[]` 가운데 (F, T] — 장부 키 「G:」). 옛 판 · 목록 없음이면 []."""
    if not 이월판(맥):
        return []
    줄들 = []
    for i, x, 쪽 in _사이목록(맥):
        if 쪽 != "사이":
            continue
        종 = ("%s" % (x.get("종류") or "")).strip()
        부호 = 이월종류.get(종)
        현키, 주키 = "G:관측:사이자본거래:%d:현금" % i, "G:관측:사이자본거래:%d:주식수" % i
        if 부호 and _n(x.get("현금")) is not None:
            현 = 맥.수(현키, "금액") if 부호[0] > 0 else 맥.식(["음", 현키], "금액")
        else:
            현 = "기록만" if not 부호 else "—"
        if 부호 and 부호[1] and _n(x.get("주식수")) is not None:
            주 = 맥.수(주키, "주") if 부호[1] > 0 else 맥.식(["음", 주키], "주")
        else:
            주 = "—"
        설 = 사이설명(맥, x, i)
        줄들.append([("%s" % x.get("날짜"))[:10], 종 or "—", 설 or "—", 현, 주, 맥.바깥글(("%s" % (x.get("출처") or "")).strip()) or "—"])
    K = "R:기준:2.DCF:%s"
    못 = _사이확인불가(맥)
    L = ["**표. 재무 자료 기준일과 평가기준일 사이의 자본거래**", ""]      # 레터 v27 — 표 제목 · 반영 규칙은 표 주석으로
    if not 줄들 and not 못:
        return ["재무 자료 기준일과 평가기준일 사이에 반영한 자본거래는 없습니다. 반영한 자본거래 현금은 %s, 주식 수 변동은 %s." % (
            맥.수(K % "165", "금액"), 입니다(맥.수(K % "167", "주"))), ""]
    줄들 += 못
    줄들.append(["**합계**", "", "", "**%s**" % 맥.수(K % "165", "금액"), "**%s**" % 맥.수(K % "167", "주"), "평가 모델 원천 시트의 사이 자본거래 칸"])
    L += _표(["날짜", "종류", "내용", "다리에 넣은 현금", "주식 수", "출처"], 줄들, ["l", "l", "l", "r", "r", "l"])
    L.append("")
    L += ["증자 · 자기주식 처분은 현금과 주식 수를 더하고, 자기주식 취득은 둘 다 빼고, 배당은 현금만 뺐습니다. "
          "배당은 배당기준일이 평가기준일과 같거나 그 전이면 반영했습니다(배당락). 소각은 유통주식수를 바꾸지 않아 기록만 했습니다."
          + (" 「확인 불가」는 결정만 공시되고 평가기준일까지 실행 결과가 공시되지 않은 사건입니다. 주주가치 이월에 반영하지 않았고, "
             "표의 금액과 주식 수는 결정 공시의 값입니다." if 못 else ""), ""]
    return L


def _사이확인불가(맥):
    """재료 `_raw/사이자본거래.json`(「사이자본거래/1」 — 날짜 둘이 가정과 같을 때만)의 확인 불가 사건 → 사이 표의 줄(이름 · 결정 금액 · 「확인 불가 — 이월 다리에 넣지 않음」).
    금액은 원 단위 재료라 금액 단위로 나눠 장부 식으로 찍는다(「파일:사이자본거래:사건:<i>:근거:…」 — 게이트 ⑦ 이 같은 파일을 해시로 다시 읽는다)."""
    import 레터 as _L                                       # noqa: PLC0415
    d = (getattr(맥, "재료", None) or {}).get("사이자본거래")
    if not isinstance(d, dict) or d.get("형식") != "사이자본거래/1":
        return []
    T = ("%s" % ((맥.메타 or {}).get("평가기준일") or "")).strip()[:10]
    if ("%s" % (d.get("평가기준일") or ""))[:10] != T or ("%s" % (d.get("재무기준일") or ""))[:10] != 재무날(맥):
        맥.알림.append("사이자본거래.json 의 날짜(%s · %s)가 가정과 다르다 — 확인 불가 사건을 사이 표에 싣지 않았다" % (d.get("재무기준일"), d.get("평가기준일")))
        return []
    사건 = d.get("사건") if isinstance(d.get("사건"), list) else []
    자리 = {("%s" % (s.get("접수번호") or "")): i for i, s in enumerate(사건) if isinstance(s, dict) and s.get("접수번호")}
    배 = "상:%d" % int(_L.단위배(맥.메타))
    줄 = []
    for x in d.get("확인불가") or []:
        if not isinstance(x, dict):
            continue
        접 = "%s" % (x.get("접수번호") or "")
        i = 자리.get(접)
        s = 사건[i] if i is not None else {}
        근 = s.get("근거") if isinstance(s.get("근거"), dict) else {}
        금키 = next((k for k in ("예정금액", "배당금총액") if _n(근.get(k)) is not None), None)
        주키 = next((k for k in ("예정주식수", "신주의수") if _n(근.get(k)) is not None), None)
        금 = 맥.식(["÷", "파일:사이자본거래:사건:%d:근거:%s" % (i, 금키), 배], "금액") if (i is not None and 금키) else None
        주 = 맥.수("파일:사이자본거래:사건:%d:근거:%s" % (i, 주키), "주") if (i is not None and 주키) else "—"
        이름 = 맥.바깥글(("%s" % (x.get("제목") or s.get("제목") or x.get("종류") or "")).strip()) or "—"
        줄.append([("%s" % (s.get("날짜") or s.get("공시일") or ""))[:10] or "—", ("%s" % (x.get("종류") or "")).strip() or "—",
                  ("%s · 결정 금액 %s" % (이름, 금)) if 금 else "%s · 결정 금액은 공시 원문에서 확인하지 못했습니다" % 이름,   # 1.1.9 — 「미기재」 는 레터의 빈칸 금지어
                  "확인 불가 — 이월 다리에 넣지 않음", 주,
                  ("%s %s" % ("SEC" if d.get("국가") == "US" else "DART", 접)) if 접 else "—"])
    return 줄


def 후사건(맥):
    """평가기준일 후 사건 — 평가기준일 뒤에 처음 생긴 사건(값에 넣지 않는다 · 키트 CLAUDE.md 「평가기준일 뒤에 나온 정보는 둘로 가른다」).
    재료: 레터부록 「기준일후사건」[{날짜 · 내용 · 출처}] + 가정 `관측.사이자본거래[]` 의 평가기준일 뒤 항목. 없으면 []."""
    부 = (맥.부록 or {}).get("기준일후사건") if isinstance(getattr(맥, "부록", None), dict) else None
    T = ("%s" % ((맥.메타 or {}).get("평가기준일") or "")).strip()[:10]
    줄 = []
    for i, x in enumerate(부 if isinstance(부, list) else []):
        if not isinstance(x, dict):
            continue
        d = ("%s" % (x.get("날짜") or "")).strip()[:10]
        if d and T and d <= T:
            맥.알림.append("레터부록 「기준일후사건[%d]」 의 날짜 %s 이 평가기준일 %s 뒤가 아니다 — 싣지 않았다" % (i, d, T))
            continue
        내 = 맥.원고글(x.get("내용"), "부록.기준일후사건[%d].내용" % i, 부록=True)
        if not 내:
            continue
        출 = 맥.바깥글(("%s" % (x.get("출처") or "")).strip())
        줄.append("- %s%s%s" % (("%s · " % d) if d else "", 내.rstrip("."), (" (%s)" % 출) if 출 else ""))   # 1.1.9 — 날짜가 없으면 날짜 칸을 뺀다(「미기재」 는 빈칸 금지어)
    for i, x, 쪽 in _사이목록(맥):
        if 쪽 != "뒤":
            continue
        설 = 사이설명(맥, x, i)
        출 = 맥.바깥글(("%s" % (x.get("출처") or "")).strip())
        줄.append("- %s · %s%s%s" % (("%s" % x.get("날짜"))[:10], ("%s" % (x.get("종류") or "자본거래")).strip(), (" — " + 설.rstrip(".")) if 설 else "",
                                    (" (%s)" % 출) if 출 else ""))
    if not 줄:
        return []
    return (["### 평가기준일 후 사건", "",
             "평가기준일(%s) 뒤에 처음 생긴 사건은 그날 시장이 알 수 없던 정보이므로 주당가치에 반영하지 않았습니다. "
             "주당가치를 바꿀 만한 사건이면 평가기준일을 옮겨 새로 평가합니다." % 맥.엔진글("메:평가기준일:날짜"), ""] + 줄 + [""])


def 종가말(맥):
    """「2026년 6월 30일 종가」 — 레터 어디서든 종가는 날짜와 함께(날짜는 장부의 엔진 글 — 평가기준일).
    평가기준일이 거래일이 아니면(주말 · 휴장) 종가는 그 앞 마지막 거래일의 값이다 — 일별 종가 파일의 그날 종가가 평가 종가와 같으면
    그 거래일을 적는다(회차 20261023 NVDA — 평가기준일 7월 26일 일요일 · 종가는 7월 24일)."""
    if not hasattr(맥, "엔진글"):                             # 숫자 쪽만 흉내 낸 맥(도구 시험 · 짧은 판) — 메타의 평가기준일을 그대로 날말로
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", "%s" % ((getattr(맥, "메타", None) or {}).get("평가기준일") or ""))
        return ("%d년 %d월 %d일 종가" % (int(m.group(1)), int(m.group(2)), int(m.group(3)))) if m else "평가기준일 종가"
    d = _종가거래일(맥)
    return "%s 종가" % (맥.엔진글("주:날말:%s" % d) if d else 맥.엔진글("메:평가기준일:날짜"))


def _종가거래일(맥):
    """평가 종가가 평가기준일 앞 거래일의 값이면 그 날짜(「YYYY-MM-DD」), 아니면 None."""
    try:
        import 레터궤적 as G                                 # noqa: PLC0415
        줄 = (getattr(맥, "주가", None) or {}).get("줄") or []
        기준 = ("%s" % ((맥.메타 or {}).get("평가기준일") or "")).strip()[:10]
        종 = _n(맥.값(맥.종가키)) if getattr(맥, "종가키", None) else None
        if not (줄 and 기준 and 종):
            return None
        기날 = G._날(기준)
        앞 = [x for x in 줄 if G._날(x[0]) <= 기날]
        if not 앞 or G._날(앞[-1][0]) == 기날 or (기날 - G._날(앞[-1][0])).days > 5:
            return None
        if abs((_n(앞[-1][1]) or 0) / 종 - 1) > 0.005:
            return None
        return G._날(앞[-1][0]).strftime("%Y-%m-%d")
    except Exception:                                        # noqa: BLE001
        return None


def _표4줄들(맥):
    """표 Ⅳ(엔진 역산)의 줄 — [{h, 갈래, 이름, 꼴, 키, 적용, 내재, 비고}]. 풀이가 없으면 내재 = None."""
    낸 = []
    for i, r in enumerate(맥.민["표4"]["줄"]):
        h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
        꼴 = 손잡이꼴(h, 맥)
        풀이 = _n(r.get("내재값")) is not None
        낸.append({"h": h, "갈래": _손잡이갈래(h)[0], "이름": 손잡이이름(h, 맥), "꼴": 꼴, "키": "민:표4:줄:%d:내재값" % i,
                  "적키": "민:표4:줄:%d:적용값" % i, "i": i,
                  "적용": 맥.수("민:표4:줄:%d:적용값" % i, 꼴),
                  "내재": 맥.수("민:표4:줄:%d:내재값" % i, 꼴) if 풀이 else None,
                  "비고": 맥.엔진글("민:표4:줄:%d:비고" % i) if ("%s" % (r.get("비고") or "")).strip() else ""})
    return 낸


def _기준기간이름(맥, x):
    """매출 구분의 기준 기간을 읽는 말 — 직전 분기면 「2026년 2분기」, 직전 회계연도면 「2025년」 따위.
    기준 기간은 재무 자료의 기간이라 재무 자료 기준일에서 센다(2026-10-25 날짜 둘 — 없으면 평가기준일 · 옛 글 그대로)."""
    m = re.match(r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})", "%s" % (재무날(맥) or 맥.메타.get("평가기준일") or ""))
    if not m:
        return "기준 기간"
    년, 월 = int(m.group(1)), int(m.group(2))
    종 = x.get("기준기간") or ""
    if 종 == "직전분기":
        return "%d년 %d분기" % (년, (월 - 1) // 3 + 1)
    if 종 == "직전회계연도":
        return "%d년" % (년 - 1 if 월 != 12 else 년)
    if 종 == "누계":
        return "%d년 %d월까지" % (년, 월)
    return "기준 기간"


def _L구분(맥, 대상):
    """역산 손잡이 대상(6s6) → 매출 구분 이름."""
    import 레터 as _L                                       # noqa: PLC0415
    d = "%s" % 대상
    return _L.구분이름(맥.구, int(d[1])) if len(d) == 3 and d.startswith("6") and d[1].isdigit() else d


def _비고글(r):
    return (" %s. 성립 조건을 벗어난 값입니다." % r["비고"]) if r["비고"] else ""


def _단가말(x):
    """매출 구분의 판매단가 명칭에서 「지수」를 뗀 말 — 「웨이퍼당 매출 지수」 → 「웨이퍼당 매출」."""
    말 = ("%s" % (x.get("판매단가명칭") or "판매단가 지수")).strip()
    return 말[:-2].strip() if 말.endswith("지수") and len(말) > 2 else 말


def _표4방식(맥, r):
    """표 Ⅳ 줄의 손잡이 방식 — 엔진이 표 Ⅳ 줄에 적은 방식(S9-03 — 유형 기본 정상 수준은 배율)이 먼저, 없으면 선언한 역산 축의 방식, 아니면 가산."""
    if r["h"].get("방식"):
        return r["h"]["방식"]
    축 = (맥.가정.get("역산") or {}).get("축")
    if isinstance(축, dict) and ["%s" % x for x in 축.get("대상") or []] == ["%s" % x for x in r["h"]["대상"]]:
        return 축.get("방식", "가산")
    return "가산"


def _정상눈금(맥, r):
    """표 Ⅳ 의 정상 수준 판매단가 지수 줄 → 독자가 아는 눈금(그 구분의 기준 기간 = 100%). 구분마다 내재 · 채택 비율 글과 지수 글.
    정상단가 줄이 아니거나 기준 기간 지수가 없으면 None."""
    import 레터 as _L                                       # noqa: PLC0415
    if r["갈래"] != "정상단가" or r["내재"] is None:
        return None
    구분들 = []
    for d in ("%s" % x for x in r["h"]["대상"]):
        if not (len(d) == 3 and d[0] == "6" and d[2] == "6" and d[1].isdigit()):
            return None
        x = next((y for y in 맥.구.get("매출구분") or [] if y.get("번호") == int(d[1])), None)
        if x is None or not _n(맥.값(눈금키(맥, int(d[1])))):
            return None
        구분들.append((int(d[1]), x))
    방식 = _표4방식(맥, r)

    def 내(s):
        if 방식 == "값":
            return r["키"]
        if 방식 == "배율":
            return ["×", "S:6%d6:기준" % s, ["÷", r["키"], r["적키"]]]
        return ["합", "S:6%d6:기준" % s, ["−", r["키"], r["적키"]]]
    말들 = {_단가말(x) for _s, x in 구분들}
    기간들 = {눈금이름(맥, x) for _s, x in 구분들}
    지수 = [r["내재"] if 방식 == "값" or len(구분들) == 1 else 맥.식(내(s), "지수2") for s, _x in 구분들]
    채택 = [맥.수("S:6%d6:기준" % s, "지수2") for s, _x in 구분들]
    return {"구분": [_L.구분이름(맥.구, s) for s, _x in 구분들], "말": 말들.pop() if len(말들) == 1 else "판매단가",
            "기간": 기간들.pop() if len(기간들) == 1 else "각 구분의 기준 기간",
            "방식": {"값": "같은 값", "배율": "같은 비율"}.get(방식, "같은 폭"),
            "내재": [맥.식(["÷", 내(s), 눈금키(맥, s)], "퍼0") for s, _x in 구분들],
            "적용": [맥.식(["÷", "S:6%d6:기준" % s, 눈금키(맥, s)], "퍼0") for s, _x in 구분들],
            "지수": 지수[0] if len(set(지수)) == 1 else " · ".join(지수), "지수채택": 채택[0] if len(set(채택)) == 1 else " · ".join(채택),
            "여럿": len(set(지수)) > 1}


def _정상눈금줄(맥, 눈, 비고=""):
    """13절의 줄 — 「DRAM 웨이퍼당 매출(정상 수준) : 2026년 2분기의 85%(채택 38%). 지수로는 2.14(채택 0.95)다.」"""
    if len(눈["구분"]) == 1:
        머 = "%s %s(정상 수준) : %s의 %s(채택 %s)" % (눈["구분"][0], 눈["말"], 눈["기간"], 눈["내재"][0], 눈["적용"][0])
    else:
        머 = "%s %s(정상 수준, %s) : 각각 %s의 %s(채택 %s)" % (" · ".join(눈["구분"]), 눈["말"], 눈["방식"], 눈["기간"],
                                                       " · ".join(눈["내재"]), " · ".join(눈["적용"]))
    return "- %s. 지수로는 %s%s(채택 %s)입니다.%s" % (머, "각각 " if 눈["여럿"] else "", 눈["지수"], 눈["지수채택"], 비고)


def _능력줄(맥, x):
    """매출 구분 x 의 생산능력 역산 — 설비투자와 짝(회차 입력 「능력투자」의 단가) · 투자 없이는 상한 한 줄."""
    import 레터 as _L                                       # noqa: PLC0415
    s = x["번호"]
    이름 = _L.구분이름(맥.구, s)
    량 = ("%s" % (x.get("판매량명칭") or "판매량")).strip()
    단위 = ("%s" % (x.get("판매량단위") or "")).strip()
    끝 = 맥.끝예측
    채택 = 맥.수("R:기준:4.Sales:1%d9:%s" % (s, 끝), "수1")
    L = []
    입 = _L.능력투자입력(맥.원, s)
    근글 = 맥.원고글(입.get("근거"), "가격성립.능력투자.%d.근거" % s, 부록=True) if 입 and 입.get("근거") else ""
    근 = (" %s." % 근글.rstrip(".")) if 근글 else ""
    if 입 is not None and _n(맥.값("가:능력투자:%d:한계" % s)) is not None:
        단가 = 맥.수("가:능력투자:%d:단가" % s, "금액")
        속 = (맥.구.get("투자") or {}).get("유지속성") or {}
        환 = "(환율 조정 전)" if 속.get("환율적용", "예") == "예" and ((맥.구.get("환율") or {}).get("경로") or "없음") != "없음" else ""
        if _n(맥.값("가:능력투자:%d" % s)) is not None:
            L.append("- %s %s(%s 말) : %s%s(채택 %s). 늘린 %s%s에는 1%s당 %s, 모두 %s%s의 설비투자를 생산능력이 늘어나는 기간에 함께 반영했습니다.%s" % (
                이름, 량, 맥.열말(끝), 맥.수("가:능력투자:%d:끝" % s, "수1"), (" %s" % 단위) if 단위 else "", 채택,
                맥.수("가:능력투자:%d" % s, "수1"), (" %s" % 단위) if 단위 else "", 단위, 단가, 맥.수("가:능력투자:%d:투자" % s, "금액"), 환, 근))
        else:
            한계 = _n(맥.값("가:능력투자:%d:한계" % s))
            한계글 = 맥.수("가:능력투자:%d:한계" % s, "주당") if 한계 > 0 else 맥.식(["음", "가:능력투자:%d:한계" % s], "주당")
            쪽 = "늘지만 찾은 범위 안에서는 주당가치가 이 가격과 같아지지 않습니다" if 한계 > 0 \
                else "줄어 생산능력으로는 이 가격이 성립하지 않습니다"
            L.append("- %s %s : 늘린 생산능력에 1%s당 %s%s의 설비투자를 함께 넣으면 1%s마다 주당가치가 %s %s.%s" % (
                이름, 량, 단위, 단가, 환, 단위, 한계글, 쪽, 근))
    elif 입 is None:
        맥.알림.append("가격 성립 입력에 %s 의 「능력투자」 단가가 없다 — 생산능력은 설비투자 없이 늘린 상한만 실었다" % 이름)
    if _n(맥.값("가:능력:%d" % s)) is not None:
        L.append("- %s %s(%s 말, 상한) : %s%s(채택 %s). 설비투자 없이 모든 라인의 생산능력만 같은 비율로 늘린다고 가정한 값입니다." % (
            이름, 량, 맥.열말(끝), 맥.수("가:능력:%d" % s, "수1"), (" %s" % 단위) if 단위 else "", 채택))
    return L


def _가격성립수준(맥, 표4단일=()):
    """매출 구분별 — 정상 수준 판매단가(그 구분만 · 다른 구분은 채택값, 기준 기간 = 100% 눈금) · 생산능력(설비투자와 짝 · 상한).
    표4단일 = 표 Ⅳ 에 이미 한 구분짜리 줄이 있는 구분 번호(같은 줄을 두 번 싣지 않는다)."""
    import 레터 as _L                                       # noqa: PLC0415
    구분들 = [x for x in 맥.구.get("매출구분") or [] if x.get("경로") == "수준" and x.get("번호", 6) < 6]
    수렴 = [x for x in 구분들 if x.get("단가경로") == "수렴" and _n(_L._시점값(맥.가정, "6%d6" % x["번호"], "기준")) is not None]
    L = []
    for x in 수렴:
        s = x["번호"]
        if s in 표4단일:
            continue
        이름 = _L.구분이름(맥.구, s)
        단 = _L.구분뗀말(_단가말(x), 이름)                    # 「<구분> <구분> …」 겹침 막음
        if _n(맥.값("가:정상:%d" % s)) is None:
            L.append("- %s %s(정상 수준) : 의미 있는 범위 안에서 이 가격이 성립하는 값이 없습니다." % (이름, 단))
            continue
        남 = [_L.구분이름(맥.구, y["번호"]) for y in 수렴 if y is not x]
        if _n(맥.값(눈금키(맥, s))):
            L.append("- %s %s(정상 수준) : %s의 %s(채택 %s). 지수로는 %s(채택 %s)입니다.%s" % (
                이름, 단, 눈금이름(맥, x), 맥.식(["÷", "가:정상:%d" % s, 눈금키(맥, s)], "퍼0"),
                맥.식(["÷", "S:6%d6:기준" % s, 눈금키(맥, s)], "퍼0"), 맥.수("가:정상:%d" % s, "지수2"),
                맥.수("S:6%d6:기준" % s, "지수2"), (" %s 채택값을 유지했습니다." % 은(_나열(남))) if 남 else ""))
        else:
            L.append("- %s %s 지수(정상 수준) : %s(채택 %s).%s" % (이름, 단, 맥.수("가:정상:%d" % s, "지수2"), 맥.수("S:6%d6:기준" % s, "지수2"),
                                                          (" %s 채택값을 유지했습니다." % 은(_나열(남))) if 남 else ""))
    for x in 구분들:
        if x.get("판매량산정") == "능력":
            L += _능력줄(맥, x)
    return L


def _가격성립전사(맥):
    """매출(예측기간 매출 증가율 — 엔진 역산, S9-03) — 표 Ⅳ 의 매출성장 줄. 매출 줄마다 같은 폭을 더해 이 가격에 닿는 예측기간 매출 연평균 증가율과
    끝 해 매출. 원가 비율 · 재투자 규칙 · 영구가치는 모델 그대로다(같은 엔진 · 같은 영구 계산 — 옛 「전사 단순 역산」 은 평가 모델 밖의 식이라 걷었다)."""
    if _n(맥.값("가:성장:모델")) is None:
        return []
    연 = _n(맥.값("가:성장:연수"))
    if _n(맥.값("가:성장:증가율")) is None:
        L = ["매출 항목마다 같은 크기를 더해도 주당가치가 이 가격과 같아지는 예측기간 매출 증가율을 찾지 못했습니다. 모델의 예측기간 매출 연평균 증가율은 %s." % 입니다(
            맥.수("가:성장:모델", "퍼1")), ""]
    else:
        L = ["**표. 이 가격에 필요한 예측기간(%s년) 매출 증가율(%s 연환산 매출 %s 기준)**" % (
            ("%.1f" % 연).rstrip("0").rstrip(".") if 연 else "—", 맥.열말(맥.값("가:성장:열")), 맥.수("가:성장:시작매출", "금액")), ""]
        L += _표(["", "예측기간 매출 연평균 증가율(CAGR)", "%s 매출" % 맥.열말(맥.값("가:성장:끝열"))],
                [["모델", 맥.수("가:성장:모델", "퍼1"), 맥.수("가:성장:모델끝매출", "금액")],
                 ["이 가격에 필요한 값", 맥.수("가:성장:증가율", "퍼1"), 맥.수("가:성장:끝매출", "금액")]], ["l", "r", "r"])
        L.append("")
    L.append("평가 모델의 매출 항목마다 해마다 같은 크기를 더해, 주당가치가 이 가격과 같아지는 크기를 같은 평가 모델로 역산했습니다. "
             "원가 비율 · 재투자 규칙 · 할인율 · Terminal Value 계산은 모델과 같습니다. 성장 CAPEX 규칙이 없는 모델이면 늘어난 매출에 투자가 붙지 않아 필요한 증가율이 낮게 계산됩니다.")
    L.append("")
    return L


def _독자가격(맥):
    """S9-06 — 7단계 끝에 독자가 고른 가격(매수 단가 · 오늘 종가 · 목표주가 — `_raw/역산_독자.json`)마다 표 Ⅳ 와 같은 축으로 그 가격이 전제한 값.
    날짜가 평가기준일과 다르면 그날로 굴려 견준다(다른 가정은 평가기준일의 것 그대로). 판정 문장은 쓰지 않는다."""
    import 레터궤적 as G                                     # noqa: PLC0415
    r = G.독자셈(맥.원)
    if not r:
        return []
    L = []
    for k, x in enumerate(r):
        머 = "고른 가격 %d — %s(%s)" % (k + 1, 맥.수("독:%d:주가" % k, "어림주당"), 맥.엔진글("독:%d:날말" % k))      # 근거 글(매수 단가 따위)은 싣지 않는다 — 권유어 검수 · 판정이 아니다
        조각 = []
        for i, a in enumerate(x["축"]):
            if a.get("값") is None:
                continue
            꼴 = 손잡이꼴({"이름": a["이름"], "대상": a["대상"]}, 맥)
            조각.append("%s %s(채택 %s)" % (손잡이이름({"이름": a["이름"], "대상": a["대상"]}, 맥), 맥.수("독:%d:축:%d:값" % (k, i), 꼴),
                                          맥.수("독:%d:축:%d:적용" % (k, i), 꼴)))
        L.append("- %s : %s" % (머, " · ".join(조각) if 조각 else "가정 하나만 바꿔서는 이 가격이 성립하는 값이 없습니다"))
    L += ["", "가정 하나만 바꾸고 다른 가정은 채택값을 유지한 결과입니다. 평가기준일이 아닌 날의 가격은 그날로 굴려 비교했고, 다른 가정은 평가기준일의 값을 유지했습니다. "
          "그 가격이 성립하는 조건을 보인 것이며, 그 가격의 높고 낮음을 판단한 결과가 아닙니다.", ""]
    return L


def 연간실적열(맥):
    """범위 잣대가 되는 실적 열 — 회계연도(12개월) 실적 열만(1.1.20 — ADDER80 백테스트: 반기 실적 영업이익률이 역산 범위의 위 끝이 돼
    그보다 낮은 필요값을 「범위 안」 으로 판정했다 · 가정 표의 실적 범위는 회계연도 기준). 맥에 회계연도 묶음이 없으면(옛 픽스처) 실적 열 그대로."""
    fy = getattr(맥, "FY실적", None)
    if fy is None:
        return list(맥.실적열)
    fy = set(fy)
    return [c for c in 맥.실적열 if c in fy]


def _실적이익률범위(맥):
    """실적 열의 영업이익률 범위 — 「실적 기간(FY2023A~1H26A)의 영업이익률은 −23.6%~74.4%다」 (비교 기준). 없으면 빈 글. 1.1.20 — 회계연도 열만."""
    D = "R:기준:2.DCF:%s:%s"
    값 = []
    for c in 연간실적열(맥):
        a, b = _n(맥.값(D % ("15", c))), _n(맥.값(D % ("11", c)))
        if a is not None and b:
            값.append((a / b, c))
    if len(값) < 2:
        return ""
    lo, hi = min(값), max(값)
    return " 실적 기간(%s~%s)의 영업이익률은 %s~%s." % (값[0][1], 값[-1][1], 맥.식(["÷", D % ("15", lo[1]), D % ("11", lo[1])], "퍼1"),
                                                  입니다(맥.식(["÷", D % ("15", hi[1]), D % ("11", hi[1])], "퍼1")))


def _손잡이(손):
    return {"이름": 손.get("이름") or "손잡이", "대상": ["%s" % x for x in 손.get("대상") or []], "방식": 손.get("방식", "가산")}


def _손잡이글(맥, 손, 키):
    h = _손잡이(손)
    return "%s %s" % (손잡이이름(h, 맥), 맥.수(키, 손잡이꼴(h, 맥)))


def _남은차이(맥, 풀, 키, 종):
    """남은 차이를 메울 값 칸 — 풀 손잡이의 값, 이미 종가 이상이면 「이미 넘는다」, 풀이가 없으면 「—」."""
    if 풀 and _n(맥.값(키 + ":풀")) is not None:
        return _손잡이글(맥, 풀, 키 + ":풀")
    return "이미 넘음" if (_n(맥.값(키)) or 0) >= (_n(맥.값(종)) or 0) else "—"     # 2026-10-26 — 「종가」 는 날짜와 함께만(⑫) · 칸은 짧게


def _가격성립증설(맥, 종):
    """기준에서 뺀 증설 — 회차 입력의 사례마다 덧씌운 가정의 주당가치 · 남은 차이를 메울 값. 표를 읽는 설명은 첫 사례 뒤에 한 번(W6e)."""
    L, 움직인, 설명자리 = [], [], None
    for i, 입 in enumerate((맥.가성 or {}).get("증설") or []):
        for 칸, 말 in (("이름", "사례"), ("까닭", "기준에서 뺀 까닭"), ("투자액", "투자액"), ("가동", "가동 시작"), ("근거", "근거")):
            글 = 맥.원고글(입.get(칸), "가격성립.증설.%d.%s" % (i, 칸), 부록=True)
            if 글:
                공 = ("%s" % (입.get("공표일") or "")).strip() if 칸 == "근거" else ""
                L.append("- %s : %s%s" % (말, 글.rstrip("."), (" (공표일 %s)" % 공) if 공 else ""))
        L.append("")
        풀 = 입.get("풀손잡이")
        줄들 = []
        for j, 변 in enumerate(입.get("변형") or [{}]):
            키 = "가:증설:%d:%d" % (i, j)
            줄들.append([맥.원고글(변.get("이름"), "가격성립.증설.%d.변형.%d" % (i, j), 부록=True) or "덧씌운 가정",
                       맥.원고글(변.get("근거"), "가격성립.증설.%d.변형.%d.근거" % (i, j), 부록=True) or "—",
                       맥.수(키, "주당"), 맥.식(["÷", 키, 종], "퍼0"), _남은차이(맥, 풀, 키, 종)])
        L += _표(["변형", "근거", "주당가치", "%s 대비" % 종가말(맥), "남은 차이를 메울 값"], 줄들, ["l", "l", "r", "r", "l"])
        L.append("")
        if 풀:
            이름 = 손잡이이름(_손잡이(풀), 맥)
            if 이름 not in 움직인:
                움직인.append(이름)
        if i == 0:
            설명자리 = len(L)
    if 설명자리 is not None:              # 설명은 절에 한 번 — 첫 사례의 표 뒤(W6e)
        L[설명자리:설명자리] = ["주당가치는 기준 시나리오에 사례의 증설을 덧씌워 평가 모델로 다시 계산한 값입니다.%s" % (
            (" 남은 차이를 메울 값은 덧씌운 가정에서 %s 하나만 바꿔 주당가치가 이 가격과 같아지는 값입니다." % " · ".join(움직인)) if 움직인 else ""), ""]
    return L


def _가격성립조합(맥, 종):
    """조합 사례 — 그럴듯하지만 낙관적인 가정 여럿을 함께 켠 경우의 주당가치(회차 입력)."""
    가성 = 맥.가성 or {}
    줄들, 근거들 = [], []
    조 = 가성.get("조합") or []
    for i in sorted(range(len(조)), key=lambda k: _n(맥.값("가:조합:%d" % k)) or 0):
        입 = 조[i]
        키 = "가:조합:%d" % i
        바꾼 = []
        증 = 입.get("증설")
        if 증:
            이름 = 증.get("이름") if isinstance(증, dict) else 증
            j = int(증.get("변형", 0)) if isinstance(증, dict) else 0
            k = next((n for n, x in enumerate(가성.get("증설") or []) if x.get("이름") == 이름), None)
            변 = ((가성.get("증설") or [])[k].get("변형") or [{}])[j] if k is not None else {}
            바꾼.append(맥.원고글(이름, "가격성립.조합.%d.증설" % i, 부록=True))
            if 변.get("이름"):
                바꾼.append(맥.원고글(변["이름"], "가격성립.조합.%d.변형" % i, 부록=True))
        if 입.get("덧씌우기"):
            바꾼.append(맥.원고글(입.get("덧씌우기말") or "", "가격성립.조합.%d.덧씌우기말" % i, 부록=True) or "덧씌운 가정")
        for k, 손 in enumerate(입.get("손잡이") or []):
            바꾼.append(_손잡이글(맥, 손, "가:조합:%d:손:%d" % (i, k)))
        줄들.append([맥.원고글(입.get("이름"), "가격성립.조합.%d.이름" % i, 부록=True), " · ".join(x for x in 바꾼 if x),
                   맥.수(키, "주당"), 맥.식(["÷", 키, 종], "퍼0"), _남은차이(맥, 입.get("풀손잡이"), 키, 종)])
        근 = 맥.원고글(입.get("근거"), "가격성립.조합.%d.근거" % i, 부록=True)
        최고 = max(range(len(조)), key=lambda k: _n(맥.값("가:조합:%d" % k)) or 0)
        if 근 and re.search(r"가장 낙관적", 근) and i != 최고:
            맥.알림.append("가격 성립 입력 「조합[%d]」 의 근거가 「가장 …」 이라 했으나 주당가치는 가장 높지 않다 — 근거를 싣지 않았다(이름표는 값 순서로)" % i)
            근 = ""
        if 근:
            근거들.append("- %s : %s" % (줄들[-1][0], 근))
    if not 줄들:
        return []
    L = _표(["사례", "바꾼 가정", "주당가치", "%s 대비" % 종가말(맥), "남은 차이를 메울 값"], 줄들, ["l", "l", "r", "r", "l"])
    L.append("")
    if 근거들:
        L += 근거들
        L.append("")
    return L


def 이익률100줄(맥, 줄들=None):
    """역산 절 「평가기준일 분석」 결론의 첫 문장(「{영구 이익률 줄 이름}을 100%로 두어도 주당가치는 … 종가의 x%입니다」)이 서는가 — 서면 그 표 Ⅳ 줄,
    아니면 None. 같은 절에 싣는 막4 몸(`레터막.막4` — 레터본문 역산 절이 앞에 붙인다)은 이 줄이 서면 같은 사실을 되풀이하지 않는다(1.1.19 — 한 절에 세 번)."""
    if not getattr(맥, "종가키", None) or not getattr(맥, "민", None):
        return None
    v100 = _n(맥.값("가:이익률:1"))
    if v100 is None or not v100 < (_n(맥.값(맥.종가키)) or 0):
        return None
    if 줄들 is None:                                          # 장부에 적지 않고 갈래만 본다(`_표4줄들` 은 칸마다 장부에 적는다)
        줄들 = [{"갈래": _손잡이갈래({"이름": r.get("이름"), "대상": r.get("대상"), "방식": r.get("방식")})[0], "i": i}
               for i, r in enumerate(((맥.민.get("표4") or {}).get("줄")) or [])]
    return next((r for r in 줄들 if r["갈래"] in ("영구이익률가감", "Normalization")), None)


def 역산절(맥, 번):
    """「이 가격이 성립하려면 필요한 가정」 — R1b(L8): 「평가기준일 분석」(결론 한 줄 — 영업이익률 100% 를 먼저 — 과 표 하나)과
    「평가기준일 뒤의 사건」(결론 한 줄과 표 하나)으로 가른다. 매출 구분별 · 생산능력 · 전사 단순 역산의 셈법 · 증설 사례별 표 ·
    조합의 근거 · 가격 위치 격자는 부록 J 로. 결론형 권유는 쓰지 않는다 — 필요한 가정의 목록일 뿐이다."""
    L = ["## %d. 이 가격이 성립하려면 필요한 가정" % 번, ""]
    종, 기 = 맥.종가키, "R:기준:2.DCF:68"
    머 = "%s %s 기준 시나리오 주당가치 %s의 %s." % (종가말(맥), 은(맥.수(종, "주당")), 맥.수(기, "주당"), 입니다(맥.식(["÷", 종, 기], "배")))
    낙, 종값 = _n(맥.값("R:낙관:2.DCF:68")), _n(맥.값(종))
    if 낙 and 종값:
        머 += " 낙관 시나리오의 주당가치는 이 가격의 %s." % 입니다(맥.식(["÷", "R:낙관:2.DCF:68", 종], "배"))
    L.append(머)
    # 1.1.21 — 「이 가격에는 {Narrative.가격} 반영돼 있습니다」 는 지웠다 — 이 절은 늘 본편 역산 절이 막4(「이 가격은 … 가깝습니다」 — 같은 원고) 뒤에
    # 붙이므로 한 절에 같은 Narrative 가 두 번 섰다(서른 곳 · ADDER80 백테스트 맥 읽기)
    L.append("")
    줄들 = _표4줄들(맥)
    맥.역산없음손잡이 = [r["h"] for r in 줄들 if r["내재"] is None]
    L += ["### 평가기준일 분석", ""]
    결론 = []
    이익줄 = 이익률100줄(맥, 줄들)
    if 이익줄 is not None:
        결론.append("%s %s 두어도 주당가치는 %s %s의 %s." % (을(이익줄["이름"]), 으로(맥.수("상:1", "퍼0")), 으로(맥.수("가:이익률:1", "주당")),
                                                    종가말(맥), 입니다(맥.식(["÷", "가:이익률:1", 종], "퍼0"))))
    된 = [r for r in 줄들 if r["내재"] is not None and not r["비고"]]
    if 된 and len(된) > 3:                                   # 넷 이상이면 이름만 — 값은 바로 아래 표에(견본 실측: 한 문장 136자 · ⑬ 오류)
        결론.append("가정 하나만 바꿔 주당가치를 이 가격과 같게 만들 수 있는 가정은 %s 등 %d가지입니다." % (
            _나열([r["이름"] for r in 된[:2]]), len(된)))
    elif 된:
        결론.append("가정 하나만 바꿔 주당가치를 이 가격과 같게 만들 수 있는 가정은 %s." % 입니다(_나열(["%s(%s)" % (r["이름"], r["내재"]) for r in 된])))
    elif 줄들:
        결론.append("가정 하나만 바꿔서는 주당가치가 이 가격과 같아지지 않습니다.")
    if 결론:
        L += [" ".join(결론), ""]
    L += _가격성립표(맥, 줄들)
    for r in 줄들:
        눈 = _정상눈금(맥, r)
        if 눈:
            L.append("%s %s %s의 %s(%s)입니다. 채택 %s %s." % (
                r["이름"], 은(r["내재"]), 눈["기간"], " · ".join(눈["내재"]), " · ".join(눈["구분"]), 은(r["적용"]), 입니다(" · ".join(눈["적용"]))))
            L.append("")
            break
    if 맥.역산없음손잡이:
        까 = _풀이없는까닭(맥)
        if 까:
            L += [" ".join(까), ""]
    _세부 = [말 for 말, 있 in (("매출 구분별 역산", any(x.get("경로") == "수준" and x.get("번호", 6) < 6 for x in 맥.구.get("매출구분") or [])),
                          ("생산능력", any(x.get("판매량산정") == "능력" for x in 맥.구.get("매출구분") or [])),
                          ("매출 증가율을 역산한 계산 방법", bool(_가격성립전사(맥))), ("가격 위치 격자", bool(레터이야기.격자셈(맥.원))),
                          ("기준에서 뺀 증설과 조합 사례의 세부", bool((맥.가성 or {}).get("증설") or (맥.가성 or {}).get("조합")))) if 있]
    # 1.1.20 — 「… 계산 방법은 부록 J에 있습니다」(문서 안내 · 원칙 3 — 서른 곳 같은 글)는 지웠다. 부록 J 의 절 제목이 그 자리를 말한다
    L.append("")
    L += _뒤사건(맥, 종)
    if not (맥.가성 or {}).get("증설") and not (맥.가성 or {}).get("조합"):
        맥.알림.append("가격 성립 입력(레터_가격성립.json)의 「증설」 · 「조합」 이 없다 — 기준에서 뺀 증설과 조합 사례를 싣지 않았다")
    L += 고지싸기(["이 값은 시장가격이 맞는지 틀리는지를 판정한 결과가 아닙니다. 그 가격이 성립하려면 어떤 가정이 필요한지를 보이는 값입니다."])     # 1.1.20 — 평가 고지라 고지 표지 안에
    맥.서술("역산")
    return L


def _밖파일(맥):
    """재료 `_raw/모델밖가치.json` — 발동했을 때만(아니면 None). 2026-10-27 결정 — 공시 밖 사업은 기준에 넣지 않고 이 자리에서만 셈한다."""
    f = ((맥.원.get("파일") or {}).get("모델밖가치")) or {}
    return f if f.get("발동") else None


def _밖열말(맥, 열):
    """「2029년」 · 잔여 기간 열이면 그 열이 시작하는 달(「2026년 10월」) — 「2026년 3개월부터」 처럼 읽히지 않게."""
    속 = 맥.속성.get(열, {})
    if 속.get("개월") == 12 or 속.get("종류") in ("FY실적", "연간예측"):
        return "%s년" % 속.get("회계연도")
    s = "%s" % (속.get("시작일") or "")
    return ("%s년 %d월" % (s[:4], int(s[5:7]))) if len(s) >= 7 else 맥.열말(열)


def _밖열이름(맥, 열):
    """표의 줄 이름 — 「2027년」 · 잔여 기간 열이면 「2026년 10~12월」(열말의 「2026년 3개월」 대신)."""
    속 = 맥.속성.get(열, {})
    if 속.get("개월") == 12 or 속.get("종류") in ("FY실적", "연간예측"):
        return "%s년" % 속.get("회계연도")
    a, b = "%s" % (속.get("시작일") or ""), "%s" % (속.get("종료일") or "")
    if len(a) >= 7 and len(b) >= 7:
        return "%s년 %d~%d월" % (a[:4], int(a[5:7]), int(b[5:7])) if a[:4] == b[:4] else "%s년 %d월~%s년 %d월" % (a[:4], int(a[5:7]), b[:4], int(b[5:7]))
    return 맥.열말(열)


def _밖마진말(맥, i, h):
    글 = 맥.엔진글("파일:모델밖가치:마진후보:%d:글" % i)
    if h.get("종류") == "실적" and h.get("열"):
        return "%s(%s)" % (글, 맥.열말(h["열"]))
    return 글


def _밖이름(맥, b, k):
    return 맥.원고글(b.get("이름"), "가격성립.공시밖.사업.%d.이름" % k, 부록=True)


def _공시밖(맥, 종):
    """역산 절 「공시 밖 사업이 메워야 할 값」(2026-10-27) — 종가가 낙관 시나리오보다 높거나 회차가 공시 밖 사업을 적었을 때만.
    차이(종가 − 기준 주당가치)를 공시 밖 사업 하나가 메운다고 보고 목표 영업이익률 × 시작 때마다 필요한 매출을 푼 표 · 근거가 다 있는 사업의
    사례 · 짓지 않은 사업의 까닭. 값은 `모델밖가치.장부값`(엔진의 할인 · 세율 · 영구 셈)으로 — 기준 · 비관 · 낙관 시나리오는 그대로다."""
    f = _밖파일(맥)
    if not f or not 종:
        return []
    if f.get("방향") == "아래":                              # 1.1.3(A2) — 종가 < 비관: 공시 밖 사업 격자 대신 모델 밖 할인
        import 레터갭 as _갭                                 # noqa: PLC0415
        return _갭.할인절(맥, f, 종)
    틈 = _n(맥.값("가:밖:틈"))
    if 틈 is None:
        return []
    L = ["### 공시 밖 사업이 메워야 할 값", ""]
    기, 낙 = "R:기준:2.DCF:68", "R:낙관:2.DCF:68"
    문 = []
    if 틈 <= 0:
        문.append("%s %s 기준 시나리오의 주당가치 %s보다 낮아 공시되지 않은 사업으로 설명할 차이는 없습니다." % (종가말(맥), 은(맥.수(종, "주당")), 맥.수(기, "주당")))
    else:
        if (_n(맥.값(낙)) or 0) < (_n(맥.값(종)) or 0):
            문.append("%s %s 낙관 시나리오의 주당가치 %s보다도 높습니다." % (종가말(맥), 은(맥.수(종, "주당")), 맥.수(낙, "주당")))
        # 1.1.21 — 「… 사업에서 나와야 하는 값입니다」 는 가정의 계산을 사실처럼 단정했다(바로 앞 문단은 그 근거를 찾지 못했다고 한다) — 가정으로 밝힌다
        문.append("기준 시나리오와의 차이 %s(주주가치로 %s, %s의 %s)를 이 평가에 넣지 않은 사업이 모두 메운다고 가정했습니다." % (
            맥.수("가:밖:틈", "주당"), 맥.수("가:밖:틈액", "금액"), 종가말(맥), 맥.수("가:밖:틈몫", "퍼0")))
    이름 = [x for x in (_밖이름(맥, b, k) for k, b in enumerate(f.get("사업") or [])) if x]
    if 이름:
        문.append("매출에 넣지 않은 사업은 %s." % 입니다(_나열(이름)))
    L += [" ".join(문), ""]
    회 = f.get("회전율")
    끝 = f.get("끝예측열")
    if 틈 > 0 and f.get("마진후보") and 회 and 끝:
        시작 = f.get("시작후보") or []
        줄들 = []
        for i, h in enumerate(f["마진후보"]):
            칸 = ["%s · %s" % (맥.수("가:밖:마진:%d" % i, "퍼1"), _밖마진말(맥, i, h))]
            for j, _s in enumerate(시작):
                if _n(맥.값("가:밖:필요:%d:%d" % (i, j))):
                    칸.append("%s (%s)" % (맥.수("가:밖:필요:%d:%d" % (i, j), "금액"), 맥.수("가:밖:필요배:%d:%d" % (i, j), "배1")))
                else:
                    칸.append("풀이 없음")
            줄들.append(칸)
        L += _표(["목표 영업이익률"] + ["%s부터" % _밖열말(맥, s["열"]) for s in 시작], 줄들, ["l"] + ["r"] * len(시작))
        L.append("")
        if "값" in 회:
            회말 = 맥.수("가:밖:회전", "배")
        else:
            회말 = "%s · %s" % (맥.수("가:밖:회전:앞", "배"), 맥.수("가:밖:회전:뒤", "배"))
        if 회.get("종류") == "모델":
            회출 = "이 평가의 %s 매출 ÷ 투하자본" % 맥.열말(끝)
        else:
            회출 = 맥.원고글(회.get("출처"), "가격성립.공시밖.회전율.출처", 부록=True) or "회차 입력"
        방 = ["그 차이가 모두 공시되지 않은 사업 하나에서 생긴다고 가정하고, 그 사업이 %s 한 해에 올려야 할 매출을 목표 영업이익률과 "   # 레터 v27 — 표 주석
             "매출 시작 연도별로 역산했습니다." % 맥.열말(끝),
             "괄호 안은 이 평가의 %s 매출 %s 대비 배수입니다." % (맥.열말(끝), 맥.수("가:밖:끝매출", "금액"))]
        # 1.1.20 — 셈의 방법 세 문장(매출 경로 · 투자 · 할인)은 회사와 무관한 방법 설명이라 부록 J 「공시 밖 사업」 으로 옮겼다(값 · 출처는 그대로 — 회전율)
        맥._밖방법 = ["매출은 시작 연도의 직전 연도 0에서 %s까지 매년 같은 금액씩 늘고, 그 뒤에는 영구성장률로 늘어난다고 가정했습니다." % 맥.열말(끝),
                    "매출 증가에 필요한 투자는 매출 증가분을 회전율 %s(%s)로 나눈 금액입니다." % (회말, 회출),
                    "할인율 · 세율 · 영구기간 계산은 이 평가와 같은 방법을 썼고, 그 사업의 비용은 목표 영업이익률 하나로 반영했습니다."]
        if any(h.get("종류") == "패널" for h in f["마진후보"]):
            방.append("대형 상장사는 같은 나라 상장사 가운데 5년 기간의 첫해 매출이 %s인 회사이고, 5년 평균은 그 기간의 영업이익률을 매출로 가중평균한 값입니다." % (
                맥.엔진글("파일:모델밖가치:패널:규모구간")))
        방.append("이 표는 그 사업이 실제로 그만큼의 매출을 올릴지를 판단한 결과가 아닙니다.")     # 1.1.20 — 뒤 문장(「… 매출로 나타냈습니다」)은 첫 문장과 같은 뜻이라 지웠다
        L += [" ".join(방), ""]
        L += _밖단위(맥, f)
    L += _밖사례(맥, f, 종)
    return L                                                # 1.1.20 — 「계산 과정의 세부 값과 사례의 근거는 부록 J에 있습니다」(원칙 3)는 지웠다


def _밖단위(맥, f):
    """단위 경제(단위당 연매출) · 시장 규모가 출처와 함께 적힌 사업만 — 표의 첫 시작(가장 이른 시작)으로 옮긴다. 시장 규모는 출처마다(평균 내지 않는다)."""
    L = []
    사 = ((맥.가성 or {}).get("공시밖") or {}).get("사업") or []
    for k, b in enumerate(f.get("사업") or []):
        단, 시장 = b.get("단위경제"), b.get("시장규모") or []
        이름 = _밖이름(맥, b, k)
        if (not 단 and not 시장) or not 이름 or k >= len(사):
            continue
        머 = ["목표 영업이익률"]
        if 단:
            머.append("필요한 %s 수" % (맥.원고글(단.get("단위"), "가격성립.공시밖.사업.%d.단위" % k, 부록=True) or "단위"))
        머 += ["시장 규모 출처 %d 대비" % (m + 1) for m in range(len(시장))]
        줄들 = []
        for i, _h in enumerate(f["마진후보"]):
            if not _n(맥.값("가:밖:필요:%d:0" % i)):
                continue
            칸 = [맥.수("가:밖:마진:%d" % i, "퍼1")]
            if 단:
                칸.append(맥.수("가:밖:단위:%d:%d:0" % (k, i), "수0"))
            칸 += [맥.수("가:밖:점유:%d:%d:%d:0" % (k, m, i), "퍼1") for m in range(len(시장))]
            줄들.append(칸)
        if not 줄들:
            continue
        L += ["**표. %s 하나가 차이를 모두 설명할 때 필요한 매출의 단위 경제 · 시장 규모 환산(가장 이른 시작 연도 기준)**" % 이름, ""]   # 레터 v27 — 표 제목
        L += _표(머, 줄들, ["l"] + ["r"] * (len(머) - 1))
        L.append("")
        덧 = []
        if 단:
            덧.append("단위 수는 필요한 매출을 단위당 연매출 %s로 나눈 값입니다(%s)." % (
                맥.수("가:밖:단위값:%d" % k, "금액"), 맥.원고글(단.get("출처"), "가격성립.공시밖.사업.%d.단위출처" % k, 부록=True) or "회차 입력"))
        for m, x in enumerate(시장):
            덧.append("%s %s(%s)." % (은("시장 규모 출처 %d" % (m + 1)), 입니다(맥.수("가:밖:시장값:%d:%d" % (k, m), "금액")),
                                               맥.원고글(x.get("출처"), "가격성립.공시밖.사업.%d.시장.%d" % (k, m), 부록=True) or "회차 입력"))
        if 덧:
            L += [" ".join(덧), ""]
    return L


def _밖사례(맥, f, 종):
    """근거 문장 · 출처 · 도착 매출(출처) · 목표 마진(출처)이 다 있는 사업의 사례 표와, 짓지 않은 사업의 까닭."""
    L, 줄들, 못 = [], [], []
    for k, b in enumerate(f.get("사업") or []):
        이름 = _밖이름(맥, b, k)
        if not 이름:
            continue
        if b.get("사례"):
            배 = _n(맥.값("가:밖:사례:%d:배" % k))
            줄들.append([이름, 맥.수("가:밖:사례:%d" % k, "부호주당"), 맥.수("가:밖:사례:%d:합" % k, "주당"),
                       맥.수("가:밖:사례:%d:합몫" % k, "퍼0"), (맥.수("가:밖:사례:%d:배" % k, "배1") if 배 else "—")])
        else:
            까 = [맥.엔진글("파일:모델밖가치:사업:%d:짓지않음:%d" % (k, n)) for n in range(len(b.get("짓지않음") or []))]
            까 = [x for x in 까 if x]
            못.append("%s 사례로 계산하지 않았습니다.%s" % (은(이름), (" 빠진 자료는 %s." % 입니다(" · ".join(까))) if 까 else ""))
    if 줄들:
        L += ["근거 문장 · 출처 · 도착 매출 · 목표 영업이익률이 모두 있는 사업은 그 값으로 따로 계산했습니다. 기준 · 비관 · 낙관 시나리오에는 더하지 않았습니다.", ""]
        L += _표(["사업", "주당가치에 더하는 몫", "기준 + 사례", "%s 대비" % 종가말(맥), "차이를 메우려면 도착 매출의"], 줄들, ["l", "r", "r", "r", "r"])
        L.append("")
    if 못:
        L += [" ".join(못), ""]
    return L


def _공시밖세부(맥, 종):
    """부록 J 「공시 밖 사업」 — 표의 한 칸(가장 높은 목표 영업이익률 · 가장 이른 시작)을 열마다 펼친 셈과 사례의 근거(독자가 검산할 수 있게)."""
    f = _밖파일(맥)
    if not f or not 종 or not (_n(맥.값("가:밖:틈")) or 0) > 0 or not f.get("마진후보") or not f.get("회전율"):
        return []
    i, j = len(f["마진후보"]) - 1, 0
    if not _n(맥.값("가:밖:필요:%d:%d" % (i, j))):
        return []
    L = ["**표. 공시되지 않은 사업의 기간별 계산(목표 영업이익률 %s · %s부터)**" % (      # 레터 v27 — 표 제목 · 읽는 법은 표 주석
        맥.수("가:밖:마진:%d" % i, "퍼1"), _밖열말(맥, f["시작후보"][j]["열"])), ""]
    줄들 = []
    for k, c in enumerate(f.get("예측열") or []):
        줄들.append([_밖열이름(맥, c)] + [맥.수("가:밖:줄:%d:%d:%d:%s" % (i, j, k, 칸), "금액") for 칸 in ("연간매출", "영업이익", "법인세", "재투자", "FCFF")]
                  + [맥.수("가:밖:줄:%d:%d:%d:현가계수" % (i, j, k), "수4"), 맥.수("가:밖:줄:%d:%d:%d:현가" % (i, j, k), "금액")])
    줄들.append(["영구기간", "—", "—", "—", "—", 맥.수("가:밖:영구:%d:%d:영구FCFF" % (i, j), "금액"), "—", 맥.수("가:밖:영구:%d:%d:영구현가" % (i, j), "금액")])
    L += _표(["기간", "연간 매출", "영업이익", "법인세", "재투자", "FCFF", "현가계수", "현재가치"], 줄들, ["l"] + ["r"] * 7)
    L.append("")
    L.append("매출은 연간 값이고, 잔여 기간은 그 기간에 해당하는 금액만 계산했습니다. 현재가치를 모두 더한 %s 주식 수로 나누면 %s로, 역산 절의 차이와 같습니다." % (
        을(맥.수("가:밖:영구:%d:%d:옵션값" % (i, j), "금액")), 맥.수("가:밖:영구:%d:%d:주당" % (i, j), "주당")))
    L.append("")
    덧 = []
    for k, b in enumerate(f.get("사업") or []):
        s = b.get("사례")
        이름 = _밖이름(맥, b, k)
        if not s or not 이름:
            continue
        덧.append("- %s : 근거 「%s」(%s). 도착 매출 %s — %s(%s). 목표 영업이익률 %s(%s)." % (
            이름, 맥.원고글(b.get("근거문장"), "가격성립.공시밖.사업.%d.근거문장" % k, 부록=True) or "—",
            맥.원고글(b.get("출처"), "가격성립.공시밖.사업.%d.출처" % k, 부록=True) or "—",
            맥.수("가:밖:사례:%d:도착" % k, "금액"),
            맥.원고글(s.get("산정"), "가격성립.공시밖.사업.%d.산정" % k, 부록=True) or "회차 입력",
            맥.원고글(s.get("도착매출출처"), "가격성립.공시밖.사업.%d.도착매출출처" % k, 부록=True) or "—",
            맥.수("가:밖:사례:%d:마진" % k, "퍼1"),
            맥.원고글(s.get("목표마진출처"), "가격성립.공시밖.사업.%d.목표마진출처" % k, 부록=True) or "—"))
    if 덧:
        L += 덧 + [""]
    return L


def _뒤사건(맥, 종):
    """평가기준일 뒤의 사건 — 기준에서 뺀 증설(변형의 범위)과 조합 사례를 표 하나로(R1b · L8). 조합은 주당가치 차례로 싣고 가장 높은
    줄에 그 사실을 적는다. 날짜가 다른 종가 · 굴린 가치(R1a · K7)가 있으면 같은 날끼리 견준 줄을 더한다."""
    가성 = 맥.가성 or {}
    증 = 가성.get("증설") or []
    조 = 가성.get("조합") or []
    같은날 = 날짜종가들(맥)
    if not 증 and not 조 and not 같은날:
        return []
    표, 증값, 조값, 전표 = [], [], [], []
    기준일 = "%s" % (맥.메타.get("평가기준일") or "")
    for i, 입 in enumerate(증):
        키들 = ["가:증설:%d:%d" % (i, j) for j in range(len(입.get("변형") or [{}]))]
        값들 = sorted(키들, key=lambda k: _n(맥.값(k)) or 0)
        lo, hi = 값들[0], 값들[-1]
        공 = ("%s" % (입.get("공표일") or "")).strip()
        전 = bool(공 and 기준일 and 공 <= 기준일)          # 통독 v3 중6 — 기준일 전 공시를 「기준일 뒤의 사건」 에 섞지 않는다
        if not 전:
            증값 += [lo, hi]
        풀 = 입.get("풀손잡이")
        남들 = [_남은차이(맥, 풀, k, 종) for k in 키들]
        (전표 if 전 else 표).append([맥.원고글(입.get("이름"), "가격성립.증설.%d.이름" % i) or "증설", 공 or "—",
                                   _범위글(맥, lo, hi, "주당"), _범위글(맥, ["÷", lo, 종], ["÷", hi, 종], "퍼0"), _남은범위(남들)])
    차례 = sorted(range(len(조)), key=lambda i: _n(맥.값("가:조합:%d" % i)) or 0)
    for n, i in enumerate(차례):
        입 = 조[i]
        키 = "가:조합:%d" % i
        조값.append(키)
        이름 = 맥.원고글(입.get("이름"), "가격성립.조합.%d.이름" % i) or "조합"
        if n == len(차례) - 1 and len(차례) > 1:
            이름 += " (가장 높은 값)"
        표.append([이름, "—", 맥.수(키, "주당"), 맥.식(["÷", 키, 종], "퍼0"), _남은차이(맥, 입.get("풀손잡이"), 키, 종)])
    # 2026-10-26 — 평가기준일 뒤에 발표된 증설이 있을 때만 「평가기준일 뒤의 사건」(날짜 둘 판은 사이 공시가 모두 「전」 이라 조합만 남는다)
    L = ["### 평가기준일 뒤의 사건" if 증값 else "### 기준 시나리오 밖의 사례", ""]
    결 = []
    if 증값:
        lo = min(증값, key=lambda k: _n(맥.값(k)) or 0)
        hi = max(증값, key=lambda k: _n(맥.값(k)) or 0)
        결.append("평가기준일 뒤에 발표된 증설을 반영한 주당가치는 %s(%s 대비 %s)입니다." % (
            _범위글(맥, lo, hi, "주당"), 종가말(맥), _범위글(맥, ["÷", lo, 종], ["÷", hi, 종], "퍼0")))
    if 조값:
        lo = min(조값, key=lambda k: _n(맥.값(k)) or 0)
        hi = max(조값, key=lambda k: _n(맥.값(k)) or 0)
        결.append("낙관적인 가정 여럿을 함께 바꾼 조합의 주당가치는 %s(%s)입니다." % (_범위글(맥, lo, hi, "주당"), _범위글(맥, ["÷", lo, 종], ["÷", hi, 종], "퍼0")))
    if 결:
        L += [" ".join(결), ""]
    if 표:
        L += _표(["사례", "공표일", "주당가치", "%s 대비" % 종가말(맥), "남은 차이를 메울 값"], 표, ["l", "l", "r", "r", "l"])
        L.append("")
    if 전표:
        L.append("**표. 평가기준일 전에 공시됐으나 기준 시나리오에 넣지 않은 사례(같은 계산 방법으로 따로 산정 · 넣지 않은 사유는 부록 %s)**" % 맥.부록글["가격성립"])      # 레터 v27 · 1.1.20 — 표 아래 안내 문장을 표 제목으로
        L.append("")
        L += _표(["기준에서 뺀 것", "공표일", "주당가치", "%s 대비" % 종가말(맥), "남은 차이를 메울 값"], 전표, ["l", "l", "r", "r", "l"])
        L.append("")
    if 같은날:                                                # R1a(K7) — 날짜가 다른 종가와 평가기준일의 값을 그날로 굴린 가치(같은 날끼리)
        for k, (날짜, 종가키, 굴린키) in enumerate(같은날):
            글 = "%s 종가 %s 평가기준일의 값을 그날로 굴린 %s의 %s." % (날짜말(날짜), 은(맥.수(종가키, "주당")), 맥.수(굴린키, "주당"),
                                                       입니다(맥.식(["÷", 종가키, 굴린키], "배")))
            정키 = 종가키.rsplit(":", 1)[0] + ":역산:값"
            try:
                정 = _n(맥.값(정키))
            except (KeyError, IndexError, TypeError):
                정 = None
            if 정 is not None:
                글 += " 이 가격에 해당하는 정상 수준은 %s." % 입니다(맥.수(정키, "지수2"))
            L.append(글)
        L.append("")
    elif 표 and 증값:
        L.append("평가기준일 뒤의 사건을 반영한 주당가치를 %s 비교했습니다. 사건이 알려진 날의 가격과 비교한 값이 아니므로 그 차이를 감안해야 합니다." % 과(종가말(맥)))
        L.append("")
    return L                                                # 1.1.20 — 「증설 사례별 … 근거는 부록 J에 있습니다」(원칙 3)는 지웠다


def _남은범위(글들):
    """「정상 수준 … 지수 1.78」 들 → 같은 손잡이면 「정상 수준 … 지수 1.78~1.89」, 아니면 가운뎃점으로."""
    글들 = list(dict.fromkeys(g for g in 글들 if g))
    if len(글들) <= 1:
        return 글들[0] if 글들 else "—"
    쪽 = [g.rsplit(" ", 1) for g in 글들]
    if all(len(x) == 2 for x in 쪽) and len({x[0] for x in 쪽}) == 1 and all(re.match(r"^[−\-]?[\d.,]+%?$", x[1]) for x in 쪽):
        값 = sorted((x[1] for x in 쪽), key=lambda t: float(t.replace("−", "-").replace(",", "").rstrip("%")))
        return "%s %s~%s" % (쪽[0][0], 값[0], 값[-1])
    return " · ".join(글들)


def _범위글(맥, a, b, 꼴):
    """「1,319,265원~1,347,262원」 — 두 끝이 같으면 하나. a · b 는 키 또는 식."""
    def 찍(k):
        return 맥.식(k, 꼴) if isinstance(k, list) else 맥.수(k, 꼴)
    x, y = 찍(a), 찍(b)
    return x if x == y else "%s~%s" % (x, y)


def 역산세부(맥):
    """부록 J — 「이 가격이 성립하려면 필요한 가정」 의 세부(R1b · L8): 매출 구분별 역산 · 생산능력(설비투자와 짝 · 상한) · 전사 단순 역산의
    셈법 · 기준에서 뺀 증설의 사례별 표 · 조합 사례(주당가치 차례)와 근거 · 가격 위치 격자."""
    종 = 맥.종가키
    if not 종:
        return []
    L = []
    줄들 = _표4줄들(맥)
    단일 = {int(("%s" % r["h"]["대상"][0])[1]) for r in 줄들 if r["갈래"] == "정상단가" and len(r["h"]["대상"]) == 1}
    구분 = _가격성립수준(맥, 단일)
    매출줄 = [r for r in 줄들 if r["갈래"] in ("정상단가", "판매량", "판매량증가율", "판매단가변동률", "연도")]
    if 구분 or 매출줄:
        L += ["### 매출 (매출 구분별)", ""]
        for r in 매출줄:
            눈 = _정상눈금(맥, r)
            if r["내재"] is None:
                L.append(("- %s : 의미 있는 범위 안에서 이 가격이 성립하는 값이 없습니다. %s" % (r["이름"], " ".join(_풀이없는까닭(맥, [r["h"]])))).strip())
            elif 눈:
                L.append(_정상눈금줄(맥, 눈, _비고글(r)))
            else:
                L.append("- %s : %s(채택 %s).%s" % (r["이름"], r["내재"], r["적용"], _비고글(r)))
        L += 구분 + [""]
    전사 = _가격성립전사(맥)
    if 전사:
        L += ["### 매출 (예측기간 매출 증가율 역산)", ""] + 전사
    독 = _독자가격(맥)
    if 독:
        L += ["### 독자가 고른 가격", ""] + 독
    증설 = _가격성립증설(맥, 종)
    if 증설:
        L += ["### 기준에서 뺀 증설과 설비투자", ""] + 증설
    조합 = _가격성립조합(맥, 종)
    if 조합:
        L += ["### 조합 사례", "", "그럴듯하지만 낙관적인 가정 여럿을 함께 바꾼 경우입니다. 주당가치가 낮은 것부터 적었습니다.", ""] + 조합
    밖 = _공시밖세부(맥, 종)
    방 = list(getattr(맥, "_밖방법", None) or [])                 # 1.1.20 — 본편 표 주석에서 옮긴 셈의 방법(본편 표가 선 회차만)
    if 밖 or 방:
        L += ["### 공시 밖 사업", ""] + ([" ".join(방), ""] if 방 else []) + 밖
    L += 레터이야기.격자줄(맥)
    return L


def _가격성립표(맥, 줄들):
    """14절의 표 하나 — 가정마다 이 가격에 필요한 값 · 채택 · 산술(3P test 의 Possible — 성립하지 않으면 엔진 비고와 함께) · 관측 범위
    (제안 2.5 · M5). R1b(L8 · L16) — 매출 구분별 정상 수준 · 생산능력(채택값의 배수 — 「3,755.1천 장」 같은 자릿수 대신) · 전사 단순 역산
    줄을 함께 싣는다."""
    import 레터 as _L                                       # noqa: PLC0415
    if not 줄들:
        return []
    표 = []
    관들 = [_관측칸(맥, r) for r in 줄들]
    열 = ("실적", "Normalization 범위", "세 시나리오") + (("대안 산정 방법",) if any("대안 산정 방법" in x for x in 관들) else ())     # 1.1.7 — 역산판정이 쓴 대안 사양 범위를 표에도(게이트 ⑱ 이 같은 칸을 읽는다)
    for r, 관 in zip(줄들, 관들):
        표.append([r["이름"], r["내재"] if r["내재"] is not None else "—", r["적용"], _산술칸(r)] + [관.get(k, "—") for k in 열])
    단일 = {int(("%s" % r["h"]["대상"][0])[1]) for r in 줄들 if r["갈래"] == "정상단가" and len(r["h"]["대상"]) == 1}
    for x in 맥.구.get("매출구분") or []:
        s = x.get("번호")
        if x.get("경로") != "수준" or not isinstance(s, int) or s >= 6:
            continue
        이름 = _L.구분이름(맥.구, s)
        if x.get("단가경로") == "수렴" and s not in 단일 and _n(_L._시점값(맥.가정, "6%d6" % s, "기준")) is not None:
            if _n(맥.값("가:정상:%d" % s)) is not None:
                표.append(["%s만 %s(정상 수준)" % (이름, _L.구분뗀말(_단가말(x), 이름)), 맥.수("가:정상:%d" % s, "지수2"), 맥.수("S:6%d6:기준" % s, "지수2"),
                          "Possible"] + ["—"] * len(열))
        if x.get("판매량산정") == "능력":
            량 = _L.구분뗀말(("%s" % (x.get("판매량명칭") or "판매량")).strip(), 이름)       # 「<구분> <구분> …」 겹침 막음
            채키 = "R:기준:4.Sales:1%d9:%s" % (s, 맥.끝예측)
            if _n(맥.값("가:능력투자:%d" % s)) is not None:
                표.append(["%s %s(%s 말, 설비투자와 짝)" % (이름, 량, 맥.열말(맥.끝예측)), "채택의 %s" % 맥.식(["÷", "가:능력투자:%d:끝" % s, 채키], "배"),
                          맥.수(채키, "수1"), "Possible"] + ["—"] * len(열))
            if _n(맥.값("가:능력:%d" % s)) is not None:
                표.append(["%s %s(%s 말, 설비투자 없는 상한)" % (이름, 량, 맥.열말(맥.끝예측)), "채택의 %s" % 맥.식(["÷", "가:능력:%d" % s, 채키], "배"),
                          맥.수(채키, "수1"), "Possible"] + ["—"] * len(열))
    L = _표(["가정", "이 가격에 필요한 값", "채택", "산술"] + list(열), 표, ["l", "r", "r", "l"] + ["l"] * len(열))
    L += ["", "가정 하나만 바꾸고 다른 가정은 채택값을 유지한 결과입니다. 「산술」은 그 가정 하나만 바꿔 이 가격과 같은 주당가치를 계산할 수 있는지를 나타냅니다. "
          "실적 · Normalization 범위 · 세 시나리오%s 항목은 그 값이 각 범위 안에 있는지를 나타냅니다." % (" · 할인율 대안 산정 방법" if len(열) > 3 else ""), ""]   # 레터 v27 — 표 주석
    return L


def _산술칸(r):
    """산술로 Possible 인가 — 엔진 역산의 비고(무위험이자율보다 낮음 · 100% 초과 따위)가 있으면 아니다(비고를 함께). 풀이가 없으면 「풀이 없음」."""
    if r["내재"] is None:
        return "풀이 없음"
    if r["비고"]:
        return "Possible 아님 — %s" % r["비고"]
    return "Possible"


def _관측칸(맥, r):
    """관측 범위 칸 — {범위 이름: 「0.70~1.45 밖」} (실적 · Normalization 범위 · 세 시나리오). 범위의 끝 값도 장부에 적는다."""
    if r["내재"] is None:
        return {}
    v = _n(맥.값(r["키"]))
    범위 = _관측범위(맥, r)
    글들 = {}
    for 이름, 쌍, 꼴 in 범위:
        쌍 = [(k, x) for k, x in 쌍 if x is not None]
        if not 쌍 or v is None:
            continue
        lo, hi = min(쌍, key=lambda t: t[1]), max(쌍, key=lambda t: t[1])

        def 찍(k):
            return 맥.식(k, 꼴) if isinstance(k, list) else 맥.수(k, 꼴)
        안 = lo[1] - 1e-9 <= v <= hi[1] + 1e-9
        글들[이름] = "%s %s" % (찍(lo[0]) if abs(hi[1] - lo[1]) < 1e-12 else "%s~%s" % (찍(lo[0]), 찍(hi[0])), "안" if 안 else "밖")
    return 글들


def 대안WACC쌍(맥):
    """할인율 대안 사양(가정 · 레터부록 「자본비용.대안」)의 예측기간 WACC — [(키, 값)]. βU 로 댄 대안은 엔진이 셈한 키(「대안β:<βU>:예측」)."""
    try:
        import 자본비용옮기기 as _자본                          # noqa: PLC0415
        입, _출, _알 = _자본.읽기(맥.가정, 맥.부록)
    except Exception:                                        # noqa: BLE001
        return []
    낸 = []
    for x in ((입 or {}).get("대안") or []) if isinstance(입, dict) else []:
        if not isinstance(x, dict):
            continue
        if _n(x.get("βU")) is not None and _n(x.get("예측기간WACC")) is None:
            k = "대안β:%r:예측" % _n(x["βU"])
        elif _n(x.get("예측기간WACC")) is not None:
            k = "상:%r" % _n(x["예측기간WACC"])
        else:
            continue
        v = _n(맥.값(k))
        if v is not None:
            낸.append((k, v))
    return 낸


def 역산판정(맥, r, v=None):
    """1.1.2 — 역산값(또는 v)이 관측 범위(실적 · Normalization 범위 · 세 시나리오) 가운데 하나라도 안이면 「안」, 범위가 있는데 모두 밖이면 「밖」,
    범위가 없으면 None. 장부에 적지 않는다(판정만)."""
    v = _n(맥.값(r["키"])) if v is None and r.get("내재") is not None else v
    if v is None:
        return None
    든 = 점만 = False
    for _이름, 쌍, _꼴 in _관측범위(맥, r):
        값들 = [x for _k, x in 쌍 if x is not None]
        if not 값들:
            continue
        if max(값들) - min(값들) < 1e-9:                    # 1.1.4(D) — 한 점은 범위가 아니다(세 시나리오가 같은 WACC 면 「범위 없음」 — 대안 사양이 있으면 그 범위로)
            점만 = True
            continue
        든 = True
        if min(값들) - 1e-9 <= v <= max(값들) + 1e-9:
            return "안"
    return "밖" if 든 else ("범위없음" if 점만 else None)


def _관측범위(맥, r):
    """역산 줄의 관측 범위 — [(이름, [(키 또는 식, 값)], 꼴)] (실적 · Normalization 범위 · 세 시나리오)."""
    import 레터 as _L                                       # noqa: PLC0415
    g = r["갈래"]
    대상 = "%s" % (r["h"]["대상"] or [""])[0]
    범위 = []                                               # [(이름, [(키 또는 식, 값)], 꼴)]
    D = "R:%s:2.DCF:%s"
    if g.startswith("WACC"):
        쌍 = [("R:%s:WACC:예측기간:WACC" % s, _n(맥.값("R:%s:WACC:예측기간:WACC" % s))) for s in 시나리오들]
        범위.append(("세 시나리오", 쌍, "퍼2"))
        if len({round(v, 9) for _k, v in 쌍 if v is not None}) <= 1:     # 1.1.4(D) — 세 시나리오의 WACC 가 한 점이면 대안 사양(βU · WACC 대안)의 WACC 를 범위로
            대 = 대안WACC쌍(맥)
            if 대:
                범위.append(("대안 산정 방법", 쌍[1:2] + 대, "퍼2"))        # 레터 v27 — 「대안 사양」 → 「대안 산정 방법」(표 머리 · 레터정합 역산범위밖이 같은 머리를 읽는다)
    elif g in ("영구이익률가감", "Normalization"):
        실 = []
        for c in 연간실적열(맥):                               # 1.1.20 — 반기 · 분기 실적 열은 범위 잣대에 넣지 않는다(11절 · 표의 실적 범위와 같은 회계연도 기준)
            식 = ["÷", D % ("기준", "15") + ":" + c, D % ("기준", "11") + ":" + c]
            값 = 맥.식값(식)
            if 값 is not None:
                실.append((식, 값))
        if 실:
            범위.append(("실적", 실, "퍼1"))
        if _n(_L._시점값(맥.가정, "950", "기준")) is not None and _n(_L._시점값(맥.가정, "951", "기준")) is not None:
            범위.append(("Normalization 범위", [("S:950:기준", _n(맥.값("S:950:기준"))), ("S:951:기준", _n(맥.값("S:951:기준")))], "퍼1"))
        범위.append(("세 시나리오", [(D % (s, "42"), _n(맥.값(D % (s, "42")))) for s in 시나리오들], "퍼1"))
    elif 대상.isdigit() and 대상 in (맥.가정.get("시점가정") or {}):
        범위.append(("세 시나리오", [("S:%s:%s" % (대상, s), _n(_L._시점값(맥.가정, 대상, s))) for s in 시나리오들
                                 if _n(_L._시점값(맥.가정, 대상, s)) is not None], r["꼴"]))
    elif 대상.isdigit() and 대상 in (맥.가정.get("가정") or {}) and 맥.끝예측:
        범위.append(("세 시나리오", [("A:%s:%s:%s" % (대상, s, 맥.끝예측), _n(_L._가정값(맥.가정, 대상, s, 맥.끝예측))) for s in 시나리오들
                                 if _n(_L._가정값(맥.가정, 대상, s, 맥.끝예측)) is not None], r["꼴"]))
    elif 대상 == "비영업할인":                                # 1.1.2 — 뜻 범위(장부의 0~100% 를 깎는다)
        범위.append(("뜻 범위", [("상:0", 0.0), ("상:1", 1.0)], r["꼴"]))
    return 범위


def _풀이없는까닭(맥, 손들=None):
    """역산의 풀이가 없는 손잡이마다 그 까닭 한 문장 — 엔진의 막는 조건(영구성장률 < 영구기간 WACC · 영업이익 ≤ 매출액)과
    영구기간 ROIC = WACC 일 때 영구성장률이 영구가치를 거의 움직이지 않는다는 사실."""
    D = 맥.기["2.DCF"]
    낸 = []
    for h in (손들 if 손들 is not None else getattr(맥, "역산없음손잡이", [])):
        갈래, _대 = _손잡이갈래(h)
        까 = _역산까닭(맥, h)
        # 1.1.21 — 막는 조건의 문장은 엔진이 그 조건에 막혀 풀이를 못 냈을 때(까닭 「막힘」)만 싣는다. 범위 밖 · 계산 실패에도 「영구성장률은 영구기간 WACC
        # 값보다 낮아야 합니다」 가 서서 풀이가 없는 까닭이 아닌 말이 됐다(서른 곳 — 종가가 기준보다 낮아 g 를 내려야 하는 판)
        if 갈래 == "영구성장률":
            같음 = _n(D.get("48")) is not None and _n(D.get("46")) is not None and abs(_n(D.get("48")) - _n(D.get("46"))) < 1e-9
            if 같음 or 까 == "값중립":
                낸.append("영구기간 ROIC이 WACC 값과 같아 영구성장률을 바꿔도 Terminal Value가 거의 달라지지 않습니다.")
            elif 까 == "막힘":
                낸.append("영구성장률은 영구기간 WACC 값보다 낮아야 합니다.")
        elif 갈래 in ("영구이익률가감", "Normalization"):
            if 까 == "막힘":
                낸.append("영업이익은 매출액보다 클 수 없습니다.")
        elif 갈래.startswith("WACC"):
            if 까 == "막힘":
                낸.append("WACC 값은 영구성장률보다 높아야 합니다.")
    return list(dict.fromkeys(낸))


def _역산까닭(맥, h):
    """표 Ⅳ 줄의 풀이 없는 까닭(엔진 `역산까닭` — 값중립 · 막힘 · 범위밖 · 계산실패) — 이름 · 대상이 같은 줄에서. 없으면 None."""
    for r in ((getattr(맥, "민", None) or {}).get("표4") or {}).get("줄") or []:
        if r.get("이름") == h.get("이름") and r.get("대상") == h.get("대상"):
            return r.get("까닭")
    return None


def 다른할인시점글(맥, 시점):
    """「 Terminal Value를 {시점} 시점 기준으로 할인하면 주당가치는 x% 높아집니다 · 낮아집니다.」 — 엔진 요약 「다른할인시점차」(다른 시점 ÷ 채택 − 1)의
    부호로 방향을 낱말로 쓴다(1.1.19 — 종전 「x% 달라집니다」 는 방향이 없었다 · 레터 원칙 6 부호 대신 낱말). 반올림해 0 이면 「거의 같습니다」. 값이 없으면 ""."""
    키 = "R:기준:요약:다른할인시점차"
    v = _n(맥.값(키))
    if v is None:
        return ""
    크 = 맥.수(키, "폭1")
    if not _n(re.sub(r"[^0-9.]", "", 크)):
        return " Terminal Value를 %s 시점 기준으로 할인해도 주당가치는 거의 같습니다(차이 %s)." % (시점, 크)
    return " Terminal Value를 %s 시점 기준으로 할인하면 주당가치는 %s %s." % (시점, 크, "높아집니다" if v > 0 else "낮아집니다")


def 마감날말(맥, 일시):
    """마감 일시 → 「2026년 11월 11일」 — 장부를 거친 엔진 글(키 「주:날말:<날짜>」 · 다른 날짜 문장과 같은 꼴)로 적는다(1.1.20 — ADDER80 1.1.19 재짓기:
    날짜를 글자로만 찍어 게이트 ⑦ 「장부에 없는 숫자 「11일」」 로 막혔다 · 다른 날짜는 우연히 장부에 같은 숫자가 있어 지나갔다).
    날짜 꼴이 아니면 날짜말 그대로(장부에 적을 것이 없다). 장부가 없는 맥(시험의 가짜 맥)도 날짜말."""
    m = re.match(r"^\s*(\d{4}-\d{1,2}-\d{1,2})", "%s" % (일시 or ""))
    엔 = getattr(맥, "엔진글", None)
    if m and callable(엔):
        d = "%s-%02d-%02d" % tuple(int(x) for x in m.group(1).split("-"))
        글 = 엔("주:날말:%s" % d)
        if 글:
            return 글
    return 날짜말(일시)


def 마감옛값(맥):
    """워크북 마감 기록이 지금 가정과 다른 값의 판인가 — True(다름) · False(같음) · None(볼 거리 없음).
    게이트 ⑥ 과 같은 셈이다 — 마감 기록에 값 해시가 있으면 값 해시(글 블록만 바뀐 판은 같은 값), 없으면(옛 기록) 전체 해시로 맞댄다."""
    마 = getattr(맥, "마감", None)
    가 = getattr(맥, "가정", None)
    if not isinstance(마, dict) or not isinstance(가, dict):
        return None
    기 = 마.get("가정") or {}
    try:
        if 기.get("값해시"):
            import 가정해시 as _가해                          # noqa: PLC0415
            return 기["값해시"] != _가해.값(가)
        if 기.get("해시"):
            import 레터 as _L                               # noqa: PLC0415
            return 기["해시"] != _L._해시(가)
    except Exception:                                        # noqa: BLE001 — 해시를 못 재면 시점 문장을 싣지 않는다(게이트 ⑥ 이 따로 본다)
        return None
    return None


def 가정점검항목(자):
    """자체검사 결과(`레터.자체검사돌리기`) → (오류가 난 항목 이름들, 검토가 필요한 항목 이름들). 부록 E 의 가정 점검 표와 같은 이름 · 같은 셈이다
    (이름은 `레터._점검이름` · 경보는 「방향 미선언」 을 뺀다 · 죽은 검사는 오류)."""
    import 레터 as _L                                       # noqa: PLC0415
    오, 경 = [], []
    for x in (자.get("검사") or []) if isinstance(자, dict) else []:
        if not isinstance(x, dict):
            continue
        이름 = _L._점검이름(x.get("이름") or "")
        if not 이름:
            continue
        if x.get("오류") or x.get("죽음"):
            오.append(이름)
        elif [y for y in (x.get("경보") or []) if not ("%s" % y).strip().startswith("방향 미선언")]:
            경.append(이름)
    return 오, 경


def _항목글(머리, 이름들, 상한=110, 부록=True):
    """「{머리} 「A」 · 「B」입니다(부록 E).」 — 문장이 상한(자)을 넘으면 앞 이름까지만 싣고 「「A」 등 N개 항목」(⑬ 120자 · 이름 전부는 부록 E 표에 있다).
    부록=False 면 「(부록 E)」 를 붙이지 않는다(이어지는 다음 문장이 붙인다)."""
    실은 = []
    for 이름 in 이름들:
        후보 = 실은 + ["「%s」" % 이름]
        if 실은 and len("%s %s 등 %d개 항목입니다(부록 E)." % (머리, " · ".join(후보), len(이름들))) > 상한:
            break
        실은 = 후보
    남 = len(이름들) - len(실은)
    return "%s %s%s." % (머리, 입니다(" · ".join(실은) + ((" 등 %d개 항목" % len(이름들)) if 남 else "")), "(부록 E)" if 부록 else "")


def 가정점검건(자):
    """자체검사 결과 → ([(오류 항목 이름, 건수)], [(검토 필요 항목 이름, 건수)]) — `가정점검항목` 과 같은 이름 · 같은 거름(방향 미선언 뺌 · 죽은 검사는 오류 1건)."""
    import 레터 as _L                                       # noqa: PLC0415
    오, 경 = [], []
    for x in (자.get("검사") or []) if isinstance(자, dict) else []:
        if not isinstance(x, dict):
            continue
        이름 = _L._점검이름(x.get("이름") or "")
        if not 이름:
            continue
        if x.get("오류") or x.get("죽음"):
            오.append((이름, max(len(x.get("오류") or []), 1)))
            continue
        k = len([y for y in (x.get("경보") or []) if not ("%s" % y).strip().startswith("방향 미선언")])
        if k:
            경.append((이름, k))
    return 오, 경


def 가정점검표(자, 시트있음=True):
    """18절의 가정 점검 결과 — 표(1.1.21 — 종전 문단은 도구 낱말 「가정 파일」 을 쓰고, 「오류 2건」 인데 항목을 하나만 불러 독자가 남은 하나를 찾았다).
    줄 = 오류 · 검토 필요 건수, 그다음 항목마다 이름과 건수(빠짐없이). 항목별 건수의 합이 머리 건수와 다르면 건수 없이 「오류」 · 「검토 필요」 만."""
    오n, 경n = int(자.get("오류수") or 0), int(자.get("경보수") or 0)
    오, 경 = 가정점검건(자)
    줄들 = [["오류", "%d건" % 오n], ["검토 필요", "%d건" % 경n]]
    오합, 경합 = sum(k for _i, k in 오) == 오n, sum(k for _i, k in 경) == 경n
    if 오n:
        줄들 += [[이름, ("오류 %d건" % k) if 오합 else "오류"] for 이름, k in 오]
    if 경n:
        줄들 += [[이름, ("검토 필요 %d건" % k) if 경합 else "검토 필요"] for 이름, k in 경]
    머 = ("위 검증과 별도로, 평가 모델 없이 가정만 읽어 돌린 점검" if 시트있음 else "평가 모델 없이 가정만 읽어 돌린 점검")
    return ["**표. 가정 점검 결과(%s)**" % 머, ""] + _표(["점검", "결과"], 줄들, ["l", "l"]) + [""]


def 점검절(맥, 번):
    L = ["## %d. 모델 점검" % 번, ""]
    마 = 맥.마감
    대n, 대p = 맥.대조 if isinstance(맥.대조, tuple) else (None, None)
    if isinstance(마, dict):
        점 = 마.get("모델점검") or []
        셈 = {"정합성": 0, "완결성": 0, "검토사항": 0}
        의견 = 0
        for x in 점:
            if any((x.get("판정") or {}).get(s) in (1, 1.0) for s in 시나리오들):
                셈[x.get("구분")] = 셈.get(x.get("구분"), 0) + 1
                if ("%s" % (x.get("의견") or "")).strip():
                    의견 += 1
        도 = 마.get("도구점검") or {}
        일치 = (도.get("I-53") or {}).get("판정")
        L.append("평가 모델(엑셀)을 마감하면서 세 시나리오를 다시 계산하고, 모델의 계산 결과를 모두 이 레터의 계산과 대조했습니다(%s). "
                 "검증 결과는 정합성 오류 %d건, 완결성 미비 %d건, 검토사항 %d건이며, 검토사항 %d건에는 검토 의견을 적었습니다(부록 E)."
                 % ("불일치 없음" if 일치 == 0 else "대조 결과는 부록 E", 셈["정합성"], 셈["완결성"], 셈["검토사항"], 의견))
    else:
        L.append("평가 모델(엑셀)의 마감 결과는 이 레터에 싣지 않았습니다.")
    if 대n is not None:
        L.append("별도로 수행한 대조에서도 불일치는 %d곳입니다." % 대n)
    if 마감옛값(맥):                                           # 1.1.19 — 엑셀 단계를 다시 돌지 않은 회차: 위 결과의 시점을 밝힌다(가정 점검은 지금 가정으로 다시 돈다)
        # 1.1.21 — 도구 낱말(「가정 파일」) 없이, 그 뒤 바뀐 가정이 이 검증에 들지 않는다는 사실로(ADDER80 백테스트 맥 읽기)
        L.append("위 검증 결과는 %s 평가 모델 마감 기준이며, 그 뒤 바뀐 가정 값은 이 검증에 들어 있지 않습니다." % 마감날말(맥, 마.get("일시")))
        맥.알림.append("18절 — 워크북 마감 기록(%s)이 지금 가정과 다른 값의 판이다 — 마감을 다시 돌린다(게이트 ⑥)" % (마.get("일시") or "일시 없음"))
    L.append("")
    자 = 맥.자체
    if isinstance(자, dict):
        L += 가정점검표(자, 시트있음=isinstance(마, dict))
    장 = 맥.모순
    if isinstance(장, dict) and 장.get("항목"):
        항 = [x for x in 장["항목"] if isinstance(x, dict)]
        미 = [x for x in 항 if x.get("상태") != "해소"]
        L.append(("자료 간 불일치는 %d건을 확인했고, 그 가운데 %d건은 해소하지 못했습니다(부록 H)." % (len(항), len(미))) if 미 else
                 "자료 간 불일치 %d건은 모두 해소했습니다(부록 H)." % len(항))
        L.append("")
    return L


고지표지 = ("<!-- 고지 -->", "<!-- /고지 -->")                # `레터3분.고지표지` 와 같은 표지 — 구조 검사 ④(닮음)가 표지 안의 고정 문장(정의 · 고지)을 빼고 잰다


def 고지싸기(줄들):
    """1.1.20 — 정의 · 고지 문단(원칙 12 가 허용한 고정 문장)을 고지 표지로 싼다. 빈 목록이면 빈 목록."""
    줄들 = list(줄들 or [])
    while 줄들 and 줄들[-1] == "":
        줄들.pop()
    return ([고지표지[0], ""] + 줄들 + ["", 고지표지[1], ""]) if 줄들 else []


def 한계절(맥, 번):
    """평가의 한계 — 한계 목록은 고지(평가의 전제)라 고지 표지 안에 둔다(1.1.20)."""
    return ["## %d. 평가의 한계" % 번, ""] + 고지싸기(한계목록(맥))


def 한계목록(맥):
    L = []
    L.append("- 현금 및 단기금융자산은 전액 비영업자산으로 보았습니다. 영업에 필요한 최소 현금을 차감하지 않았으므로 주주가치는 그 금액만큼 높게 산정됐습니다.")
    우 = (맥.가정.get("관측") or {}).get("우발부채")
    확인 = isinstance(우, dict) and (우.get("확인") is True or ("%s" % (우.get("확인") or "")).strip() in ("예", "확인"))
    if 확인:
        사유 = 맥.원고글(우.get("사유"), "관측.우발부채.사유")
        L.append("- 재무상태표에 계상되지 않은 우발부채 · 지급보증 · 소송은 주석에서 확인했습니다.%s" % ((" " + 사유) if 사유 else ""))
    else:                                                   # 원고 요건(관측.우발부채)이 비면 초안이 서지 않는다 — 여기 오는 것은 저자가 「확인 아니오」 와 사유를 적은 판
        사유 = 맥.원고글(우.get("사유"), "관측.우발부채.사유") if isinstance(우, dict) else ""
        L.append("- 재무상태표에 계상되지 않은 우발부채 · 지급보증 · 소송은 이 평가에 반영하지 않았고, 주석에서 그 규모를 확인하지 않았습니다.%s" % ((" " + 사유) if 사유 else ""))
    뒤 = (맥.부록 or {}).get("기준일뒤자료")
    if isinstance(뒤, list) and 뒤:
        L.append("- %s에 공표된 자료를 참고한 가정이 있습니다(부록 G)." % importlib.import_module("기준일").자료경계(맥.가정)["말"])     # 1.1.20 — 안내 문장(원칙 3)을 괄호로
    if 레터이야기.글자리들(맥.가정, 맥.가성):
        L.append("- " + 이야기숫자자리)
    L.append("- 주당가치는 이 레터에 적은 가정을 전제로 한 값입니다. 가정을 바꾸면 주당가치도 달라집니다.")
    L.append("")
    return L


이야기숫자자리 = "⟦Narrative 숫자 검수⟧"


def 파일절(맥, 번):
    L = ["## %d. 평가 모델 파일" % 번, ""]
    엑 = 맥.엑셀
    옛 = bool(마감옛값(맥))                                   # 1.1.21 — 18절이 「그 뒤 바뀐 가정 값은 이 검증에 들어 있지 않습니다」 를 쓴 판에서는 「최종본」 · 「점검을 마친 가정」 을 쓰지 않는다
    if 엑 and os.path.isfile(엑):
        같음, _말, 해시 = getattr(맥, "모델", (None, "", None))
        L.append("이 레터의 숫자를 계산한 평가 모델(엑셀, %s)을 함께 보관합니다.%s 가정을 바꿔 가며 확인하려면 이 파일을 별도로 전달받아야 합니다."
                 % (os.path.basename(엑), (" 이 파일은 모델 점검(%d절)을 마친 최종본입니다(버전 표시는 부록 E)." % 맥.절["점검"]) if 같음 and not 옛 else ""))
    else:
        L.append("이 레터의 숫자를 계산한 평가 모델(엑셀)은 따로 전달할 수 있습니다.")
    # 1.1.21 — 「바꿔 볼 가정은 …」 는 17절(`레터이야기` — 지렛대 가정)과 같은 문장이었다(서른 곳 · 회사와 무관한 고정 목록) — 17절 한 자리에만 둔다
    if 레터이야기.손잡이목록(맥):
        L.append("평가 모델의 가정 시트에서 가정을 바꾸면 주당가치가 다시 계산됩니다.")
    if not 옛 and not (엑 and os.path.isfile(엑) and getattr(맥, "모델", (None,))[0]):     # 1.1.20 — 「최종본입니다(버전 표시는 부록 E)」 가 이미 섰으면 같은 뜻을 되풀이하지 않는다
        L.append("이 레터의 숫자는 모델 점검을 마친 가정으로 계산했습니다(버전 표시는 부록 E).")    # 2026-11-01 — 해시는 독자 본편에 두지 않는다(게이트 ⑳)
    L.append("")
    return L[:2] + 고지싸기(L[2:])                            # 1.1.20 — 평가 모델 파일의 안내는 고지라 고지 표지 안에(구조 검사 ④ 가 빼고 잰다)


# ══════════════════════════════════════════════════════════════════ 쓰기

def 쓰기(맥):
    """본문 줄 목록 — 2026-10-16 결정: 머리 · 3분 레터(별도 요약본) · 본편(모델을 세운 순서 = 추론의 사슬, `레터본문.쓰기`).
    다섯 막 짜임(R1c — `레터막.쓰기`)은 폐기했다(함수는 남겨 본편의 절이 그 조각을 쓴다). 옛 짜임(R1b 까지)은 `옛쓰기`."""
    import 레터본문                                          # noqa: PLC0415
    return 레터본문.쓰기(맥)


def 옛쓰기(맥):
    """R1b 까지의 짜임 — 머리 · 3분 레터(R1b · L1) · 본편 머리와 목차(L4) · 본문 절. 절 번호는 선 절의 차례대로 매긴다."""
    import 레터 as _L                                       # noqa: PLC0415
    import 레터3분                                           # noqa: PLC0415
    종가 = _n((맥.민.get("표4") or {}).get("종가"))
    맥.종가키 = "민:표4:종가" if 종가 and 종가 > 0 else None          # 역산이 쓴 종가(13번 99 · 평가기준일 열)
    절들 = [("요약", 요약절)]
    맥.개요 = 개요문단(맥)
    N = 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}
    이야기 = bool(맥.개요 or any(("%s" % (N.get(k) or "")).strip() for k in ("정체성", "구성", "우위", "그러나"))
               or isinstance((맥.메타 or {}).get("생애주기"), dict) or 맥.가정.get("서사연결"))
    if 맥.원.get("지난") is not None:
        절들.append(("다리", 레터이야기.다리절))
    절들.append(("실적", 실적절))
    if 이야기:
        절들.append(("Narrative", 레터이야기.Narrative절))
    절들 += [("방법", 방법절), ("매출", 매출절), ("비용", 비용절), ("재투자", 재투자절), ("세금", 세금절),
           ("할인율", 할인율절), ("영구", 영구절), ("주주가치", 주주가치절), ("시나리오", 시나리오절), ("민감도", 민감도절)]
    if 맥.종가키:
        절들.append(("역산", 역산절))
    if 레터이야기.신호들(맥):
        절들.append(("이야기점검", 레터이야기.이야기점검절))
    if 이야기 or isinstance((맥.메타 or {}).get("이해관계"), dict):
        절들.append(("자리", 레터이야기.자리절))
    절들 += [("점검", 점검절), ("한계", 한계절), ("파일", 파일절)]
    맥.절 = {k: i + 1 for i, (k, _f) in enumerate(절들)}
    L = _머리(맥)
    L += 레터3분.쓰기(맥)                                    # R1b(L1) — 2쪽 3분 레터를 맨 앞에
    본 = []
    제목들 = []
    for 키, f in 절들:
        줄 = f(맥, 맥.절[키])
        if 키 in ("매출", "비용", "재투자", "세금", "할인율", "영구", "주주가치"):
            줄 = 줄[:2] + 레터이야기.절머리(맥, 키) + 줄[2:]             # 추정 절 머리 — 이 절이 담은 Narrative(제안 2.3)
        제목들.append(줄[0][3:].strip() if 줄 and 줄[0].startswith("## ") else "%d." % 맥.절[키])
        본 += 줄
    L += [_L.본편머리, ""]
    L.append("아래는 이 평가의 본편입니다. 절마다 값이 어떻게 나왔는지와 그 근거를 적었습니다.")
    L.append("")
    L += ["- [%s](#s%d)" % (t, 맥.절[k]) for (k, _f), t in zip(절들, 제목들)] + ["- [부록](#부록)", ""]
    L += 본
    return L


def _격자이름(맥, 이름):
    """R1a 격자 축의 이름 — 판매단가 명칭이 하나면 「판매단가」 를 그 명칭으로(L5), 기호 괄호(「(g)」 · 「(RONIC)」)는 걷는다."""
    import 레터 as _L                                       # noqa: PLC0415
    수렴 = [x for x in 맥.구.get("매출구분") or [] if x.get("단가경로") in ("수렴", "연동")]
    명 = 수렴명칭(맥, 수렴) if 수렴 else "판매단가 지수"
    글 = _L._단가바꿈("%s" % (이름 or ""), None if 명 == "판매단가 지수" else 명)
    return 레터이야기.이름다듬기(글)


def _격자꼴(이름, 기본):
    """R1a 격자 축의 꼴 — 이름으로(연도 · 비율 · 지수)."""
    t = "%s" % (이름 or "")
    if "연도" in t or "고점 구간" in t or "고원" in t:      # 고원 — 옛 이름
        return "연도"
    if any(k in t for k in ("ROIC", "성장률", "WACC", "이익률", "유지율", "가동률")):
        return "퍼1"
    return 기본


def 날짜종가들(맥):
    """R1a(K7) — 평가기준일 밖의 종가와 그날로 굴린 가치 — [(날짜, 종가 키, 굴린 주당가치 키)]. 엔진이 표 Ⅳ 곁에 「날짜종가」
    목록({날짜, 종가, 굴린주당})을 내면 읽는다. 지금 엔진에는 없다 → 빈 목록(그 줄과 「평가기준일 뒤의 사건」 의 같은 날 비교를 세우지 않는다)."""
    목록 = (맥.민 or {}).get("날짜가격")                    # R1a(K7) — 가정 파일 `역산.가격` 의 날마다 굴린 값 · 되굴린 목표 · 역산
    낸 = []
    for k, x in enumerate(목록 or []):
        if isinstance(x, dict) and _n(x.get("종가")) and _n(x.get("굴린주당")) and x.get("날짜"):
            낸.append((x["날짜"], "민:날짜가격:%d:종가" % k, "민:날짜가격:%d:굴린주당" % k))
    return 낸


# ══════════════════════════════════════════════════════════════════ 찾기 — 게이트와 같은 탐색

def 대조찾기(회차, 지정=None):
    """대조 결과의 「어긋난 자리 N곳」 → (N 또는 None, 파일 경로 또는 None). 레터와 레터게이트 ⑤ 가 같은 탐색을 쓴다.
    후보: `지정` 파일 하나, 없으면 회차 `_raw` 와 `_raw/*/` 의 `대조*.txt` · `_대조*.txt`(`도구대조` 제외). 최근 것부터."""
    import glob as _glob
    if 지정:
        후보 = [지정]
    else:
        r = os.path.join(회차 or "", "_raw")
        폴더 = ([r] + [os.path.join(r, d) for d in os.listdir(r) if os.path.isdir(os.path.join(r, d))]) if (회차 and os.path.isdir(r)) else []
        후보 = [p for d in 폴더 for 꼴 in ("대조*.txt", "_대조*.txt") for p in _glob.glob(os.path.join(d, 꼴))
              if os.path.isfile(p) and "도구" not in os.path.basename(p)]
        후보 = sorted(set(후보), key=lambda p: (-round(os.path.getmtime(p)), os.path.basename(p).startswith("_"), p))
    for p in 후보:
        try:
            m = re.findall(r"어긋난 자리 (\d+)곳", io.open(p, encoding="utf-8", errors="ignore").read())
        except Exception:                                    # noqa: BLE001
            m = []
        if m:
            return int(m[-1]), p
    return None, None


def 장부읽기(경로):
    """회차의 `_raw/모순장부.json` 항목 목록(없으면 None)."""
    if not 경로:
        return None
    p = os.path.join(os.path.dirname(os.path.abspath(경로)), "_raw", "모순장부.json")
    if not os.path.exists(p):
        return None
    try:
        return json.load(io.open(p, encoding="utf-8")).get("항목") or []
    except Exception:                                        # noqa: BLE001
        return None


# ══════════════════════════════════════════════════════════════════ 1.1.2 — 역산 넓힘 · 보수성 점검 · 반대 논거
# 가정 하나로 푼 역산값이 실적 · 정상화 · 시나리오 범위 밖이면 그 값은 「그 가정 하나로는 설명되지 않는다」 는 뜻이다. 첫 장에는 그 값을 싣지 않고
# (게이트 정합 「3분 범위 밖 역산값」), 범위 끝에 한 가정을 두고 둘째 가정을 다시 푼 조합(두 변수 동시 역산 — 장부 키 「역둘:i:j:v」)을 싣는다.
# 평가값과 종가의 차이가 문턱(정합설정 「반대논거.문턱」)을 넘으면 보수성 점검표(민감도 표의 폭 끝 중 종가 쪽)와 반대 논거(원고 `Narrative.반대논거`
# — 논거 · 근거 · 바꾸는 가정 · 값, 주당가치는 레터가 엔진으로 셈한다 — 장부 키 「반:i」)를 싣는다.

def _정합설정():
    try:
        import 레터정합 as _J                                 # noqa: PLC0415
        return _J.설정()
    except Exception:                                        # noqa: BLE001
        return {}


def 종가괴리(맥):
    """(기준 주당가치 − 종가) ÷ 종가 — 종가가 없으면 None."""
    if not getattr(맥, "종가키", None):
        return None
    p, v = _n(맥.값(맥.종가키)), _n(맥.값("R:기준:2.DCF:68"))
    return (v - p) / p if p and v is not None else None


def 반대논거필요(맥):
    """평가값과 종가의 차이(종가 대비 절댓값)가 문턱을 넘나."""
    g = 종가괴리(맥)
    문 = float(((_정합설정().get("반대논거") or {}).get("문턱")) or 0.30)
    return g is not None and abs(g) > 문


def _범위끝들(맥, r):
    """역산 줄의 관측 범위 끝 [(키 또는 식, 값, 꼴)] — 범위가 여럿이면 모두의 합집합 끝 둘."""
    쌍 = [(k, x, 꼴) for _이름, 목, 꼴 in _관측범위(맥, r) for k, x in 목 if x is not None]
    if not 쌍:
        return []
    lo = min(쌍, key=lambda t: t[1])
    hi = max(쌍, key=lambda t: t[1])
    return [lo] if abs(hi[1] - lo[1]) < 1e-12 else [lo, hi]


def 두변수(맥):
    """두 변수 동시 역산 → [{"A", "B", "끝", "v1", "키", "v2", "판정"}] (맥에 한 번 셈해 둔다). A = 풀이가 범위 밖이거나 풀이가 없는 축(가감 공간 축 제외),
    B = 범위가 있는 다른 축. A 는 범위 끝 가운데 이 가격 쪽(풀이가 있으면 그 값에 가까운 끝 · 없으면 엔진의 닿는 끝에 가까운 끝)에 둔다."""
    if hasattr(맥, "_두변수"):
        return 맥._두변수
    맥._두변수 = []
    if not getattr(맥, "종가키", None) or not 맥.민 or not (맥.민.get("표4") or {}).get("종가"):
        return 맥._두변수
    줄들 = [r for r in _표4줄들(맥) if ("%s" % (r["h"]["대상"] or [""])[0]) not in ("매출성장", "목표마진")]
    원줄 = 맥.민["표4"]["줄"]
    A들 = []
    for r in 줄들:
        if r["내재"] is not None and 역산판정(맥, r) in ("밖", "범위없음"):
            A들.append(r)
        elif r["내재"] is None and (원줄[r["i"]].get("까닭") == "범위밖") and _범위끝들(맥, r):
            A들.append(r)
    _민 = importlib.import_module("엔진.민감도")
    if _민.브리지역산필수(맥.가정):                          # 비영업 몫이 크면 브리지 축을 먼저 범위 끝에 둔다(시장의 교차 보유 할인을 먼저 걷는다)
        A들.sort(key=lambda r: 0 if ("%s" % (r["h"]["대상"] or [""])[0]) == "비영업할인" else 1)
    낸 = []
    for A in A들[:3]:
        끝들 = _범위끝들(맥, A)
        if not 끝들:
            continue
        if A["내재"] is not None:
            기준 = _n(맥.값(A["키"]))
        else:
            닿 = 원줄[A["i"]].get("닿는끝") or {}
            기준 = _n(닿.get("값"))
        끝 = min(끝들, key=lambda t: abs(t[1] - 기준)) if 기준 is not None else 끝들[-1]
        if _채택과같은끝(맥, A, 끝):                         # 1.1.19 — 범위 끝이 채택값이면 A 는 그대로라 조합이 아니라 B 하나의 역산이다(한 변수 결론이 판정한다)
            continue
        짝 = 0
        for B in 줄들:
            if B is A or not _관측범위(맥, B) or len(낸) >= 6 or 짝 >= 2 or B in A들[:A들.index(A)]:
                continue
            짝 += 1
            키 = "역둘:%d:%d:%r" % (A["i"], B["i"], float(끝[1]))
            v2 = _n(맥.값(키))
            낸.append({"A": A, "B": B, "끝": 끝, "v1": 끝[1], "키": 키, "v2": v2,
                      "판정": 역산판정(맥, B, v2) if v2 is not None else None})
    맥._두변수 = 낸
    return 낸


def _채택과같은끝(맥, A, 끝):
    """두 변수 역산에서 A 를 둘 범위 끝이 A 의 채택값과 같은가(값이 같거나 같은 꼴로 찍은 글이 같으면 같다 — 독자에게는 같은 값이다).
    같으면 A 는 움직이지 않으므로 그 줄은 「두 가정을 함께」 가 아니라 B 하나만 푼 역산이다 — 한 변수 역산 표와 결론이 이미 다른 잣대로 판정한 값을
    「범위 안」 으로 다시 판정하지 않게 그 줄을 세우지 않는다(1.1.19 — 영구성장률 2.00%(채택 · 범위 끝) · WACC 5.73% 「범위 안」 대 한 변수 결론 「범위를 넘습니다」)."""
    import 레터 as _L                                       # noqa: PLC0415
    적 = _n(맥.값(A["적키"]))
    v = _n(끝[1])
    if 적 is None or v is None:
        return False
    if abs(v - 적) <= 1e-9 * max(1.0, abs(적)):
        return True
    try:
        return _L.꼴글(v, 끝[2], 맥.메타) == _L.꼴글(적, 끝[2], 맥.메타)
    except Exception:                                        # noqa: BLE001
        return False


def 두변수안(맥):
    """범위 안에서 선 두 변수 조합(첫째) — 없으면 None."""
    return next((x for x in 두변수(맥) if x["판정"] == "안"), None)


def _끝글(맥, 끝):
    k, _v, 꼴 = 끝
    return 맥.식(k, 꼴) if isinstance(k, list) else 맥.수(k, 꼴)


def _역범위글(맥, r):
    끝들 = _범위끝들(맥, r)
    if not 끝들:
        return "—"
    return " ~ ".join(_끝글(맥, e) for e in 끝들) if len(끝들) > 1 else _끝글(맥, 끝들[0])


def 두변수절(맥):
    줄 = 두변수(맥)
    if not 줄:
        return []
    표 = []
    for x in 줄:
        A, B = x["A"], x["B"]
        표.append([A["이름"], _끝글(맥, x["끝"]), B["이름"], 맥.수(x["키"], B["꼴"]) if x["v2"] is not None else "풀이 없음", _역범위글(맥, B),
                  {"안": "범위 안", "밖": "범위 밖", "범위없음": "범위 없음"}.get(x["판정"], "—")])     # 1.1.4(D) — 한 점뿐인 범위는 「범위 없음」
    # 1.1.20 — 머리의 일반 규칙 문장(「가정 하나만 역산한 값이 … 범위를 벗어나면, 그 가정 하나만으로는 이 가격을 설명할 수 없습니다」 — 서른 곳 같은 글)을
    # 표 제목으로 바꿨다. 판정은 표의 「판정」 칸과 표 아래 결론 문장이 쓴다
    L = ["### 두 가정을 함께 풀기", "", "**표. 한 가정을 범위 끝에 두고 둘째 가정을 다시 푼 값**", ""]
    L += _표(["범위 끝에 둔 가정", "둔 값", "다시 푼 가정", "이 가격에 필요한 값", "그 가정의 범위", "판정"], 표, ["l", "r", "l", "r", "r", "l"])
    L += ["", "그 가정을 범위의 두 끝 가운데 이 가격에 가까워지는 쪽의 끝값으로 두고, 주당가치가 이 가격과 같아지도록 둘째 가정을 역산한 값입니다. "
          "다른 가정은 채택값을 유지했습니다.", ""]                 # 레터 v27 — 표 주석
    안 = 두변수안(맥)
    if 안:
        L += ["범위 안에서 이 가격이 성립하는 조합이 있습니다. %s %s 두고 %s %s 두면 주당가치가 이 가격과 같아집니다." % (
            을(안["A"]["이름"]), 으로(_끝글(맥, 안["끝"])), 을(안["B"]["이름"]), 으로(맥.수(안["키"], 안["B"]["꼴"]))), ""]
    else:
        L += ["두 가정을 함께 범위의 끝값까지 바꿔도 범위 안에서는 주당가치가 이 가격과 같아지지 않습니다.", ""]
    return L


def 보수성절(맥):
    """평가값과 종가의 차이가 문턱을 넘을 때 — 민감도 표(표 Ⅲ)의 손잡이마다 폭 끝 가운데 종가 쪽 끝의 주당가치."""
    if not 반대논거필요(맥) or not 맥.민 or not 맥.민.get("표3"):
        return []
    p = _n(맥.값(맥.종가키))
    v = _n(맥.값("R:기준:2.DCF:68"))
    아래 = p < v
    표 = []
    for i, r in enumerate(맥.민["표3"]):
        쪽들 = [k for k in ("하", "상") if _n(r.get(k)) is not None]
        if not 쪽들:
            continue
        쪽 = min(쪽들, key=lambda k: _n(r[k])) if 아래 else max(쪽들, key=lambda k: _n(r[k]))
        if (아래 and _n(r[쪽]) >= v) or (not 아래 and _n(r[쪽]) <= v):
            continue
        h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
        꼴 = 손잡이꼴(h, 맥)
        값키 = "민:표3:%d:%s값" % (i, 쪽)
        표.append([손잡이이름(h, 맥), 맥.수("민:표3:%d:기준값" % i, 꼴) if _n(r.get("기준값")) is not None else "—",
                  맥.수(값키, 꼴) if _n(r.get(쪽 + "값")) is not None else "—", _표3칸(맥, i, 쪽)])
    if not 표:
        return []
    L = ["### 보수성 점검 : 가정마다 이 가격 쪽 끝으로 옮긴 값", "",
         # 1.1.21 — 도구 문턱(「그 차이가 30%를 넘습니다」)을 독자에게 설명하지 않는다 — 차이의 크기와 방향만(원칙 3 · 6)
         "기준 시나리오 주당가치는 %s보다 %s. 그래서 가정마다 변동 범위에서 이 가격에 가까운 쪽 끝값을 적용한 주당가치도 계산했습니다." % (
             종가말(맥), 맥.식(["÷", ["−", "R:기준:2.DCF:68", 맥.종가키], 맥.종가키], "증1:높습니다/낮습니다")), ""]
    L += _표(["가정", "채택", "이 가격 쪽 끝", "그때 주당가치 (기준 대비)"], 표, ["l", "r", "r", "r"])
    L += ["", "가정을 하나씩 바꾼 결과이며, 다른 가정은 채택값을 유지했습니다.", ""]       # 레터 v27 — 표 주석
    return L


def 반대논거절(맥):
    """원고 `Narrative.반대논거`[{논거, 근거, 출처, 바꿈 | (가정, 방식, 값), 바꾼값글}] → 표(주당가치는 장부 키 「반:i」 로 엔진이 셈한다).
    1.1.19 — 결합 줄(다른 논거 둘 이상의 바꿈을 모두 담은 줄 · 원고의 「세 논거를 함께」)은 논거 줄로 싣지 않는다 — 끝 줄 「위 논거가 함께 맞을 때」 가
    그 자리다. 결합 줄 판정 · 논거 목록 · 함께 맞을 때의 키는 3분 레터 · 1절 문장과 같은 함수를 쓴다(`레터이야기.반대결합줄` · `반대논거들` · `반대함께키`
    — `반:i` 의 i 는 원래 목록의 차례)."""
    import 레터 as _L                                       # noqa: PLC0415
    전목 = ((맥.가정.get("Narrative") or {}).get("반대논거")) if isinstance(맥.가정.get("Narrative"), dict) else None
    전목 = 전목 if isinstance(전목, list) else []
    목 = 레터이야기.반대논거들(전목)
    결 = sorted(레터이야기.반대결합줄(전목))
    if not 목:
        return []
    for j in 결:
        맥.알림.append("Narrative.반대논거[%d] — 다른 논거의 바꿈을 모두 담은 결합 줄이라 논거로 세지 않았다(표의 「위 논거가 함께 맞을 때」 줄이 그 판이다)"
                     " — 원고는 결합 줄을 쓰지 않는다" % j)
    표 = []
    for i, x in 목:
        try:
            _L.반대바꿈(x)
        except Exception as e:                               # noqa: BLE001
            맥.알림.append("Narrative.반대논거[%d] — %s" % (i, e))
            continue
        표.append([맥.원고글(x.get("논거") or "", "Narrative.반대논거[%d].논거" % i), 맥.원고글(x.get("근거") or "—", "Narrative.반대논거[%d].근거" % i),
                  맥.원고글(x.get("바꾼값글") or x.get("가정글") or "—", "Narrative.반대논거[%d].바꾼값글" % i),
                  "%s (%s)" % (맥.수("반:%d" % i, "주당"), 맥.식(["괴리", "반:%d" % i, "R:기준:2.DCF:68"], "증1"))])
    if not 표:
        return []
    if len(표) >= 2:                                         # 1.1.4(D) — 논거를 함께 맞을 때의 판(따로 셈한 판만 있으면 「모두 맞으면 얼마인가」 가 비었다)
        합키 = 레터이야기.반대함께키(전목)
        if 합키:
            표.append(["위 논거가 함께 맞을 때", "—", "위 바뀌는 가정을 모두 함께", "%s (%s)" % (맥.수(합키, "주당"), 맥.식(["괴리", 합키, "R:기준:2.DCF:68"], "증1"))])
        else:
            맥.알림.append("Narrative.반대논거 — 결합 줄이 논거 일부만 묶어 「위 논거가 함께 맞을 때」 줄을 싣지 않았다(결합 줄을 지우면 레터가 논거 전부를 함께 셈한다)")
    L = ["### 반대 논거 : 시장 쪽 논거와 그때의 주당가치", "",
         "이 평가와 반대되는 결론을 뒷받침하는 논거 가운데 근거가 있는 것을 골라, 그 논거가 맞을 때 달라지는 가정과 그때의 주당가치를 계산했습니다. "
         "다른 가정은 채택값을 유지했습니다.", ""]
    L += _표(["논거", "근거 자료", "바뀌는 가정", "그때 주당가치 (기준 대비)"], 표, ["l", "l", "l", "r"])
    L.append("")
    return L


def 사이기간절(맥):
    """Q27 — 원고 `관측.사이기간`(재무 자료 기준일과 평가기준일 사이의 사건 · 대조) → 표. 없으면 빈 목록."""
    import 레터원고 as W                                     # noqa: PLC0415
    import 레터갭 as _갭                                     # noqa: PLC0415 — 1.1.3(A1) 시장 변동(F 갭 · T 갭 · 지수)과 사건 표가 한 절에서 만난다
    시 = _갭.시장변동절(맥)
    v = (맥.가정.get("관측") or {}).get("사이기간")
    사 = [x for x in ((v or {}).get("사건") or []) if isinstance(x, dict)] if isinstance(v, dict) else []
    if not 사:
        return (["### 재무 자료 기준일과 평가기준일 사이의 시장", ""] + 시) if 시 else []
    변 = W.사이주가변화(맥)
    경 = importlib.import_module("기준일").자료경계(맥.가정)
    L = ["### 재무 자료 기준일과 평가기준일 사이의 사건", ""] + 시
    # 1.1.21 — 시장 변동 문단이 이미 이 회사 주가의 변화를 말했으면 같은 사실(「… 종가까지 주가는 36.1% 내렸습니다」 — 마침표도 없었다)을 다시 싣지 않는다
    주가말 = any("이 회사 주가는" in x for x in 시)
    지수말 = any(" 지수는 " in x for x in 시)
    if 변 is not None and not 주가말:                         # 레터 v27 — 증감 방향은 부호로 낱말을 고른다(원칙 6 · 「움직였다」 금지)
        import 어투 as _어                                    # noqa: PLC0415
        방 = _어.방향(round(변, 3), "올랐습니다", "내렸습니다")
        L += [("%s 종가에서 %s 종가까지 주가는 %s %s." % (날짜말(경["F"]), 날짜말(경["T"]), 맥.수("상:%r" % abs(변), "퍼1"), 방)) if 방 else
              "%s 종가와 %s 종가는 같았습니다." % (날짜말(경["F"]), 날짜말(경["T"])), ""]
    L += ["**표. 재무 자료 기준일과 평가기준일 사이의 사건과 입력값에 미친 영향**", ""]
    L += _표(["날짜", "사건", "출처", "이 평가의 입력에 미친 영향", "반영"],          # 1.1.4 — 「에 닿는 길」 은 문장검수 비유어(초안이 서지 않던 자리)
            [[맥.원고글("%s" % x.get("날짜")), 맥.원고글(x.get("사건") or "—"), 맥.원고글(x.get("출처") or "—"), 맥.원고글(x.get("입력영향") or "—"),
              맥.원고글(("%s" % x.get("반영")) if not isinstance(x.get("반영"), bool) else ("예" if x["반영"] else "아니오"))] for x in 사],
            ["l", "l", "l", "l", "l"])
    L.append("")
    대 = dict(v.get("대조")) if isinstance(v.get("대조"), dict) else {}
    if 지수말:                                                # 1.1.21 — 시장 변동 문단이 지수 변화를 말했으면 원고 대조의 지수 칸은 되풀이다(동종 회사만 남긴다)
        대.pop("지수", None)
    if 대.get("지수") or 대.get("동종"):
        _N = importlib.import_module("레터이야기")          # 1.1.4(R21) — 대조 칸도 장부 키(「{키|꼴}」)를 편다
        출 = _N.펴기(맥, 대.get("출처") or "", "관측.사이기간.대조.출처")
        L += ["재무 자료 기준일부터 평가기준일까지 %s%s%s." % (     # 1.1.21 — 「같은 기간」 은 표 뒤라 가리킬 기간이 없었다
            ("시장 지수는 %s" % _N.펴기(맥, "%s" % 대["지수"], "관측.사이기간.대조.지수")) if 대.get("지수") else "",
            ((" · 동종 회사는 %s" if 대.get("지수") else "동종 회사는 %s") % _N.펴기(맥, "%s" % 대["동종"], "관측.사이기간.대조.동종"))
            if 대.get("동종") else "",
            ("(%s)" % 출) if 출 else ""), ""]
    return L


def 역산넓힘(맥):
    """역산 절 끝에 붙는 1.1.2 소절 — 두 변수 · 보수성 · 반대 논거 · 사이 기간 사건(서지 않는 것은 빈 목록) ·
    1.1.3 — 범위 밖 · 배수 대조 · 시나리오 폭(`레터갭.갭절`) · 지주 할인 보조 시나리오(`레터갭.지주절`)."""
    import 레터갭 as _갭                                     # noqa: PLC0415
    import 레터안정 as _안                                    # noqa: PLC0415 — 1.1.5 공시된 적자 부문(모델 밖 가치의 별도 줄)
    import 레터레짐 as _레                                  # noqa: PLC0415 — 1.1.6 선택 표 「레짐 기대값」(선언이 있을 때만)
    return 두변수절(맥) + 보수성절(맥) + 반대논거절(맥) + _레.레짐절(맥) + 사이기간절(맥) + _갭.갭절(맥) + _갭.지주절(맥) + _안.적자부문절(맥)



def 부록B있음(맥):
    """부록 B 에 대안 사양 줄이 서나(가정 · 레터부록의 「자본비용.대안」 이 하나 이상)."""
    try:
        import 자본비용옮기기 as _자본                          # noqa: PLC0415
        입, _출, _알 = _자본.읽기(맥.가정, 맥.부록)
    except Exception:                                        # noqa: BLE001
        return False
    return isinstance(입, dict) and bool([x for x in 입.get("대안") or [] if isinstance(x, dict)])


def 부록G있음(맥):
    """부록 G 에 자료 줄이 서나(레터부록 「기준일뒤자료」 가 비지 않은 목록)."""
    v = (맥.부록 or {}).get("기준일뒤자료") if isinstance(맥.부록, dict) else None
    return isinstance(v, list) and bool(v)


def 피어회사표(맥):
    """1.1.2 — 할인율 절의 회사별 Peer 표. 재료 `유사기업βU`(C2 조립기의 `_raw/peers/βU_<표본>.json` 「표」 · 「본값」)에서 회사마다
    사업 접점(슬롯) · Levered Beta · 부채 ÷ 자기자본 · 현금 비중 · Unlevered Beta · 본값 표본 채택 여부와 제외 까닭을 싣는다. 숫자는 장부 키 「파일:유사기업βU:표:i:…」."""
    d = (맥.원.get("파일") or {}).get("유사기업βU") or {}
    표 = d.get("표") if isinstance(d.get("표"), list) else []
    if not 표:
        return []
    본 = set()
    for v in (d.get("본값") or {}).values():
        if isinstance(v, dict) and isinstance(v.get("본값"), dict):
            본 |= {("%s" % t) for t in v["본값"].get("티커") or []}
            break
    K = "파일:유사기업βU:표:%d:%s"
    줄들 = []
    for i, x in enumerate(표):
        if not isinstance(x, dict):
            continue
        이름 = ("%s" % (x.get("회사명") or x.get("티커") or "—")).strip()

        def 칸(k, 꼴, i=i, x=x):
            return 맥.수(K % (i, k), 꼴) if isinstance(x.get(k), (int, float)) and not isinstance(x.get(k), bool) else "—"
        de = "DE_본" if isinstance(x.get("DE_본"), (int, float)) else "DE"
        현 = "현금비중_본" if isinstance(x.get("현금비중_본"), (int, float)) else "현금비중"
        bu = "βU_본" if isinstance(x.get("βU_본"), (int, float)) else "βU"
        채 = ("%s" % (x.get("티커") or "")) in 본 or 이름 in 본
        제 = x.get("본값제외")
        제글 = (제 if isinstance(제, str) else "; ".join("%s" % y for y in 제)) if 제 else ""
        예비 = x.get("핵심") is False or ("%s" % (x.get("구분") or "")) == "예비"
        if 제글:                                             # 1.1.4 — 조립기 사유 글은 저자층이다. 독자 글로 옮기고, 본문 검수에 걸리면 빈칸 대신 일반 사유
            import βU본값 as _본                              # noqa: PLC0415
            제글 = _본.독자사유(제글)
            if importlib.import_module("레터").원고검사(제글):
                제글 = "본값 제외 규칙(회귀 품질 · 자본구조 · 자료) 해당"
        까 = "채택" if 채 else ("제외 — %s" % 맥.원고글(제글, "파일:유사기업βU.본값제외", 부록=True) if 제글 else
                              ("제외 — 예비 표본(최종 값은 핵심 표본으로 산정)" if 예비 else "제외 — 최종 표본 밖"))
        줄들.append([이름, 맥.원고글("%s" % (x.get("슬롯") or "—"), "파일:유사기업βU.슬롯", 부록=True), 칸("βL", "지수3"), 칸(de, "배"), 칸(현, "퍼1"),
                   칸(bu, "지수3"), 까])
    if not 줄들:
        return []
    n채 = sum(1 for r in 줄들 if r[-1] == "채택")
    L = ["Peer group 후보 %d곳 가운데 %d곳을 최종 표본으로 채택했습니다." % (len(줄들), n채), "",
         "**표. 후보 회사별 베타와 자본구조, 채택하지 않은 사유**", ""]              # 레터 v27 — 표 제목
    L += _표(["회사", "사업 접점", "Levered Beta", "부채 ÷ 자기자본", "현금 비중", "Unlevered Beta", "채택 여부와 사유"], 줄들, ["l", "l", "r", "r", "r", "r", "l"])
    L.append("")
    return L


def 갭문장(맥, 본편=False):
    """1.1.2(Q7 · Q22 · CT24) — 종가가 낙관 시나리오보다 높을 때의 갭 문장 한 곳(3분 레터 · 본편 1절이 같은 함수). 기준과의 차이와 낙관으로도 남는 차이를
    갈라 적고, 그 몫을 공시 밖 사업으로 통째로 돌리지 않는다 — 보수성 점검 · 반대 논거 · 공시 밖 사업의 크기는 역산 절에서 함께 본다."""
    종, 기, 낙 = 맥.종가키, "R:기준:2.DCF:68", "R:낙관:2.DCF:68"
    # 1.1.21 — 「이 차이를 … 무엇으로 설명할 수 있는지 분석했습니다(15절)」 는 문서 안내(원칙 3 · 서른 곳 같은 글)라 지웠다. `본편` 은 옛 부름을 받으려고 남긴다
    return "%s 기준 시나리오 주당가치의 차이는 그 주가의 %s이고, 낙관 시나리오 주당가치와의 차이는 %s." % (
        과(종가말(맥)), 맥.식(["÷", ["−", 종, 기], 종], "퍼0"), 입니다(맥.식(["÷", ["−", 종, 낙], 종], "퍼0")))



